import React, { useState, useRef, useCallback } from 'react';
import { Calendar, ChevronLeft, ChevronRight } from 'lucide-react';

const formatDate = (date) => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

const DateRangeFilter = ({ onChange }) => {
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [preset, setPreset] = useState('all');

  const applyPreset = useCallback((presetKey) => {
    setPreset(presetKey);
    if (presetKey === 'all') {
      setStartDate('');
      setEndDate('');
      if (onChange) onChange({ startDate: '', endDate: '', preset: 'all' });
      return;
    }
    const now = new Date();
    let start, end;
    switch (presetKey) {
      case 'today': start = new Date(now.getFullYear(), now.getMonth(), now.getDate()); end = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59); break;
      case 'yesterday': start = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1); end = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1, 23, 59, 59); break;
      case 'thisWeek': { const d = now.getDay(); const diff = d === 0 ? 6 : d - 1; start = new Date(now.getFullYear(), now.getMonth(), now.getDate() - diff); end = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59); break; }
      case 'lastWeek': { const le = new Date(now.getFullYear(), now.getMonth(), now.getDate() - now.getDay()); const ls = new Date(le); ls.setDate(le.getDate() - 6); start = new Date(ls.getFullYear(), ls.getMonth(), ls.getDate()); end = new Date(le.getFullYear(), le.getMonth(), le.getDate(), 23, 59, 59); break; }
      case 'thisMonth': start = new Date(now.getFullYear(), now.getMonth(), 1); end = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59); break;
      case 'lastMonth': start = new Date(now.getFullYear(), now.getMonth() - 1, 1); end = new Date(now.getFullYear(), now.getMonth(), 0, 23, 59, 59); break;
      case 'last7days': start = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 6); end = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59); break;
      case 'last30days': start = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 29); end = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59); break;
      default: return;
    }
    const s = formatDate(start); const e = formatDate(end);
    setStartDate(s); setEndDate(e);
    if (onChange) onChange({ startDate: s, endDate: e, preset: presetKey });
  }, [onChange]);

  const navigateWeek = useCallback((dir) => {
    const c = new Date(startDate);
    c.setDate(c.getDate() + (dir === 'prev' ? -7 : 7));
    const s = formatDate(c); const e = formatDate(new Date(c.getTime() + 6 * 86400000));
    setStartDate(s); setEndDate(e); setPreset('custom');
    if (onChange) onChange({ startDate: s, endDate: e, preset: 'custom' });
  }, [startDate, onChange]);

  const handleDateChange = useCallback((field, value) => {
    if (field === 'start') setStartDate(value); else setEndDate(value);
    const s = field === 'start' ? value : startDate;
    const e = field === 'end' ? value : endDate;
    if (s && e) { setPreset('custom'); if (onChange) onChange({ startDate: s, endDate: e, preset: 'custom' }); }
  }, [startDate, endDate, onChange]);

  const presets = [
    { key: 'all', label: 'Todos' },
    { key: 'today', label: 'Hoje' }, { key: 'yesterday', label: 'Ontem' },
    { key: 'thisWeek', label: 'Esta semana' }, { key: 'lastWeek', label: 'Semana passada' },
    { key: 'last7days', label: 'Últimos 7 dias' }, { key: 'thisMonth', label: 'Este mês' },
    { key: 'lastMonth', label: 'Mês passado' }, { key: 'last30days', label: 'Últimos 30 dias' },
  ];

  return (
    <div style={{ background: 'white', borderRadius: '0.75rem', padding: '1rem', marginBottom: '1.5rem', boxShadow: '0 1px 3px rgba(0,0,0,0.05)' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '0.75rem' }}>
        <Calendar size={18} style={{ color: '#64748b' }} />
        <span style={{ fontWeight: 600, fontSize: '0.875rem', color: '#1e293b' }}>Período</span>
      </div>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.5rem', marginBottom: '0.75rem' }}>
        {presets.map(p => (
          <button key={p.key} onClick={() => applyPreset(p.key)} style={{ padding: '0.375rem 0.75rem', borderRadius: '0.375rem', border: preset === p.key ? '2px solid #2563eb' : '1px solid #e2e8f0', background: preset === p.key ? '#eff6ff' : 'white', color: preset === p.key ? '#2563eb' : '#64748b', cursor: 'pointer', fontSize: '0.75rem', fontWeight: preset === p.key ? 600 : 400 }}>
            {p.label}
          </button>
        ))}
      </div>
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', flexWrap: 'wrap' }}>
        <button onClick={() => navigateWeek('prev')} style={{ padding: '0.375rem', borderRadius: '0.375rem', border: '1px solid #e2e8f0', background: 'white', cursor: 'pointer' }}><ChevronLeft size={16} /></button>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <input type="date" value={startDate} onChange={(e) => handleDateChange('start', e.target.value)} style={{ padding: '0.5rem', borderRadius: '0.375rem', border: '1px solid #e2e8f0', fontSize: '0.8125rem' }} />
          <span style={{ color: '#64748b', fontSize: '0.8125rem' }}>até</span>
          <input type="date" value={endDate} onChange={(e) => handleDateChange('end', e.target.value)} style={{ padding: '0.5rem', borderRadius: '0.375rem', border: '1px solid #e2e8f0', fontSize: '0.8125rem' }} />
        </div>
        <button onClick={() => navigateWeek('next')} style={{ padding: '0.375rem', borderRadius: '0.375rem', border: '1px solid #e2e8f0', background: 'white', cursor: 'pointer' }}><ChevronRight size={16} /></button>
      </div>
    </div>
  );
};

export default DateRangeFilter;

import React, { useState, useEffect, useRef } from 'react';
import { Bell, Check, Package, DollarSign, AlertCircle, X, UserPlus } from 'lucide-react';
import api from '@/lib/api';

const NotificationBell = () => {
  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [pendingCount, setPendingCount] = useState(0);
  const [isOpen, setIsOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const dropdownRef = useRef(null);

  // Verificar se é admin
  const user = JSON.parse(localStorage.getItem('user') || '{}');
  const isAdmin = user?.user_type === 'ADMIN';

  useEffect(() => {
    loadNotifications();
    if (isAdmin) loadPendingUsers();
    // Poll a cada 30 segundos
    const interval = setInterval(() => {
      loadNotifications();
      if (isAdmin) loadPendingUsers();
    }, 30000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const loadNotifications = async () => {
    try {
      const response = await api.get('/api/user/notifications');
      const newNotifications = response.data.notifications || [];
      const newUnread = response.data.unread_count || 0;
      
      // Toca som se há novas notificações não lidas
      if (newUnread > unreadCount && unreadCount > 0) {
        playNotificationSound();
      }
      
      setNotifications(newNotifications);
      setUnreadCount(newUnread);
    } catch (err) {
      // Silently fail - not critical
    }
  };

  const loadPendingUsers = async () => {
    try {
      const response = await api.get('/api/admin/pending-users');
      const users = response.data.users || [];
      const prevCount = pendingCount;
      setPendingCount(users.length);
      // Toca som se há novos pendentes
      if (users.length > prevCount && prevCount > 0) {
        playNotificationSound();
      }
    } catch (err) {
      // Silently fail
    }
  };

  const playNotificationSound = () => {
    try {
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      const ctx = new AudioContext();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.frequency.value = 800;
      osc.type = 'sine';
      gain.gain.setValueAtTime(0.3, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.3);
      osc.start(ctx.currentTime);
      osc.stop(ctx.currentTime + 0.3);
      setTimeout(() => ctx.close(), 500);
    } catch (e) {
      // Silently fail
    }
  };

  const markAsRead = async (notificationId) => {
    try {
      await api.put(`/api/user/notifications/${notificationId}/read`);
      setNotifications(prev =>
        prev.map(n => n.id === notificationId ? { ...n, is_read: true } : n)
      );
      setUnreadCount(prev => Math.max(0, prev - 1));
    } catch (err) {
      console.error('Erro ao marcar notificação:', err);
    }
  };

  const markAllAsRead = async () => {
    try {
      const unreadIds = notifications.filter(n => !n.is_read).map(n => n.id);
      // Usar allSettled para não falhar tudo se uma request der erro
      await Promise.allSettled(unreadIds.map(id => api.put(`/api/user/notifications/${id}/read`)));
      setNotifications(prev => prev.map(n => ({ ...n, is_read: true })));
      setUnreadCount(0);
    } catch (err) {
      console.error('Erro ao marcar todas:', err);
    }
  };

  const getNotificationIcon = (type) => {
    switch (type) {
      case 'NEW_ORDER': return <Package size={16} style={{ color: '#2563eb' }} />;
      case 'ORDER_STATUS': return <Package size={16} style={{ color: '#8b5cf6' }} />;
      case 'PAYMENT': return <DollarSign size={16} style={{ color: '#22c55e' }} />;
      case 'ALERT': return <AlertCircle size={16} style={{ color: '#f59e0b' }} />;
      default: return <Bell size={16} style={{ color: '#64748b' }} />;
    }
  };

  const formatTime = (dateStr) => {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    const now = new Date();
    const diff = now - date;

    if (diff < 60000) return 'Agora';
    if (diff < 3600000) return `${Math.floor(diff / 60000)}min atrás`;
    if (diff < 86400000) return `${Math.floor(diff / 3600000)}h atrás`;
    return date.toLocaleDateString('pt-BR');
  };

  const renderMessage = (message) => {
    if (!message) return null;
    const urlRegex = /(https?:\/\/[^\s]+)/g;
    const parts = message.split(urlRegex);
    return parts.map((part, i) => {
      if (part.match(urlRegex)) {
        return (
          <a key={i} href={part} target="_blank" rel="noopener noreferrer"
            onClick={e => e.stopPropagation()}
            style={{ color: '#2563eb', textDecoration: 'underline', wordBreak: 'break-all', fontWeight: 500 }}>
            {part.length > 50 ? part.substring(0, 50) + '...' : part}
          </a>
        );
      }
      return part;
    });
  };

  const handleNotificationClick = (notification) => {
    if (!notification.is_read) markAsRead(notification.id);
    // Se a mensagem contém um link, abrir em nova aba
    const urlMatch = notification.message?.match(/(https?:\/\/[^\s]+)/);
    if (urlMatch) {
      window.open(urlMatch[1], '_blank');
    }
  };

  const totalBadge = unreadCount + pendingCount;

  return (
    <div ref={dropdownRef} style={{ position: 'relative', zIndex: 100003 }}>
      {/* Bell Button */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        aria-label={`Notificações${totalBadge > 0 ? ` (${totalBadge} não lidas)` : ''}`}
        aria-expanded={isOpen}
        style={{
          position: 'relative', background: 'none', border: 'none',
          cursor: 'pointer', padding: '0.5rem', borderRadius: '0.5rem',
          color: '#64748b', transition: 'all 0.2s'
        }}
        onMouseEnter={e => e.currentTarget.style.background = '#f1f5f9'}
        onMouseLeave={e => e.currentTarget.style.background = 'none'}
      >
        <Bell size={20} />
        {totalBadge > 0 && (
          <span style={{
            position: 'absolute', top: '2px', right: '2px',
            background: pendingCount > 0 ? '#f59e0b' : '#ef4444', color: 'white',
            fontSize: '0.625rem', fontWeight: 700,
            width: '1.125rem', height: '1.125rem',
            borderRadius: '50%', display: 'flex',
            alignItems: 'center', justifyContent: 'center'
          }}>
            {totalBadge > 9 ? '9+' : totalBadge}
          </span>
        )}
      </button>

      {/* Dropdown */}
      {isOpen && (
        <div style={{
          position: 'absolute', top: '100%', right: 0,
          width: 'min(350px, calc(100vw - 2rem))', maxHeight: '450px',
          background: 'white', borderRadius: '0.75rem',
          boxShadow: '0 10px 40px rgba(0,0,0,0.15)',
          border: '1px solid #e2e8f0',
          zIndex: 100002,
          overflow: 'hidden',
          marginTop: '0.5rem'
        }}>
          {/* Header */}
          <div style={{
            padding: '1rem 1rem 0.75rem',
            borderBottom: '1px solid #f1f5f9',
            display: 'flex', justifyContent: 'space-between', alignItems: 'center'
          }}>
            <h3 style={{ fontSize: '0.9375rem', fontWeight: 600, color: '#1e293b' }}>
              Notificações
            </h3>
            {unreadCount > 0 && (
              <button
                onClick={markAllAsRead}
                style={{
                  background: 'none', border: 'none',
                  color: '#2563eb', fontSize: '0.75rem',
                  fontWeight: 500, cursor: 'pointer'
                }}
              >
                Marcar todas como lidas
              </button>
            )}
          </div>

          {/* Pendentes de aprovação (admins only) */}
          {isAdmin && pendingCount > 0 && (
            <div
              onClick={() => { window.location.href = '/admin'; setIsOpen(false); }}
              style={{
                padding: '0.75rem 1rem',
                background: '#fffbeb',
                borderBottom: '1px solid #fde68a',
                display: 'flex', alignItems: 'center', gap: '0.5rem',
                cursor: 'pointer', transition: 'background 0.15s'
              }}
              onMouseEnter={e => e.currentTarget.style.background = '#fef3c7'}
              onMouseLeave={e => e.currentTarget.style.background = '#fffbeb'}
            >
              <div style={{
                width: '2rem', height: '2rem', borderRadius: '50%',
                background: '#f59e0b', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0
              }}>
                <UserPlus size={14} style={{ color: 'white' }} />
              </div>
              <div style={{ flex: 1 }}>
                <p style={{ fontSize: '0.8125rem', fontWeight: 600, color: '#92400e' }}>
                  {pendingCount} cadastro(s) pendente(s)
                </p>
                <p style={{ fontSize: '0.6875rem', color: '#b45309' }}>
                  Toque para aprovar ou rejeitar
                </p>
              </div>
            </div>
          )}

          {/* Lista */}
          <div style={{ maxHeight: '350px', overflowY: 'auto' }}>
            {notifications.length === 0 ? (
              <div style={{
                padding: '2rem', textAlign: 'center',
                color: '#64748b', fontSize: '0.875rem'
              }}>
                <Bell size={32} style={{ marginBottom: '0.5rem', opacity: 0.5 }} />
                <p>Nenhuma notificação</p>
              </div>
            ) : (
              notifications.slice(0, 20).map(notification => (
                <div
                  key={notification.id}
                  onClick={() => handleNotificationClick(notification)}
                  style={{
                    padding: '0.875rem 1rem',
                    borderBottom: '1px solid #f8fafc',
                    display: 'flex', gap: '0.75rem',
                    cursor: 'pointer',
                    background: notification.is_read ? 'white' : '#f8fafc',
                    transition: 'background 0.2s'
                  }}
                  onMouseEnter={e => e.currentTarget.style.background = '#f1f5f9'}
                  onMouseLeave={e => e.currentTarget.style.background = notification.is_read ? 'white' : '#f8fafc'}
                >
                  <div style={{
                    width: '2rem', height: '2rem',
                    borderRadius: '50%',
                    background: notification.is_read ? '#f1f5f9' : '#eff6ff',
                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                    flexShrink: 0
                  }}>
                    {getNotificationIcon(notification.type)}
                  </div>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <p style={{
                      fontSize: '0.8125rem', fontWeight: notification.is_read ? 400 : 600,
                      color: '#1e293b', marginBottom: '0.25rem',
                      overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap'
                    }}>
                      {notification.title || 'Notificação'}
                    </p>
                    <p style={{
                      fontSize: '0.75rem', color: '#64748b',
                      wordBreak: 'break-all'
                    }}>
                      {renderMessage(notification.message)}
                    </p>
                    <p style={{ fontSize: '0.6875rem', color: '#64748b', marginTop: '0.25rem' }}>
                      {formatTime(notification.created_at)}
                    </p>
                  </div>
                  {!notification.is_read && (
                    <div style={{
                      width: '0.5rem', height: '0.5rem',
                      borderRadius: '50%', background: '#2563eb',
                      flexShrink: 0, marginTop: '0.375rem'
                    }} />
                  )}
                </div>
              ))
            )}
          </div>

          {/* Footer */}
          {notifications.length > 0 && (
            <div style={{
              padding: '0.75rem', borderTop: '1px solid #f1f5f9',
              textAlign: 'center'
            }}>
              <button
                onClick={() => setIsOpen(false)}
                style={{
                  background: 'none', border: 'none',
                  color: '#64748b', fontSize: '0.8125rem',
                  cursor: 'pointer'
                }}
              >
                Fechar
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default NotificationBell;

import React, { useState, useEffect, useRef } from 'react';
import { Package, MapPin, DollarSign, Clock, CheckCircle, X, Navigation, Store } from 'lucide-react';
import api from '@/lib/api';
import { startSiren, stopSiren } from '@/lib/notify';
import { showToast } from '@/components/Toast';
import { offlineDB, isOnline } from '@/lib/offline';

const OrderOfferPopup = () => {
  const [offer, setOffer] = useState(null);
  const [isVisible, setIsVisible] = useState(false);
  const [isAccepting, setIsAccepting] = useState(false);
  const [timeLeft, setTimeLeft] = useState(60);
  const timerRef = useRef(null);
  const pollRef = useRef(null);

  useEffect(() => {
    // Verificar ofertas a cada 5 segundos
    checkForOffers();
    pollRef.current = setInterval(checkForOffers, 5000);

    return () => {
      if (pollRef.current) clearInterval(pollRef.current);
      if (timerRef.current) clearInterval(timerRef.current);
      stopSiren();
    };
  }, []);

  const checkForOffers = async () => {
    try {
      const token = localStorage.getItem('token');
      if (!token) return;

      // Verificar se o usuario e um entregador
      const userStr = localStorage.getItem('user');
      if (!userStr) return;
      const user = JSON.parse(userStr);
      if (user.user_type !== 'DRIVER') return;

      // Verificar se o entregador está online antes de buscar pedidos
      if (user.user_type === 'DRIVER') {
        const isOnline = user.driver?.is_online;
        if (isOnline === false) return;
      }

      const response = await api.get('/api/orders/available');
      const orders = response.data.orders || [];

      // Verificar se ha algum pedido oferecido para este entregador
      // (nao ha como saber pelo backend, entao mostramos qualquer pedido disponivel)
      if (orders.length > 0 && !isVisible) {
        const order = orders[0]; // Mostrar o primeiro pedido disponivel
        setOffer(order);
        setIsVisible(true);
        setTimeLeft(60);
        startSiren();

        // Iniciar contagem regressiva
        if (timerRef.current) clearInterval(timerRef.current);
        timerRef.current = setInterval(() => {
          setTimeLeft(prev => {
            if (prev <= 1) {
              handleDismiss();
              return 0;
            }
            return prev - 1;
          });
        }, 1000);
      }
    } catch (err) {
      // Silencioso
    }
  };

  const handleAccept = async () => {
    if (!offer || isAccepting) return;

    try {
      setIsAccepting(true);
      stopSiren();

      if (!isOnline()) {
        // Sem internet: salva na fila offline
        await offlineDB.addToQueue({ type: 'ACCEPT_ORDER', orderId: offer.id });
        showToast('Pedido salvo offline. Será aceito quando a internet voltar.', 'info');
      } else {
        // Com internet: envia direto
        await api.post(`/api/orders/${offer.id}/accept`);
      }

      setIsVisible(false);
      setOffer(null);
      if (timerRef.current) clearInterval(timerRef.current);
      window.location.href = `/delivery/${offer.id}`;
    } catch (err) {
      console.error('Erro ao aceitar pedido:', err);
      showToast(err.response?.data?.error || 'Erro ao aceitar pedido', 'error');
    } finally {
      setIsAccepting(false);
    }
  };

  const handleDismiss = () => {
    stopSiren();
    setIsVisible(false);
    setOffer(null);
    if (timerRef.current) clearInterval(timerRef.current);
  };

  if (!isVisible || !offer) return null;

  return (
    <div style={{
      position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.7)',
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      zIndex: 99999, padding: '1rem'
    }}>
      <div style={{
        background: 'white', borderRadius: '1rem', padding: '1.5rem',
        maxWidth: '400px', width: '100%', position: 'relative',
        animation: 'pulse 0.5s ease-in-out infinite alternate'
      }}>
        {/* Botao fechar */}
        <button
          onClick={handleDismiss}
          style={{
            position: 'absolute', top: '0.75rem', right: '0.75rem',
            background: 'none', border: 'none', cursor: 'pointer',
            color: '#94a3b8'
          }}
        >
          <X size={20} />
        </button>

        {/* Icone de alerta */}
        <div style={{
          width: '64px', height: '64px', borderRadius: '50%',
          background: '#fef3c7', display: 'flex', alignItems: 'center',
          justifyContent: 'center', margin: '0 auto 1rem',
          animation: 'bounce 0.5s ease-in-out infinite alternate'
        }}>
          <Package size={32} style={{ color: '#d97706' }} />
        </div>

        {/* Titulo */}
        <h2 style={{
          fontSize: '1.25rem', fontWeight: 700, color: '#1e293b',
          textAlign: 'center', marginBottom: '0.5rem'
        }}>
          Novo Pedido Disponivel!
        </h2>

        {/* Contagem regressiva */}
        <div style={{
          textAlign: 'center', marginBottom: '1rem',
          fontSize: '0.875rem', color: '#ef4444', fontWeight: 600
        }}>
          Tempo restante: {timeLeft}s
        </div>

        {/* Detalhes do pedido */}
        <div style={{
          background: '#f8fafc', borderRadius: '0.75rem',
          padding: '1rem', marginBottom: '1rem'
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '0.5rem' }}>
            <Store size={16} style={{ color: '#64748b' }} />
            <span style={{ fontSize: '0.875rem', fontWeight: 500, color: '#1e293b' }}>
              {offer.restaurant?.name || 'Restaurante'}
            </span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '0.5rem' }}>
            <MapPin size={16} style={{ color: '#64748b' }} />
            <span style={{ fontSize: '0.8125rem', color: '#64748b' }}>
              {offer.delivery_address?.street || 'Endereco de entrega'}
            </span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <DollarSign size={16} style={{ color: '#16a34a' }} />
            <span style={{ fontSize: '0.875rem', fontWeight: 600, color: '#16a34a' }}>
              R$ {(offer.delivery_fee || 0).toFixed(2)}
            </span>
          </div>
        </div>

        {/* Botoes */}
        <div style={{ display: 'flex', gap: '0.75rem' }}>
          <button
            onClick={handleDismiss}
            style={{
              flex: 1, padding: '0.75rem', borderRadius: '0.5rem',
              border: '1px solid #e2e8f0', background: 'white',
              color: '#64748b', cursor: 'pointer', fontSize: '0.875rem'
            }}
          >
            Rejeitar
          </button>
          <button
            onClick={handleAccept}
            disabled={isAccepting}
            style={{
              flex: 2, padding: '0.75rem', borderRadius: '0.5rem',
              border: 'none', background: '#16a34a', color: 'white',
              cursor: isAccepting ? 'not-allowed' : 'pointer',
              fontSize: '0.875rem', fontWeight: 600,
              display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem'
            }}
          >
            {isAccepting ? (
              'Aceitando...'
            ) : (
              <>
                <CheckCircle size={18} /> Aceitar Pedido
              </>
            )}
          </button>
        </div>
      </div>

      <style>{`
        @keyframes pulse {
          from { transform: scale(1); }
          to { transform: scale(1.02); }
        }
        @keyframes bounce {
          from { transform: translateY(0); }
          to { transform: translateY(-5px); }
        }
      `}</style>
    </div>
  );
};

export default OrderOfferPopup;

import React, { useEffect, useRef } from 'react';
import { Navigate } from 'react-router-dom';

const OwnDriverProtectedRoute = ({ children }) => {
  const token = localStorage.getItem('own_driver_token');
  const gpsHttpRef = useRef(null);
  const gpsBroadcastRef = useRef(null);
  
  // GPS persistente para entregadores próprios — funciona em TODAS as páginas
  // Supabase Broadcast a cada 2s (tempo real) + HTTP POST a cada 30s (persistência)
  useEffect(() => {
    if (!token) return;

    let driverId = null;
    let tenantId = null;
    let realtimeModule = null;

    // Carregar módulos e dados do entregador uma vez
    const init = async () => {
      try {
        realtimeModule = await import('@/lib/realtime');
        const m = await import('@/lib/api');
        const res = await m.default.get('/api/own-driver/profile', {
          headers: { Authorization: `Bearer ${token}` }
        });
        driverId = res.data?.id;
        tenantId = res.data?.tenant_id;
      } catch (e) { /* Ignorar erro */ }
    };

    const broadcast = () => {
      if (!navigator.geolocation) return;
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          if (realtimeModule?.isRealtimeAvailable() && driverId) {
            realtimeModule.sendGPS(driverId, pos.coords.latitude, pos.coords.longitude, tenantId, 'own');
          }
        },
        () => {},
        { enableHighAccuracy: true, timeout: 8000, maximumAge: 2000 }
      );
    };

    const persist = () => {
      if (!navigator.geolocation) return;
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          import('@/lib/api').then((m) => {
            m.default.post('/api/own-driver/location', {
              latitude: pos.coords.latitude,
              longitude: pos.coords.longitude
            }, { headers: { Authorization: `Bearer ${token}` } }).catch(() => {});
          }).catch(() => {});
        },
        () => {},
        { enableHighAccuracy: true, timeout: 10000, maximumAge: 15000 }
      );
    };

    init().then(() => {
      broadcast(); persist();
      gpsBroadcastRef.current = setInterval(broadcast, 2000);
      gpsHttpRef.current = setInterval(persist, 30000);
    });

    return () => {
      if (gpsBroadcastRef.current) clearInterval(gpsBroadcastRef.current);
      if (gpsHttpRef.current) clearInterval(gpsHttpRef.current);
    };
  }, [token]);

  if (!token) {
    return <Navigate to="/own-driver/login" replace />;
  }

  return children;
};

export default OwnDriverProtectedRoute;

import React, { useState, useEffect } from 'react';
import { ChevronDown, MapPin } from 'lucide-react';
import { useSquare } from '@/contexts/SquareContext';
import api from '@/lib/api';

const SquareSelector = () => {
  const { selectedSquare, setSelectedSquare, squares, setSquares } = useSquare();
  const [isOpen, setIsOpen] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadSquares();
  }, []);

  const loadSquares = async () => {
    try {
      const response = await api.get('/api/admin/squares');
      const squaresData = response.data.squares || [];
      setSquares(squaresData);

      // Se não tem praça selecionada e tem praças disponíveis, selecionar a primeira
      if (!selectedSquare && squaresData.length > 0) {
        setSelectedSquare(squaresData[0]);
      }
    } catch (err) {
      console.error('Erro ao carregar praças:', err);
    } finally {
      setLoading(false);
    }
  };

  if (loading || squares.length === 0) {
    return null;
  }

  // Se só tem uma praça, não mostrar seletor
  if (squares.length === 1) {
    return (
      <div style={{
        display: 'flex',
        alignItems: 'center',
        gap: '0.375rem',
        padding: '0.375rem 0.75rem',
        borderRadius: '0.5rem',
        background: '#f0fdf4',
        fontSize: '0.8125rem',
        color: '#16a34a'
      }}>
        <MapPin size={14} />
        {squares[0].name}
      </div>
    );
  }

  return (
    <div style={{ position: 'relative' }}>
      <button
        onClick={() => setIsOpen(!isOpen)}
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: '0.5rem',
          padding: '0.5rem 0.75rem',
          borderRadius: '0.5rem',
          border: '1px solid #e2e8f0',
          background: 'white',
          cursor: 'pointer',
          fontSize: '0.8125rem',
          color: '#374151',
          transition: 'all 0.15s',
          minWidth: '150px'
        }}
      >
        <MapPin size={14} style={{ color: '#2563eb' }} />
        <span style={{ flex: 1, textAlign: 'left' }}>
          {selectedSquare?.name || 'Selecionar praça'}
        </span>
        <ChevronDown size={14} style={{ 
          color: '#64748b',
          transform: isOpen ? 'rotate(180deg)' : 'rotate(0)',
          transition: 'transform 0.2s'
        }} />
      </button>

      {isOpen && (
        <>
          <div
            style={{
              position: 'fixed',
              inset: 0,
              zIndex: 99998
            }}
            onClick={() => setIsOpen(false)}
          />
          <div style={{
            position: 'absolute',
            top: '100%',
            left: 0,
            marginTop: '0.25rem',
            background: 'white',
            borderRadius: '0.5rem',
            boxShadow: '0 10px 25px rgba(0,0,0,0.1)',
            border: '1px solid #e2e8f0',
            zIndex: 99999,
            minWidth: '200px',
            maxHeight: '300px',
            overflow: 'auto'
          }}>
            <div style={{
              padding: '0.5rem',
              borderBottom: '1px solid #f1f5f9'
            }}>
              <p style={{
                fontSize: '0.6875rem',
                color: '#64748b',
                textTransform: 'uppercase',
                letterSpacing: '0.05em',
                padding: '0.25rem 0.5rem'
              }}>
                Selecionar Praça
              </p>
            </div>
            {squares.map(square => (
              <button
                key={square.id}
                onClick={() => {
                  setSelectedSquare(square);
                  setIsOpen(false);
                }}
                style={{
                  width: '100%',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '0.5rem',
                  padding: '0.625rem 0.75rem',
                  border: 'none',
                  background: selectedSquare?.id === square.id ? '#eff6ff' : 'transparent',
                  cursor: 'pointer',
                  fontSize: '0.8125rem',
                  color: selectedSquare?.id === square.id ? '#2563eb' : '#374151',
                  transition: 'background 0.15s'
                }}
                onMouseEnter={(e) => {
                  if (selectedSquare?.id !== square.id) {
                    e.currentTarget.style.background = '#f8fafc';
                  }
                }}
                onMouseLeave={(e) => {
                  if (selectedSquare?.id !== square.id) {
                    e.currentTarget.style.background = 'transparent';
                  }
                }}
              >
                <MapPin size={14} style={{ 
                  color: selectedSquare?.id === square.id ? '#2563eb' : '#64748b' 
                }} />
                <div style={{ flex: 1, textAlign: 'left' }}>
                  <p style={{ fontWeight: selectedSquare?.id === square.id ? 600 : 400 }}>
                    {square.name}
                  </p>
                  {square.city && (
                    <p style={{ fontSize: '0.6875rem', color: '#64748b' }}>
                      {square.city}/{square.state}
                    </p>
                  )}
                </div>
                {selectedSquare?.id === square.id && (
                  <div style={{
                    width: '6px',
                    height: '6px',
                    borderRadius: '50%',
                    background: '#2563eb'
                  }} />
                )}
              </button>
            ))}
          </div>
        </>
      )}
    </div>
  );
};

export default SquareSelector;

import React, { useState, useEffect, useCallback } from 'react';
import { CheckCircle, AlertCircle, Info, X } from 'lucide-react';

let toastId = 0;
let addToastFn = null;

export const showToast = (message, type = 'info', duration = 4000) => {
  if (addToastFn) {
    addToastFn(message, type, duration);
  }
};

const ToastContainer = () => {
  const [toasts, setToasts] = useState([]);

  const addToast = useCallback((message, type, duration) => {
    const id = ++toastId;
    setToasts(prev => [...prev, { id, message, type, duration }]);
    setTimeout(() => {
      setToasts(prev => prev.filter(t => t.id !== id));
    }, duration);
  }, []);

  useEffect(() => {
    addToastFn = addToast;
    return () => { addToastFn = null; };
  }, [addToast]);

  const removeToast = (id) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  const getIcon = (type) => {
    switch (type) {
      case 'success': return <CheckCircle size={18} />;
      case 'error': return <AlertCircle size={18} />;
      default: return <Info size={18} />;
    }
  };

  const getColors = (type) => {
    switch (type) {
      case 'success': return { bg: '#dcfce7', border: '#86efac', color: '#166534' };
      case 'error': return { bg: '#fef2f2', border: '#fecaca', color: '#dc2626' };
      default: return { bg: '#dbeafe', border: '#93c5fd', color: '#1d4ed8' };
    }
  };

  return (
    <div style={{
      position: 'fixed', top: '1rem', right: '1rem', zIndex: 99999,
      display: 'flex', flexDirection: 'column', gap: '0.5rem',
      maxWidth: '400px'
    }}>
      {toasts.map(toast => {
        const colors = getColors(toast.type);
        return (
          <div
            key={toast.id}
            style={{
              background: colors.bg,
              border: `1px solid ${colors.border}`,
              color: colors.color,
              padding: '0.875rem 1rem',
              borderRadius: '0.5rem',
              display: 'flex',
              alignItems: 'center',
              gap: '0.625rem',
              fontSize: '0.875rem',
              boxShadow: '0 4px 12px rgba(0,0,0,0.15)',
              animation: 'slideIn 0.3s ease-out',
              cursor: 'pointer'
            }}
            onClick={() => removeToast(toast.id)}
          >
            {getIcon(toast.type)}
            <span style={{ flex: 1 }}>{toast.message}</span>
            <X size={14} style={{ opacity: 0.6, flexShrink: 0 }} />
          </div>
        );
      })}
      <style>{`
        @keyframes slideIn {
          from { transform: translateX(100%); opacity: 0; }
          to { transform: translateX(0); opacity: 1; }
        }
      `}</style>
    </div>
  );
};

export default ToastContainer;

import React, { useState, useEffect } from 'react';
import { Trash2, RotateCcw, AlertCircle, CheckCircle, Loader2, X } from 'lucide-react';
import { adminService } from '@/lib/api';
import { showToast } from '@/components/Toast';

const TrashModal = ({ isOpen, onClose, onRestore, userType = null }) => {
  const [deletedUsers, setDeletedUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedUsers, setSelectedUsers] = useState([]);
  const [retentionDays, setRetentionDays] = useState(90);
  const [filterDays, setFilterDays] = useState('');
  const [processing, setProcessing] = useState(false);

  useEffect(() => {
    if (isOpen) {
      loadDeletedUsers();
      loadRetentionConfig();
    }
  }, [isOpen, filterDays]);

  const loadDeletedUsers = async () => {
    try {
      setLoading(true);
      const data = await adminService.getDeletedUsers(filterDays || null, userType);
      setDeletedUsers(data.users || []);
      setSelectedUsers([]);
    } catch (err) {
      showToast('Erro ao carregar lixeira', 'error');
    } finally {
      setLoading(false);
    }
  };

  const loadRetentionConfig = async () => {
    try {
      const data = await adminService.getRetentionConfig();
      setRetentionDays(data.retention_days || 90);
    } catch {}
  };

  const handleRestore = async (userId) => {
    try {
      setProcessing(true);
      await adminService.restoreUser(userId);
      showToast('Usuário restaurado com sucesso!', 'success');
      loadDeletedUsers();
      if (onRestore) onRestore();
    } catch (err) {
      showToast(err.response?.data?.error || 'Erro ao restaurar', 'error');
    } finally {
      setProcessing(false);
    }
  };

  const handlePermanentDelete = async (userId) => {
    if (!window.confirm('Tem certeza? Esta ação é IRREVERSÍVEL.')) return;
    try {
      setProcessing(true);
      await adminService.deleteUserPermanent(userId);
      showToast('Usuário excluído permanentemente', 'success');
      loadDeletedUsers();
    } catch (err) {
      showToast(err.response?.data?.error || 'Erro ao excluir', 'error');
    } finally {
      setProcessing(false);
    }
  };

  const handleBulkRestore = async () => {
    if (selectedUsers.length === 0) return;
    try {
      setProcessing(true);
      for (const userId of selectedUsers) {
        await adminService.restoreUser(userId);
      }
      showToast(`${selectedUsers.length} usuário(s) restaurado(s)!`, 'success');
      setSelectedUsers([]);
      loadDeletedUsers();
      if (onRestore) onRestore();
    } catch (err) {
      showToast('Erro ao restaurar usuários', 'error');
    } finally {
      setProcessing(false);
    }
  };

  const handleBulkDelete = async () => {
    if (selectedUsers.length === 0) return;
    if (!window.confirm(`Tem certeza que deseja excluir PERMANENTEMENTE ${selectedUsers.length} usuário(s)? Esta ação é IRREVERSÍVEL.`)) return;
    try {
      setProcessing(true);
      await adminService.cleanupDeletedUsers(selectedUsers);
      showToast(`${selectedUsers.length} usuário(s) excluído(s) permanentemente`, 'success');
      setSelectedUsers([]);
      loadDeletedUsers();
    } catch (err) {
      showToast(err.response?.data?.error || 'Erro ao excluir', 'error');
    } finally {
      setProcessing(false);
    }
  };

  const toggleSelect = (userId) => {
    setSelectedUsers(prev =>
      prev.includes(userId) ? prev.filter(id => id !== userId) : [...prev, userId]
    );
  };

  const toggleSelectAllOld = () => {
    const oldUsers = deletedUsers.filter(u => u.days_deleted >= retentionDays);
    const allSelected = oldUsers.every(u => selectedUsers.includes(u.id));
    if (allSelected) {
      setSelectedUsers(prev => prev.filter(id => !oldUsers.find(u => u.id === id)));
    } else {
      setSelectedUsers(prev => [...new Set([...prev, ...oldUsers.map(u => u.id)])]);
    }
  };

  const getTypeLabel = (type) => {
    const labels = { ADMIN: 'Admin', DRIVER: 'Entregador', CLIENT: 'Estabelecimento' };
    return labels[type] || type;
  };

  const getTypeColor = (type) => {
    const colors = { ADMIN: '#2563eb', DRIVER: '#0891b2', CLIENT: '#16a34a' };
    return colors[type] || '#64748b';
  };

  if (!isOpen) return null;

  return (
    <>
      <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', zIndex: 99999 }} onClick={onClose} />
      <div style={{
        position: 'fixed', top: '50%', left: '50%', transform: 'translate(-50%, -50%)',
        background: 'white', borderRadius: '0.75rem', width: '90%', maxWidth: '700px',
        maxHeight: '80vh', overflowY: 'auto',
        boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1)', zIndex: 100000
      }}>
        {/* Header */}
        <div style={{ padding: '1.5rem', borderBottom: '1px solid #f1f5f9', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <div style={{ width: '2.5rem', height: '2.5rem', borderRadius: '0.5rem', background: '#fef3c7', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <Trash2 size={20} style={{ color: '#d97706' }} />
            </div>
            <div>
              <h2 style={{ fontSize: '1.25rem', fontWeight: 700, color: '#1e293b' }}>Lixeira</h2>
              <p style={{ fontSize: '0.75rem', color: '#64748b' }}>{deletedUsers.length} usuário(s) excluído(s)</p>
            </div>
          </div>
          <button onClick={onClose} style={{ border: 'none', background: 'none', cursor: 'pointer', color: '#64748b', fontSize: '1.5rem' }}>×</button>
        </div>

        {/* Filtros */}
        <div style={{ padding: '1rem 1.5rem', borderBottom: '1px solid #f1f5f9', display: 'flex', gap: '0.75rem', alignItems: 'center', flexWrap: 'wrap' }}>
          <select value={filterDays} onChange={e => setFilterDays(e.target.value)}
            style={{ padding: '0.5rem 0.75rem', borderRadius: '0.5rem', border: '1.5px solid #e2e8f0', fontSize: '0.8125rem', background: 'white' }}>
            <option value="">Todos</option>
            <option value="30">Últimos 30 dias</option>
            <option value="60">Últimos 60 dias</option>
            <option value="90">Últimos 90 dias</option>
          </select>
          <div style={{ flex: 1 }} />
          {selectedUsers.length > 0 && (
            <div style={{ display: 'flex', gap: '0.5rem' }}>
              <button onClick={handleBulkRestore} disabled={processing}
                style={{ padding: '0.5rem 1rem', borderRadius: '0.5rem', border: 'none', background: '#16a34a', color: 'white', cursor: 'pointer', fontSize: '0.8125rem', fontWeight: 600, opacity: processing ? 0.7 : 1 }}>
                <RotateCcw size={14} style={{ marginRight: '0.25rem', verticalAlign: 'middle' }} />
                Restaurar ({selectedUsers.length})
              </button>
              <button onClick={handleBulkDelete} disabled={processing}
                style={{ padding: '0.5rem 1rem', borderRadius: '0.5rem', border: '1px solid #ef4444', background: 'white', color: '#ef4444', cursor: 'pointer', fontSize: '0.8125rem', fontWeight: 600, opacity: processing ? 0.7 : 1 }}>
                <Trash2 size={14} style={{ marginRight: '0.25rem', verticalAlign: 'middle' }} />
                Excluir ({selectedUsers.length})
              </button>
            </div>
          )}
        </div>

        {/* Aviso de retenção */}
        {deletedUsers.some(u => u.days_deleted >= retentionDays) && (
          <div style={{ margin: '1rem 1.5rem', padding: '0.75rem 1rem', background: '#fffbeb', border: '1px solid #fde68a', borderRadius: '0.5rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <AlertCircle size={16} style={{ color: '#d97706', flexShrink: 0 }} />
            <p style={{ fontSize: '0.8125rem', color: '#92400e', flex: 1 }}>
              Existem registros com mais de {retentionDays} dias. Considere limpar para liberar espaço.
            </p>
            <button onClick={toggleSelectAllOld}
              style={{ padding: '0.375rem 0.75rem', borderRadius: '0.375rem', border: '1px solid #d97706', background: 'white', color: '#d97706', cursor: 'pointer', fontSize: '0.75rem', fontWeight: 600, whiteSpace: 'nowrap' }}>
              Selecionar antigos
            </button>
          </div>
        )}

        {/* Lista */}
        <div style={{ padding: '0 1.5rem 1.5rem' }}>
          {loading ? (
            <div style={{ display: 'flex', justifyContent: 'center', padding: '3rem' }}>
              <Loader2 size={32} style={{ animation: 'spin 1s linear infinite', color: '#2563eb' }} />
            </div>
          ) : deletedUsers.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '3rem', color: '#64748b' }}>
              <Trash2 size={48} style={{ opacity: 0.3, marginBottom: '1rem' }} />
              <p>Lixeira vazia</p>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
              {deletedUsers.map(user => {
                const isOld = user.days_deleted >= retentionDays;
                const isSelected = selectedUsers.includes(user.id);
                return (
                  <div key={user.id} style={{
                    display: 'flex', alignItems: 'center', gap: '0.75rem',
                    padding: '0.75rem 1rem', background: isOld ? '#fffbeb' : '#f8fafc',
                    borderRadius: '0.5rem', border: `1px solid ${isOld ? '#fde68a' : '#e2e8f0'}`,
                    opacity: processing ? 0.7 : 1
                  }}>
                    <input type="checkbox" checked={isSelected} onChange={() => toggleSelect(user.id)}
                      style={{ cursor: 'pointer' }} />
                    <div style={{ flex: 1 }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                        <span style={{ fontWeight: 600, fontSize: '0.875rem', color: '#1e293b' }}>
                          {user.first_name} {user.last_name}
                        </span>
                        <span style={{
                          padding: '0.125rem 0.5rem', borderRadius: '9999px', fontSize: '0.6875rem', fontWeight: 600,
                          background: `${getTypeColor(user.user_type)}15`, color: getTypeColor(user.user_type)
                        }}>
                          {getTypeLabel(user.user_type)}
                        </span>
                        {isOld && (
                          <span style={{
                            padding: '0.125rem 0.5rem', borderRadius: '9999px', fontSize: '0.6875rem', fontWeight: 600,
                            background: '#fef3c7', color: '#92400e'
                          }}>
                            {user.days_deleted}d
                          </span>
                        )}
                      </div>
                      <p style={{ fontSize: '0.75rem', color: '#64748b', marginTop: '0.125rem' }}>
                        {user.email} • Excluído há {user.days_deleted} dias por {user.deleted_by_name}
                      </p>
                    </div>
                    <div style={{ display: 'flex', gap: '0.375rem' }}>
                      <button onClick={() => handleRestore(user.id)} disabled={processing}
                        title="Restaurar"
                        style={{ padding: '0.375rem', borderRadius: '0.375rem', border: 'none', background: '#dcfce7', color: '#16a34a', cursor: 'pointer', opacity: processing ? 0.5 : 1 }}>
                        <RotateCcw size={16} />
                      </button>
                      <button onClick={() => handlePermanentDelete(user.id)} disabled={processing}
                        title="Excluir permanentemente"
                        style={{ padding: '0.375rem', borderRadius: '0.375rem', border: 'none', background: '#fee2e2', color: '#dc2626', cursor: 'pointer', opacity: processing ? 0.5 : 1 }}>
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>

        <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
      </div>
    </>
  );
};

export default TrashModal;

