import React, { createContext, useContext, useReducer, useEffect } from 'react';
import { authService } from '@/lib/api';

// Estado inicial
const initialState = {
  user: null,
  token: null,
  isAuthenticated: false,
  isLoading: true,
  error: null,
};

// Actions
const AUTH_ACTIONS = {
  LOGIN_START: 'LOGIN_START',
  LOGIN_SUCCESS: 'LOGIN_SUCCESS',
  LOGIN_FAILURE: 'LOGIN_FAILURE',
  LOGOUT: 'LOGOUT',
  SET_LOADING: 'SET_LOADING',
  UPDATE_USER: 'UPDATE_USER',
  CLEAR_ERROR: 'CLEAR_ERROR',
};

// Reducer
const authReducer = (state, action) => {
  switch (action.type) {
    case AUTH_ACTIONS.LOGIN_START:
      return {
        ...state,
        isLoading: true,
        error: null,
      };
    case AUTH_ACTIONS.LOGIN_SUCCESS:
      return {
        ...state,
        user: action.payload.user,
        token: action.payload.token,
        isAuthenticated: true,
        isLoading: false,
        error: null,
      };
    case AUTH_ACTIONS.LOGIN_FAILURE:
      return {
        ...state,
        user: null,
        token: null,
        isAuthenticated: false,
        isLoading: false,
        error: action.payload,
      };
    case AUTH_ACTIONS.LOGOUT:
      return {
        ...state,
        user: null,
        token: null,
        isAuthenticated: false,
        isLoading: false,
        error: null,
      };
    case AUTH_ACTIONS.SET_LOADING:
      return {
        ...state,
        isLoading: action.payload,
      };
    case AUTH_ACTIONS.UPDATE_USER:
      return {
        ...state,
        user: action.payload,
      };
    case AUTH_ACTIONS.CLEAR_ERROR:
      return {
        ...state,
        error: null,
      };
    default:
      return state;
  }
};

// Context
const AuthContext = createContext();

// Provider
export const AuthProvider = ({ children }) => {
  const [state, dispatch] = useReducer(authReducer, initialState);

  // Carrega dados do localStorage na inicialização
  useEffect(() => {
    const loadStoredAuth = async () => {
      try {
        const token = localStorage.getItem('token');
        const user = localStorage.getItem('user');

        if (token && user) {
          // Verifica se o token ainda é válido
          const userData = await authService.getProfile();
          dispatch({
            type: AUTH_ACTIONS.LOGIN_SUCCESS,
            payload: {
              user: userData,
              token,
            },
          });
        } else {
          dispatch({ type: AUTH_ACTIONS.SET_LOADING, payload: false });
        }
      } catch (error) {
        // Token inválido, remove do localStorage
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        dispatch({ type: AUTH_ACTIONS.SET_LOADING, payload: false });
      }
    };

    loadStoredAuth();
  }, []);

  // Função de login
  const login = async (email, password, userType = null) => {
    dispatch({ type: AUTH_ACTIONS.LOGIN_START });
    
    try {
      const response = await authService.login(email, password, null, userType);

      // Se retornou múltiplas contas, propagar para o componente tratar
      if (response.multiple_accounts) {
        dispatch({ type: AUTH_ACTIONS.SET_LOADING, payload: false });
        throw { response: { status: 409, data: response } };
      }
      
      // Salva no localStorage
      localStorage.setItem('token', response.access_token);
      localStorage.setItem('user', JSON.stringify(response.user));

      dispatch({
        type: AUTH_ACTIONS.LOGIN_SUCCESS,
        payload: {
          user: response.user,
          token: response.access_token,
        },
      });

      // Registrar token FCM para push notifications (background, sem travar login)
      try {
        const { requestNotificationPermission } = await import('@/lib/firebase');
        const fcmToken = await requestNotificationPermission();
        if (fcmToken) {
          api.post('/api/driver/push-token', { token: fcmToken }).catch(() => {});
        }
      } catch (e) {
        // Push notification é opcional — não bloqueia login
      }

      return response;
    } catch (error) {
      const errorMessage = error.response?.data?.error || 'Erro ao fazer login';
      dispatch({
        type: AUTH_ACTIONS.LOGIN_FAILURE,
        payload: errorMessage,
      });
      throw error;
    }
  };

  // Função de registro
  const register = async (userData) => {
    dispatch({ type: AUTH_ACTIONS.LOGIN_START });
    
    try {
      const response = await authService.register(userData);
      
      // Salva no localStorage
      localStorage.setItem('token', response.access_token);
      localStorage.setItem('user', JSON.stringify(response.user));
      
      dispatch({
        type: AUTH_ACTIONS.LOGIN_SUCCESS,
        payload: {
          user: response.user,
          token: response.access_token,
        },
      });
      
      return response;
    } catch (error) {
      const errorMessage = error.response?.data?.error || 'Erro ao criar conta';
      dispatch({
        type: AUTH_ACTIONS.LOGIN_FAILURE,
        payload: errorMessage,
      });
      throw error;
    }
  };

  // Função de logout
  const logout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    dispatch({ type: AUTH_ACTIONS.LOGOUT });
  };

  // Função para atualizar dados do usuário
  const updateUser = (userData) => {
    localStorage.setItem('user', JSON.stringify(userData));
    dispatch({
      type: AUTH_ACTIONS.UPDATE_USER,
      payload: userData,
    });
  };

  // Função para limpar erro
  const clearError = () => {
    dispatch({ type: AUTH_ACTIONS.CLEAR_ERROR });
  };

  const value = {
    ...state,
    login,
    register,
    logout,
    updateUser,
    clearError,
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};

// Hook para usar o contexto
export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth deve ser usado dentro de um AuthProvider');
  }
  return context;
};

export default AuthContext;

import React, { createContext, useContext, useState, useEffect } from 'react';
import api from '@/lib/api';

const SquareContext = createContext();

export const useSquare = () => {
  const context = useContext(SquareContext);
  if (!context) {
    throw new Error('useSquare must be used within a SquareProvider');
  }
  return context;
};

export const SquareProvider = ({ children }) => {
  const [selectedSquare, setSelectedSquare] = useState(() => {
    const saved = localStorage.getItem('selectedSquare');
    return saved ? JSON.parse(saved) : null;
  });

  const [squares, setSquares] = useState([]);

  // Validar praça do localStorage contra o backend ao carregar (apenas para admins)
  useEffect(() => {
    const validateSquare = async () => {
      try {
        const user = JSON.parse(localStorage.getItem('user') || '{}');
        // Apenas admins precisam validar praças
        if (!user || user.user_type !== 'ADMIN') return;

        const res = await api.get('/api/admin/squares');
        const validSquares = res.data.squares || res.data || [];
        setSquares(validSquares);
        // Se a praça salva não existe mais na lista, limpar
        if (selectedSquare && validSquares.length > 0) {
          const stillValid = validSquares.some(s => s.id === selectedSquare.id);
          if (!stillValid) {
            setSelectedSquare(validSquares[0] || null);
          }
        }
      } catch (err) {
        // Se falhar, mantém o estado atual
      }
    };
    validateSquare();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  // Salvar no localStorage quando mudar
  useEffect(() => {
    if (selectedSquare) {
      localStorage.setItem('selectedSquare', JSON.stringify(selectedSquare));
    } else {
      localStorage.removeItem('selectedSquare');
    }
  }, [selectedSquare]);

  const value = {
    selectedSquare,
    setSelectedSquare,
    squares,
    setSquares,
    squareId: selectedSquare?.id || null
  };

  return (
    <SquareContext.Provider value={value}>
      {children}
    </SquareContext.Provider>
  );
};

export default SquareContext;

