            <MapPin size={14} style={{ color: '#16a34a', flexShrink: 0 }} />
            <span style={{ fontSize: '0.8125rem', color: '#475569', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
              {order.delivery_address?.street || 'Destino'}
              {order.delivery_address?.neighborhood ? `, ${order.delivery_address.neighborhood}` : ''}
            </span>
          </div>
        </div>

        {/* Footer */}
        <div style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          marginTop: '0.875rem',
          paddingTop: '0.875rem',
          borderTop: '1px solid #f1f5f9'
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.375rem' }}>
            <DollarSign size={13} style={{ color: '#64748b' }} />
            <span style={{ fontSize: '0.8125rem', color: '#64748b' }}>
              Total: {utils.formatCurrency(order.total_amount)}
            </span>
          </div>
          <span style={{
            padding: '0.25rem 0.625rem',
            borderRadius: '9999px',
            fontSize: '0.6875rem',
            fontWeight: 600,
            background: isDelivered ? '#dcfce7' : '#fee2e2',
            color: isDelivered ? '#16a34a' : '#dc2626'
          }}>
            {isDelivered ? 'Entregue' : 'Cancelado'}
          </span>
        </div>
      </div>
    </div>
  );
};

export default HistoryPage;

import React, { useState } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { Eye, EyeOff, ArrowRight, Bike, MapPin, BarChart3, Shield } from 'lucide-react';
import { useAuth } from '@/contexts/AuthContext';

const LoginPage = () => {
  const [formData, setFormData] = useState({ email: '', password: '' });
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [accountOptions, setAccountOptions] = useState(null);

  const { login, error, clearError } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const from = location.state?.from?.pathname || '/dashboard';

  const handleChange = (e) => {
    setFormData(prev => ({ ...prev, [e.target.name]: e.target.value }));
    clearError();
    setAccountOptions(null);
  };

  const handleAccountSelect = async (userType) => {
    setIsLoading(true);
    setAccountOptions(null);
    try {
      const response = await login(formData.email, formData.password, userType);
      const user = response?.user || JSON.parse(localStorage.getItem('user'));
      navigateToDashboard(user);
    } catch (err) {
      // erro tratado no contexto
    } finally {
      setIsLoading(false);
    }
  };

  const navigateToDashboard = (user) => {
    const userType = user?.user_type;
    const isSuperAdmin = user?.is_super_admin;
    let target;
    if (userType === 'ADMIN' && isSuperAdmin) {
      target = '/platform';
    } else if (userType === 'ADMIN') {
      target = '/admin';
    } else if (userType === 'CLIENT') {
      target = '/client';
    } else {
      target = '/dashboard';
    }
    navigate(target, { replace: true });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setAccountOptions(null);
    try {
      const response = await login(formData.email, formData.password);
      const user = response?.user || JSON.parse(localStorage.getItem('user'));
      navigateToDashboard(user);
    } catch (err) {
      // Se 409 - múltiplas contas, mostrar seletor
      if (err?.response?.status === 409 && err?.response?.data?.options) {
        setAccountOptions(err.response.data.options);
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="auth-split-layout">
      {/* Lado esquerdo - Branding */}
      <div className="auth-branding" style={{ flex: '0 0 45%' }}>
        <div className="auth-animate-in" style={{ position: 'relative', zIndex: 1, maxWidth: '400px' }}>
          <img
            src="/logo-muvlog.jpg"
            alt="muv.log"
            style={{ height: '80px', marginBottom: '2rem', borderRadius: '0.75rem', boxShadow: '0 8px 32px rgba(0,0,0,0.2)' }}
          />
          <h1 style={{ fontSize: '2.5rem', fontWeight: 700, marginBottom: '0.75rem', letterSpacing: '-0.02em' }}>
            muv.log
          </h1>
          <p style={{ fontSize: '1.125rem', opacity: 0.9, marginBottom: '3rem', lineHeight: 1.6 }}>
            Plataforma completa para gestão<br />de entregadores
          </p>

          <div style={{ textAlign: 'left' }}>
            <div className="feature-item">
              <div className="feature-icon"><Bike size={20} /></div>
              <span>Gestão completa de entregadores</span>
            </div>
            <div className="feature-item">
              <div className="feature-icon"><MapPin size={20} /></div>
              <span>Tracking em tempo real</span>
            </div>
            <div className="feature-item">
              <div className="feature-icon"><BarChart3 size={20} /></div>
              <span>Relatórios e analytics</span>
            </div>
            <div className="feature-item">
              <div className="feature-icon"><Shield size={20} /></div>
              <span>Pagamentos seguros e rápidos</span>
            </div>
          </div>
        </div>
      </div>

      {/* Lado direito - Formulário */}
      <div className="auth-form-panel">
        <div className="auth-form-container auth-animate-in">
          <div style={{ marginBottom: '2rem', textAlign: 'center' }}>
            <h2 style={{ fontSize: '1.75rem', fontWeight: 700, color: '#1e293b', marginBottom: '0.5rem' }}>
              Bem-vindo de volta
            </h2>
            <p style={{ color: '#64748b', fontSize: '0.9375rem' }}>
              Faça login para acessar sua conta
            </p>
          </div>

          <div className="auth-form-card">
            {/* Seletor de conta quando há múltiplos usuários com mesmo email */}
            {accountOptions ? (
              <div>
                <p style={{ fontSize: '0.875rem', color: '#475569', marginBottom: '1rem', textAlign: 'center' }}>
                  Este email possui múltiplas contas. Escolha como deseja entrar:
                </p>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                  {accountOptions.map((opt) => {
                    const icons = { ADMIN: Shield, DRIVER: Bike, CLIENT: MapPin };
                    const colors = { ADMIN: '#7c3aed', DRIVER: '#2563eb', CLIENT: '#0d9488' };
                    const Icon = icons[opt.user_type] || Shield;
                    const color = colors[opt.user_type] || '#64748b';
                    return (
                      <button
                        key={opt.user_type}
                        onClick={() => handleAccountSelect(opt.user_type)}
                        style={{
                          display: 'flex', alignItems: 'center', gap: '0.75rem',
                          padding: '1rem', borderRadius: '0.75rem',
                          border: `2px solid ${color}20`, background: `${color}08`,
                          cursor: 'pointer', fontSize: '0.9375rem', fontWeight: 600,
                          color: color, transition: 'all 0.15s'
                        }}
                        onMouseEnter={(e) => e.currentTarget.style.background = `${color}15`}
                        onMouseLeave={(e) => e.currentTarget.style.background = `${color}08`}
                      >
                        <Icon size={22} />
                        {opt.label}
                      </button>
                    );
                  })}
                </div>
                <button
                  onClick={() => setAccountOptions(null)}
                  style={{
                    display: 'block', margin: '1rem auto 0', background: 'none',
                    border: 'none', color: '#64748b', fontSize: '0.8125rem',
                    cursor: 'pointer', textDecoration: 'underline'
                  }}
                >
                  Voltar ao login
                </button>
              </div>
            ) : (
            <form onSubmit={handleSubmit}>
              {error && (
                <div className="auth-error">
                  <svg width="16" height="16" viewBox="0 0 16 16" fill="currentColor">
                    <path d="M8 1C4.1 1 1 4.1 1 8s3.1 7 7 7 7-3.1 7-7-3.1-7-7-7zm-.5 3h1v5h-1V4zm.5 7.5c-.4 0-.7-.3-.7-.7s.3-.7.7-.7.7.3.7.7-.3.7-.7.7z"/>
                  </svg>
                  {error}
                </div>
              )}

              <div style={{ marginBottom: '1.25rem' }}>
                <label htmlFor="login-email" className="auth-form-label">Email</label>
                <input
                  id="login-email"
                  type="email"
                  name="email"
                  className="auth-form-input"
                  placeholder="seu@email.com"
                  value={formData.email}
                  onChange={handleChange}
                  required
                  autoComplete="username"
                />
              </div>

              <div style={{ marginBottom: '0.5rem' }}>
                <label htmlFor="login-password" className="auth-form-label">Senha</label>
                <div className="password-wrapper">
                  <input
                    id="login-password"
                    type={showPassword ? 'text' : 'password'}
                    name="password"
                    className="auth-form-input"
                    placeholder="Sua senha"
                    value={formData.password}
                    onChange={handleChange}
                    required
                    autoComplete="current-password"
                    style={{ paddingRight: '2.75rem' }}
                  />
                  <button
                    type="button"
                    className="password-toggle"
                    onClick={() => setShowPassword(!showPassword)}
                  >
                    {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                  </button>
                </div>
              </div>

              <div style={{ textAlign: 'right', marginBottom: '1.5rem' }}>
                <a href="/support" style={{ fontSize: '0.8125rem', color: '#64748b', textDecoration: 'none' }}>
                  Esqueci minha senha
                </a>
              </div>

              <button type="submit" className="auth-btn-primary" disabled={isLoading}>
                {isLoading ? (
                  <>
                    <div style={{
                      width: '1rem', height: '1rem',
                      border: '2px solid rgba(255,255,255,0.3)',
                      borderTopColor: 'white',
                      borderRadius: '50%',
                      animation: 'spin 0.6s linear infinite'
                    }} />
                    Entrando...
                  </>
                ) : (
                  <>
                    Entrar
                    <ArrowRight size={18} />
                  </>
                )}
              </button>
            </form>
            )}
          </div>

          <div style={{ marginTop: '1.5rem', textAlign: 'center' }}>
            <p style={{ color: '#64748b', fontSize: '0.875rem', marginBottom: '0.5rem' }}>
              Não tem uma conta?
            </p>
            <div style={{ display: 'flex', gap: '0.75rem', justifyContent: 'center' }}>
              <Link to="/register" className="auth-footer-link">
                Cadastre-se como entregador
              </Link>
              <span style={{ color: '#cbd5e1' }}>|</span>
              <Link to="/client/register" className="auth-footer-link">
                Cadastre-se como estabelecimento
              </Link>
            </div>
          </div>

          {/* Credenciais de teste - sutil */}
        </div>
      </div>

      <style>{`
        @keyframes spin {
          to { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
};

export default LoginPage;

import React, { useState, useEffect } from 'react';
import { AlertCircle, CheckCircle } from 'lucide-react';
import api from '@/lib/api';
import ExportButton from './payment-reports/ExportButton';
import PaymentFilters from './payment-reports/PaymentFilters';
import PaymentStats from './payment-reports/PaymentStats';
import PaymentList from './payment-reports/PaymentList';
import WithdrawalsList from './payment-reports/WithdrawalsList';

const PAYMENT_FREQUENCY_LABELS = {
  DAILY: { label: 'Diário', icon: '📅', color: '#2563eb' },
  WEEKLY: { label: 'Semanal', icon: '📆', color: '#7c3aed' },
  MONTHLY: { label: 'Mensal', icon: '🗓️', color: '#059669' },
  ON_DEMAND: { label: 'Sob Demanda', icon: '⚡', color: '#d97706' }
};

const PaymentReportsPage = () => {
  const [reports, setReports] = useState([]);
  const [summary, setSummary] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [expandedDriver, setExpandedDriver] = useState(null);
  const [expandedPeriod, setExpandedPeriod] = useState(null);
  const [activeTab, setActiveTab] = useState('reports');

  // Withdrawals
  const [withdrawals, setWithdrawals] = useState([]);
  const [withdrawalSummary, setWithdrawalSummary] = useState(null);

  // Filtros
  const [period, setPeriod] = useState('month');
  const [frequencyFilter, setFrequencyFilter] = useState('');
  const [restaurantFilter, setRestaurantFilter] = useState('');
  const [restaurants, setRestaurants] = useState([]);
  const [isAdmin, setIsAdmin] = useState(false);

  useEffect(() => {
    checkUserRole();
  }, []);

  const checkUserRole = async () => {
    try {
      const res = await api.get('/api/user/profile');
      const isAdminUser = res.data.user_type === 'ADMIN';
      setIsAdmin(isAdminUser);
      if (isAdminUser) {
        loadRestaurants();
      }
    } catch (err) {
      console.error(err);
    }
  };

  const loadRestaurants = async () => {
    try {
      const res = await api.get('/api/admin/establishments');
      setRestaurants(res.data.establishments || []);
    } catch (err) {
      console.error(err);
    }
  };

  const loadReports = async () => {
    try {
      setLoading(true);
      setError('');
      const params = { period };
      if (frequencyFilter) params.frequency = frequencyFilter;
      if (restaurantFilter) params.restaurant_id = restaurantFilter;

      const res = await api.get('/api/finance/payment-reports', { params });
      setReports(res.data.reports || []);
      setSummary(res.data.summary || {});
    } catch (err) {
      console.error('Erro ao carregar relatórios:', err);
      setError('Erro ao carregar relatórios');
    } finally {
      setLoading(false);
    }
  };

  const loadWithdrawals = async () => {
    try {
      setLoading(true);
      const res = await api.get('/api/finance/own-driver-withdrawals');
      setWithdrawals(res.data.drivers || []);
      setWithdrawalSummary(res.data.summary || {});
    } catch (err) {
      console.error('Erro ao carregar saques:', err);
      setError('Erro ao carregar saques');
    } finally {
      setLoading(false);
    }
  };

  const handleProcessWithdrawal = async (driverId) => {
    if (!window.confirm('Processar saque via PIX?')) return;
    try {
      const res = await api.post('/api/finance/process-withdrawal', {
        driver_id: driverId,
        payment_method: 'PIX'
      });
      setSuccess(res.data.message);
      setTimeout(() => setSuccess(''), 5000);
      loadWithdrawals();
    } catch (err) {
      setError(err.response?.data?.error || 'Erro ao processar saque');
    }
  };

  useEffect(() => {
    if (activeTab === 'reports') loadReports();
    if (activeTab === 'withdrawals') loadWithdrawals();
  }, [activeTab, period, frequencyFilter, restaurantFilter]);

  const handlePayPeriod = async (driverId, periodStart, paymentMethod = 'PIX') => {
    try {
      const res = await api.post('/api/finance/pay-period', {
        driver_id: driverId,
        period_start: periodStart,
        payment_method: paymentMethod
      });
      setSuccess(res.data.message);
      setTimeout(() => setSuccess(''), 3000);
      loadReports();
    } catch (err) {
      setError(err.response?.data?.error || 'Erro ao registrar pagamento');
    }
  };

  const handlePayAll = async (driverId, paymentMethod = 'PIX') => {
    if (!window.confirm('Marcar todos os ganhos pendentes como pagos?')) return;
    try {
      const res = await api.post('/api/finance/pay-all', {
        driver_id: driverId,
        payment_method: paymentMethod
      });
      setSuccess(res.data.message);
      setTimeout(() => setSuccess(''), 3000);
      loadReports();
    } catch (err) {
      setError(err.response?.data?.error || 'Erro ao registrar pagamento');
    }
  };

  const formatCurrency = (value) => {
    return `R$ ${(value || 0).toFixed(2).replace('.', ',')}`;
  };

  const formatDate = (dateStr) => {
    if (!dateStr) return '-';
    return new Date(dateStr).toLocaleDateString('pt-BR');
  };

  const formatDateTime = (dateStr) => {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return `${date.toLocaleDateString('pt-BR')} ${date.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}`;
  };

  const exportCSV = () => {
    if (activeTab === 'reports') {
      if (!reports.length) return;

      let csv = 'Entregador,Restaurante,Frequência,Total Ganhos,Total Pago,Pendente\n';

      reports.forEach(r => {
        csv += `"${r.driver_name}","${r.restaurant_name}","${r.payment_frequency}",${r.total_earning.toFixed(2)},${r.total_paid.toFixed(2)},${r.total_pending.toFixed(2)}\n`;
      });

      const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `relatorio_pagamentos_${new Date().toISOString().split('T')[0]}.csv`;
      a.click();
      URL.revokeObjectURL(url);
    } else if (activeTab === 'withdrawals') {
      if (!withdrawals.length) return;

      let csv = 'Entregador,Restaurante,PIX,Pendente,Pago,Frequência\n';

      withdrawals.forEach(d => {
        csv += `"${d.driver_name}","${d.restaurant_name}","${d.pix_key || '-'}",${d.pending_amount.toFixed(2)},${d.paid_amount.toFixed(2)},"${d.payment_frequency}"\n`;
      });

      const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `relatorio_saques_${new Date().toISOString().split('T')[0]}.csv`;
      a.click();
      URL.revokeObjectURL(url);
    }
  };

  return (
    <div style={{ padding: '1.5rem', maxWidth: '1200px', margin: '0 auto' }}>
      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem' }}>
        <div>
          <h1 style={{ fontSize: '1.75rem', fontWeight: 700, color: '#1e293b', marginBottom: '0.25rem' }}>
            Financeiro - Entregadores Próprios
          </h1>
          <p style={{ color: '#64748b', fontSize: '0.9375rem' }}>
            Relatórios de pagamento por frequência e quitação por período
          </p>
        </div>
        <ExportButton onClick={exportCSV} />
      </div>

      {/* Mensagens */}
      {error && (
        <div style={{ background: '#fef2f2', border: '1px solid #fecaca', color: '#dc2626', padding: '0.75rem 1rem', borderRadius: '0.5rem', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <AlertCircle size={16} /> {error}
        </div>
      )}
      {success && (
        <div style={{ background: '#f0fdf4', border: '1px solid #bbf7d0', color: '#166534', padding: '0.75rem 1rem', borderRadius: '0.5rem', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <CheckCircle size={16} /> {success}
        </div>
      )}

      {/* Tabs */}
      <div style={{ display: 'flex', gap: '0.5rem', marginBottom: '1.5rem' }}>
        <button
          onClick={() => setActiveTab('reports')}
          style={{ padding: '0.5rem 1rem', borderRadius: '0.5rem', border: 'none', background: activeTab === 'reports' ? '#2563eb' : 'white', color: activeTab === 'reports' ? 'white' : '#64748b', fontSize: '0.875rem', fontWeight: 500, cursor: 'pointer' }}
        >
          Relatórios
        </button>
        <button
          onClick={() => setActiveTab('withdrawals')}
          style={{ padding: '0.5rem 1rem', borderRadius: '0.5rem', border: 'none', background: activeTab === 'withdrawals' ? '#2563eb' : 'white', color: activeTab === 'withdrawals' ? 'white' : '#64748b', fontSize: '0.875rem', fontWeight: 500, cursor: 'pointer' }}
        >
          Saques
        </button>
      </div>

      {/* Filters */}
      {activeTab === 'reports' && (
        <PaymentFilters
          period={period}
          onPeriodChange={setPeriod}
          frequencyFilter={frequencyFilter}
          onFrequencyChange={setFrequencyFilter}
          restaurantFilter={restaurantFilter}
          onRestaurantChange={setRestaurantFilter}
          isAdmin={isAdmin}
          restaurants={restaurants}
        />
      )}

      {/* Stats */}
      {activeTab === 'reports' && (
        <PaymentStats summary={summary} variant="reports" formatCurrency={formatCurrency} />
      )}
      {activeTab === 'withdrawals' && (
        <PaymentStats summary={withdrawalSummary} variant="withdrawals" formatCurrency={formatCurrency} />
      )}

      {/* Loading */}
      {loading ? (
        <div style={{ display: 'flex', justifyContent: 'center', padding: '3rem' }}>
          <div style={{ width: '2rem', height: '2rem', border: '3px solid #e2e8f0', borderTopColor: '#0d9488', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
          <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
        </div>
      ) : activeTab === 'reports' ? (
        <PaymentList
          reports={reports}
          expandedDriver={expandedDriver}
          expandedPeriod={expandedPeriod}
          onToggleDriver={(driverId) => setExpandedDriver(expandedDriver === driverId ? null : driverId)}
          onTogglePeriod={setExpandedPeriod}
          onPayAll={handlePayAll}
          onPayPeriod={handlePayPeriod}
          formatCurrency={formatCurrency}
          formatDate={formatDate}
          formatDateTime={formatDateTime}
          PAYMENT_FREQUENCY_LABELS={PAYMENT_FREQUENCY_LABELS}
        />
      ) : (
        <WithdrawalsList
          withdrawals={withdrawals}
          onProcessWithdrawal={handleProcessWithdrawal}
          formatCurrency={formatCurrency}
        />
      )}
    </div>
  );
};

export default PaymentReportsPage;

import React, { useState, useEffect, useRef } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Clock, CheckCircle, XCircle, ArrowLeft, Loader } from 'lucide-react';
import api from '@/lib/api';

const PendingApprovalPage = () => {
  const [status, setStatus] = useState('pending'); // pending, approved, rejected
  const [checking, setChecking] = useState(true);
  const [pushEnabled, setPushEnabled] = useState(false);
  const navigate = useNavigate();
  const intervalRef = useRef(null);

  // Solicitar permissão de notificação e registrar token
  useEffect(() => {
    const setupPush = async () => {
      try {
        const { requestNotificationPermission } = await import('@/lib/firebase');
        const token = await requestNotificationPermission();
        if (token) {
          setPushEnabled(true);
          // Registrar token no backend
          await api.post('/api/auth/register-push-token', { token }).catch(() => {});
        }
      } catch (err) {
        console.log('[Push] Não foi possível ativar notificações:', err.message);
      }
    };
    setupPush();
  }, []);

  // Polling para verificar status do cadastro
  useEffect(() => {
    const checkStatus = async () => {
      try {
        const res = await api.get('/api/user/profile');
        const user = res.data;
        if (user.status === 'ACTIVE') {
          setStatus('approved');
          playSound();
          clearInterval(intervalRef.current);
          // Redirecionar para login após 3 segundos
          setTimeout(() => navigate('/login'), 3000);
        }
      } catch (err) {
        // Se retornar 401/403, pode ter sido rejeitado (usuário deletado)
        if (err.response?.status === 401 || err.response?.status === 403) {
          setStatus('rejected');
          playSound();
          clearInterval(intervalRef.current);
        }
      } finally {
        setChecking(false);
      }
    };

    // Verificar imediatamente
    checkStatus();
    // Depois a cada 15 segundos
    intervalRef.current = setInterval(checkStatus, 15000);

    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current);
    };
  }, [navigate]);

  // Escutar mensagens em foreground (quando o app está aberto)
  useEffect(() => {
    let unsubscribe = () => {};
    const setupForeground = async () => {
      try {
        const { onForegroundMessage } = await import('@/lib/firebase');
        unsubscribe = onForegroundMessage((payload) => {
          const type = payload.data?.type;
          if (type === 'ACCOUNT_APPROVED') {
            setStatus('approved');
            playSound();
            setTimeout(() => navigate('/login'), 3000);
          } else if (type === 'ACCOUNT_REJECTED') {
            setStatus('rejected');
            playSound();
          }
        });
      } catch {}
    };
    setupForeground();
    return () => unsubscribe();
  }, [navigate]);

  const playSound = () => {
    try {
      const ctx = new (window.AudioContext || window.webkitAudioContext)();
      // Tom de notificação agradável (3 notas ascendentes)
      const notes = [523.25, 659.25, 783.99]; // C5, E5, G5
      notes.forEach((freq, i) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.type = 'sine';
        osc.frequency.value = freq;
        gain.gain.setValueAtTime(0.3, ctx.currentTime + i * 0.15);
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + i * 0.15 + 0.4);
        osc.start(ctx.currentTime + i * 0.15);
        osc.stop(ctx.currentTime + i * 0.15 + 0.4);
      });
    } catch {}
  };

  // Status: Aprovado
  if (status === 'approved') {
    return (
      <div style={{
        minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center',
        background: 'linear-gradient(135deg, #f0fdf4 0%, #dcfce7 100%)', padding: '2rem'
