      <div style={{ display: 'flex', gap: '0.5rem', marginBottom: '1.5rem' }}>
        <button
          onClick={() => setActiveTab('subscriptions')}
          style={{ padding: '0.5rem 1rem', borderRadius: '0.5rem', border: 'none', background: activeTab === 'subscriptions' ? '#2563eb' : 'white', color: activeTab === 'subscriptions' ? 'white' : '#64748b', fontSize: '0.875rem', fontWeight: 500, cursor: 'pointer' }}
        >
          Assinaturas
        </button>
        <button
          onClick={() => setActiveTab('invoices')}
          style={{ padding: '0.5rem 1rem', borderRadius: '0.5rem', border: 'none', background: activeTab === 'invoices' ? '#2563eb' : 'white', color: activeTab === 'invoices' ? 'white' : '#64748b', fontSize: '0.875rem', fontWeight: 500, cursor: 'pointer' }}
        >
          Faturas
        </button>
      </div>

      {/* Content */}
      {loading ? (
        <div style={{ display: 'flex', justifyContent: 'center', padding: '3rem' }}>
          <div style={{ width: '2rem', height: '2rem', border: '3px solid #e2e8f0', borderTopColor: '#0d9488', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
          <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
        </div>
      ) : (
        <>
          {activeTab === 'subscriptions' && (
            <SubscriptionCards
              subscriptions={subscriptions}
              onGenerateInvoice={handleGenerateInvoice}
            />
          )}

          {activeTab === 'invoices' && (
            <InvoicesTable
              invoices={invoices}
              onPayInvoice={handlePayInvoice}
            />
          )}
        </>
      )}

      {/* Modal de Criação */}
      <CreateSubscriptionModal
        isOpen={showCreateModal}
        onClose={() => setShowCreateModal(false)}
        onSubmit={handleCreateSubscription}
        createForm={createForm}
        setCreateForm={setCreateForm}
        restaurants={restaurants}
      />
    </div>
  );
};

export default SubscriptionPage;

import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { Package, CheckCircle, Clock, Bike, MapPin, Store, User } from 'lucide-react';
import api from '@/lib/api';

const statusConfig = {
  SCHEDULED: { color: '#6366f1', icon: Clock, label: 'Pedido criado' },
  PENDING: { color: '#f59e0b', icon: Clock, label: 'Aguardando entregador' },
  ACCEPTED: { color: '#2563eb', icon: CheckCircle, label: 'Aceito por entregador' },
  PREPARING: { color: '#8b5cf6', icon: Package, label: 'Em preparo' },
  READY: { color: '#06b6d4', icon: CheckCircle, label: 'Pronto para coleta' },
  PICKED_UP: { color: '#f59e0b', icon: Bike, label: 'Coletado' },
  DELIVERED: { color: '#22c55e', icon: CheckCircle, label: 'Entregue' },
  CANCELLED: { color: '#ef4444', icon: Package, label: 'Cancelado' },
};

const TrackPage = () => {
  const { token } = useParams();
  const [tracking, setTracking] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    loadTracking();
    // Atualizar a cada 30 segundos
    const interval = setInterval(loadTracking, 30000);
    return () => clearInterval(interval);
  }, [token]);

  const loadTracking = async () => {
    try {
      const response = await api.get(`/api/orders/track/${token}`);
      setTracking(response.data);
      setError('');
    } catch (err) {
      setError('Pedido não encontrado');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: '#f1f5f9' }}>
        <div style={{ textAlign: 'center' }}>
          <div style={{ width: '3rem', height: '3rem', border: '3px solid #e2e8f0', borderTopColor: '#6366f1', borderRadius: '50%', animation: 'spin 1s linear infinite', margin: '0 auto 1rem' }} />
          <p style={{ color: '#64748b' }}>Carregando...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: '#f1f5f9' }}>
        <div style={{ textAlign: 'center', padding: '2rem', background: 'white', borderRadius: '1rem', boxShadow: '0 4px 6px rgba(0,0,0,0.05)' }}>
          <Package size={48} style={{ color: '#64748b', margin: '0 auto 1rem' }} />
          <h2 style={{ fontSize: '1.25rem', fontWeight: 600, color: '#1e293b', marginBottom: '0.5rem' }}>{error}</h2>
          <p style={{ color: '#64748b' }}>Verifique o link e tente novamente.</p>
        </div>
      </div>
    );
  }

  const currentStatus = statusConfig[tracking.status] || statusConfig.PENDING;

  return (
    <div style={{ minHeight: '100vh', background: '#f1f5f9', padding: '1.5rem' }}>
      <div style={{ maxWidth: '500px', margin: '0 auto' }}>
        {/* Header */}
        <div style={{ textAlign: 'center', marginBottom: '2rem' }}>
          <img src="/logo-muvlog.jpg" alt="muv.log" style={{ height: '60px', borderRadius: '0.5rem', marginBottom: '1rem' }} />
          <h1 style={{ fontSize: '1.5rem', fontWeight: 700, color: '#1e293b' }}>Rastreio de Pedido</h1>
        </div>

        {/* Card principal */}
        <div style={{ background: 'white', borderRadius: '1rem', overflow: 'hidden', boxShadow: '0 4px 6px rgba(0,0,0,0.05)' }}>
          {/* Status atual */}
          <div style={{ padding: '1.5rem', background: `linear-gradient(135deg, ${currentStatus.color}10, ${currentStatus.color}05)`, borderBottom: '1px solid #f1f5f9' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
              <div style={{ width: '48px', height: '48px', borderRadius: '50%', background: `${currentStatus.color}15`, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <currentStatus.icon size={24} style={{ color: currentStatus.color }} />
              </div>
              <div>
                <p style={{ fontSize: '0.75rem', color: '#64748b' }}>Status atual</p>
                <p style={{ fontSize: '1.125rem', fontWeight: 600, color: currentStatus.color }}>{currentStatus.label}</p>
              </div>
            </div>
          </div>

          {/* Informações do pedido */}
          <div style={{ padding: '1.5rem' }}>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem', marginBottom: '1.5rem' }}>
              <div>
                <p style={{ fontSize: '0.75rem', color: '#64748b' }}>Pedido</p>
                <p style={{ fontSize: '0.875rem', fontWeight: 500, color: '#1e293b' }}>#{tracking.order_number}</p>
              </div>
              <div>
                <p style={{ fontSize: '0.75rem', color: '#64748b' }}>Estabelecimento</p>
                <p style={{ fontSize: '0.875rem', fontWeight: 500, color: '#1e293b' }}>{tracking.restaurant_name}</p>
              </div>
            </div>

            {/* Timeline */}
            <div style={{ marginTop: '1.5rem' }}>
              <p style={{ fontSize: '0.75rem', fontWeight: 600, color: '#1e293b', marginBottom: '1rem' }}>Progresso</p>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                {tracking.timeline?.map((step, index) => {
                  const stepConfig = statusConfig[step.status];
                  const isActive = tracking.status === step.status;
                  const isPast = tracking.timeline.findIndex(s => s.status === tracking.status) > index;
                  
                  return (
                    <div key={step.status} style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                      <div style={{
                        width: '12px', height: '12px', borderRadius: '50%',
                        background: isPast || isActive ? stepConfig.color : '#e2e8f0',
                        border: isActive ? `2px solid ${stepConfig.color}` : 'none',
                        flexShrink: 0
                      }} />
                      <div style={{ flex: 1 }}>
                        <p style={{ fontSize: '0.8125rem', fontWeight: isActive ? 600 : 400, color: isPast || isActive ? '#1e293b' : '#64748b' }}>
                          {step.label}
                        </p>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Localização do entregador */}
            {tracking.driver_location && (
              <div style={{ marginTop: '1.5rem', padding: '1rem', background: '#f8fafc', borderRadius: '0.75rem' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '0.5rem' }}>
                  <Bike size={16} style={{ color: '#2563eb' }} />
                  <p style={{ fontSize: '0.8125rem', fontWeight: 600, color: '#1e293b' }}>Entregador a caminho</p>
                </div>
                <p style={{ fontSize: '0.75rem', color: '#64748b' }}>
                  {tracking.driver_location.name} • {tracking.driver_location.vehicle_type}
                </p>
              </div>
            )}

            {/* Bairro de entrega */}
            {tracking.delivery_neighborhood && (
              <div style={{ marginTop: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                <MapPin size={16} style={{ color: '#64748b' }} />
                <p style={{ fontSize: '0.8125rem', color: '#64748b' }}>
                  Entrega em: {tracking.delivery_neighborhood}
                </p>
              </div>
            )}
          </div>
        </div>

        {/* Footer */}
        <div style={{ textAlign: 'center', marginTop: '2rem' }}>
          <p style={{ fontSize: '0.75rem', color: '#64748b' }}>
            Atualização automática a cada 30 segundos
          </p>
        </div>
      </div>

      <style>{`
        @keyframes spin { to { transform: rotate(360deg); } }
      `}</style>
    </div>
  );
};

export default TrackPage;

import React, { useState, useEffect } from 'react';
import { Wallet, ArrowDownCircle, ArrowUpCircle, Clock, CheckCircle, XCircle, RefreshCw } from 'lucide-react';
import api from '@/lib/api';

const WalletPage = () => {
  const [wallet, setWallet] = useState(null);
  const [loading, setLoading] = useState(true);
  const [showWithdraw, setShowWithdraw] = useState(false);
  const [showPixEdit, setShowPixEdit] = useState(false);
  const [withdrawAmount, setWithdrawAmount] = useState('');
  const [pixKey, setPixKey] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  useEffect(() => { loadWallet(); }, []);

  const loadWallet = async () => {
    try {
      setLoading(true);
      setError('');
      const response = await api.get('/api/driver/wallet');
      setWallet(response.data || {});
      setPixKey(response.data?.pix_key || '');
    } catch (err) {
      setError('Erro ao carregar carteira');
    } finally {
      setLoading(false);
    }
  };

  const handleWithdraw = async () => {
    if (!withdrawAmount || parseFloat(withdrawAmount) <= 0) {
      setError('Informe um valor válido');
      return;
    }
    try {
      await api.post('/api/driver/wallet/withdraw', { amount: parseFloat(withdrawAmount) });
      setSuccess('Solicitação de saque enviada!');
      setWithdrawAmount('');
      setShowWithdraw(false);
      loadWallet();
      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      setError(err.response?.data?.error || 'Erro ao solicitar saque');
    }
  };

  const handleSavePix = async () => {
    if (!pixKey.trim()) {
      setError('Informe sua chave PIX');
      return;
    }
    try {
      await api.put('/api/driver/wallet/pix-key', { pix_key: pixKey.trim() });
      setSuccess('Chave PIX atualizada!');
      setShowPixEdit(false);
      loadWallet();
      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      setError(err.response?.data?.error || 'Erro ao atualizar PIX');
    }
  };

  if (loading) {
    return (
      <div style={{ minHeight: '60vh', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ width: '3rem', height: '3rem', border: '3px solid #e2e8f0', borderTopColor: '#2563eb', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
      </div>
    );
  }

  return (
    <div style={{ padding: '1rem', maxWidth: '600px', margin: '0 auto' }}>
      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem' }}>
        <h1 style={{ fontSize: '1.5rem', fontWeight: 700, color: '#1e293b' }}>Minha Carteira</h1>
        <button onClick={loadWallet} style={{ display: 'flex', alignItems: 'center', gap: '0.375rem', padding: '0.375rem 0.75rem', borderRadius: '0.5rem', border: '1px solid #e2e8f0', background: 'white', cursor: 'pointer', fontSize: '0.75rem', color: '#64748b' }}>
          <RefreshCw size={14} /> Atualizar
        </button>
      </div>

      {error && <div style={{ background: '#fef2f2', border: '1px solid #fecaca', color: '#dc2626', padding: '0.75rem', borderRadius: '0.5rem', marginBottom: '1rem', fontSize: '0.875rem' }}>{error}</div>}
      {success && <div style={{ background: '#dcfce7', border: '1px solid #86efac', color: '#166534', padding: '0.75rem', borderRadius: '0.5rem', marginBottom: '1rem', fontSize: '0.875rem' }}>{success}</div>}

      {/* Saldo */}
      <div style={{ background: 'linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%)', borderRadius: '1rem', padding: '1.5rem', color: 'white', marginBottom: '1rem' }}>
        <p style={{ fontSize: '0.875rem', opacity: 0.8, marginBottom: '0.25rem' }}>Saldo Disponível</p>
        <p style={{ fontSize: '2rem', fontWeight: 700 }}>R$ {(wallet?.balance || 0).toFixed(2).replace('.', ',')}</p>
        {(wallet?.locked_balance || 0) > 0 && (
          <p style={{ fontSize: '0.75rem', opacity: 0.7, marginTop: '0.5rem' }}>
            🔒 Bloqueado: R$ {(wallet?.locked_balance || 0).toFixed(2).replace('.', ',')}
          </p>
        )}
      </div>

      {/* Ações */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.75rem', marginBottom: '1.5rem' }}>
        <button
          onClick={() => setShowWithdraw(true)}
          disabled={!wallet?.balance || wallet.balance <= 0}
          style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '0.5rem', padding: '1rem', borderRadius: '0.75rem', border: '1px solid #e2e8f0', background: 'white', cursor: wallet?.balance > 0 ? 'pointer' : 'not-allowed', opacity: wallet?.balance > 0 ? 1 : 0.5 }}
        >
          <ArrowUpCircle size={24} style={{ color: '#2563eb' }} />
          <span style={{ fontSize: '0.8125rem', fontWeight: 600, color: '#1e293b' }}>Sacar via PIX</span>
        </button>
        <button
          onClick={() => setShowPixEdit(true)}
          style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '0.5rem', padding: '1rem', borderRadius: '0.75rem', border: '1px solid #e2e8f0', background: 'white', cursor: 'pointer' }}
        >
          <Wallet size={24} style={{ color: '#0d9488' }} />
          <span style={{ fontSize: '0.8125rem', fontWeight: 600, color: '#1e293b' }}>{wallet?.pix_key ? 'Alterar PIX' : 'Configurar PIX'}</span>
        </button>
      </div>

      {/* Chave PIX atual */}
      {wallet?.pix_key && (
        <div style={{ background: '#f0fdfa', border: '1px solid #99f6e4', borderRadius: '0.5rem', padding: '0.75rem', marginBottom: '1.5rem' }}>
          <p style={{ fontSize: '0.75rem', color: '#0d9488', marginBottom: '0.25rem' }}>Chave PIX</p>
          <p style={{ fontSize: '0.875rem', fontWeight: 500, color: '#1e293b' }}>{wallet.pix_key}</p>
        </div>
      )}

      {/* Histórico */}
      <div style={{ background: 'white', borderRadius: '0.75rem', padding: '1rem', boxShadow: '0 1px 3px rgba(0,0,0,0.05)' }}>
        <h3 style={{ fontSize: '0.9375rem', fontWeight: 600, color: '#1e293b', marginBottom: '0.75rem' }}>Últimas Transações</h3>
        {wallet?.recent_payments?.length === 0 ? (
          <p style={{ color: '#64748b', fontSize: '0.875rem', textAlign: 'center', padding: '1rem' }}>Nenhuma transação</p>
        ) : (
          wallet?.recent_payments?.map(p => (
            <div key={p.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '0.5rem 0', borderBottom: '1px solid #f1f5f9' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                {p.amount > 0 ? (
                  <ArrowDownCircle size={16} style={{ color: '#22c55e' }} />
                ) : (
                  <ArrowUpCircle size={16} style={{ color: '#ef4444' }} />
                )}
                <div>
                  <p style={{ fontSize: '0.8125rem', fontWeight: 500, color: '#1e293b' }}>
                    {p.type === 'WITHDRAWAL' ? 'Saque PIX' : 'Ganho de entrega'}
                  </p>
                  <p style={{ fontSize: '0.6875rem', color: '#64748b' }}>
                    {p.created_at ? new Date(p.created_at + 'Z').toLocaleString('pt-BR') : ''}
                  </p>
                </div>
              </div>
              <span style={{ fontWeight: 600, color: p.amount > 0 ? '#22c55e' : '#ef4444' }}>
                {p.amount > 0 ? '+' : ''}R$ {Math.abs(p.amount).toFixed(2).replace('.', ',')}
              </span>
            </div>
          ))
        )}
      </div>

      {/* Modal Saque */}
      {showWithdraw && (
        <>
          <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', zIndex: 99999 }} onClick={() => setShowWithdraw(false)} />
          <div style={{ position: 'fixed', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', background: 'white', borderRadius: '0.75rem', width: '90%', maxWidth: '400px', zIndex: 100000, padding: '1.5rem' }}>
            <h3 style={{ fontSize: '1.125rem', fontWeight: 700, color: '#1e293b', marginBottom: '1rem' }}>Solicitar Saque</h3>
            <p style={{ fontSize: '0.875rem', color: '#64748b', marginBottom: '1rem' }}>
              Saldo disponível: <strong>R$ {(wallet?.balance || 0).toFixed(2).replace('.', ',')}</strong>
            </p>
            <input
              type="number"
              value={withdrawAmount}
              onChange={e => setWithdrawAmount(e.target.value)}
              placeholder="Valor do saque"
              style={{ width: '100%', padding: '0.75rem', border: '1.5px solid #e2e8f0', borderRadius: '0.5rem', fontSize: '1rem', marginBottom: '1rem', boxSizing: 'border-box' }}
            />
            <div style={{ display: 'flex', gap: '0.75rem' }}>
              <button onClick={() => setShowWithdraw(false)} style={{ flex: 1, padding: '0.75rem', borderRadius: '0.5rem', border: '1px solid #e2e8f0', background: 'white', cursor: 'pointer' }}>Cancelar</button>
              <button onClick={handleWithdraw} style={{ flex: 1, padding: '0.75rem', borderRadius: '0.5rem', border: 'none', background: '#2563eb', color: 'white', fontWeight: 600, cursor: 'pointer' }}>Sacar</button>
            </div>
          </div>
        </>
      )}

      {/* Modal PIX */}
      {showPixEdit && (
        <>
          <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', zIndex: 99999 }} onClick={() => setShowPixEdit(false)} />
          <div style={{ position: 'fixed', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', background: 'white', borderRadius: '0.75rem', width: '90%', maxWidth: '400px', zIndex: 100000, padding: '1.5rem' }}>
            <h3 style={{ fontSize: '1.125rem', fontWeight: 700, color: '#1e293b', marginBottom: '1rem' }}>Chave PIX</h3>
            <input
              value={pixKey}
              onChange={e => setPixKey(e.target.value)}
              placeholder="CPF, telefone, email ou chave aleatória"
              style={{ width: '100%', padding: '0.75rem', border: '1.5px solid #e2e8f0', borderRadius: '0.5rem', fontSize: '1rem', marginBottom: '1rem', boxSizing: 'border-box' }}
            />
            <div style={{ display: 'flex', gap: '0.75rem' }}>
              <button onClick={() => setShowPixEdit(false)} style={{ flex: 1, padding: '0.75rem', borderRadius: '0.5rem', border: '1px solid #e2e8f0', background: 'white', cursor: 'pointer' }}>Cancelar</button>
              <button onClick={handleSavePix} style={{ flex: 1, padding: '0.75rem', borderRadius: '0.5rem', border: 'none', background: '#0d9488', color: 'white', fontWeight: 600, cursor: 'pointer' }}>Salvar</button>
            </div>
          </div>
        </>
      )}

      <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
    </div>
  );
};

export default WalletPage;

import React from 'react';
import { Package } from 'lucide-react';

const CodeModal = ({
  showCodeModal, codeInput, setCodeInput, pendingStatus, isUpdating,
  order, proofPhoto,
  onClose, onConfirm
}) => {
  if (!showCodeModal) return null;

  return (
    <div style={{
      position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)',
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      zIndex: 10000, padding: '1rem'
    }}>
      <div style={{
        background: 'white', borderRadius: '1rem', padding: '2rem',
        maxWidth: '400px', width: '100%', textAlign: 'center'
      }}>
        <div style={{
          width: '64px', height: '64px', borderRadius: '50%',
          background: pendingStatus === 'PICKED_UP' ? '#dbeafe' : '#dcfce7',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          margin: '0 auto 1rem'
        }}>
          <Package size={32} style={{ color: pendingStatus === 'PICKED_UP' ? '#2563eb' : '#16a34a' }} />
        </div>

        <h2 style={{ fontSize: '1.25rem', fontWeight: 700, color: '#1e293b', marginBottom: '0.5rem' }}>
          {pendingStatus === 'PICKED_UP' ? 'Código de Coleta' : 'Código de Entrega'}
        </h2>
        <p style={{ color: '#64748b', fontSize: '0.875rem', marginBottom: '1.5rem' }}>
          Peça o código ao {pendingStatus === 'PICKED_UP' ? 'estabelecimento' : 'cliente'}
        </p>

        {/* Input do codigo */}
        <input
          type="text"
          value={codeInput}
          onChange={(e) => setCodeInput(e.target.value.replace(/\D/g, '').slice(0, 6))}
          placeholder="000000"
          maxLength={6}
          style={{
            width: '100%', padding: '1rem', borderRadius: '0.75rem',
            border: '2px solid #e2e8f0', fontSize: '1.5rem',
            textAlign: 'center', letterSpacing: '0.5rem',
            fontWeight: 700, outline: 'none',
            fontFamily: 'monospace'
          }}
          autoFocus
        />

        {/* Botoes */}
        <div style={{ display: 'flex', gap: '0.75rem', marginTop: '1.5rem' }}>
          <button
            onClick={onClose}
            style={{
              flex: 1, padding: '0.75rem', borderRadius: '0.5rem',
              border: '1px solid #e2e8f0', background: 'white',
              color: '#64748b', cursor: 'pointer', fontSize: '0.875rem'
            }}
          >
            Cancelar
          </button>
          <button
            onClick={() => {
              if (codeInput.length === 6) {
                onConfirm(codeInput);
              }
            }}
            disabled={codeInput.length !== 6 || isUpdating}
            style={{
              flex: 1, padding: '0.75rem', borderRadius: '0.5rem',
              border: 'none', background: codeInput.length === 6 ? '#2563eb' : '#94a3b8',
              color: 'white', cursor: codeInput.length === 6 ? 'pointer' : 'not-allowed',
              fontSize: '0.875rem', fontWeight: 600
            }}
          >
            {isUpdating ? 'Confirmando...' : 'Confirmar'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default CodeModal;

import React, { useEffect, useRef } from 'react';
import { Navigation, Phone, X } from 'lucide-react';
import L from 'leaflet';
import { escapeHtml } from './constants';

const MapModal = ({ showMap, mapTarget, order, mapRef, onClose, onNavigate, onCall }) => {
  const mapInstanceRef = useRef(null);

  // Inicializa o mapa quando abre
  useEffect(() => {
    if (showMap && mapRef.current && !mapInstanceRef.current) {
      const map = L.map(mapRef.current).setView([-29.95, -50.45], 13);
      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '© OpenStreetMap'
      }).addTo(map);
      mapInstanceRef.current = map;

      // Aguarda um frame para o mapa renderizar
      setTimeout(() => map.invalidateSize(), 100);
    }

    return () => {
      if (mapInstanceRef.current) {
        mapInstanceRef.current.remove();
        mapInstanceRef.current = null;
      }
    };
  }, [showMap]);

  // Atualiza marcadores do mapa
  useEffect(() => {
    if (!mapInstanceRef.current || !order) return;

    const map = mapInstanceRef.current;
    map.eachLayer(layer => {
      if (layer instanceof L.Marker) map.removeLayer(layer);
    });

    // Marcador do restaurante
    if (order.restaurant?.latitude && order.restaurant?.longitude) {
      const restaurantIcon = L.divIcon({
        html: '<div style="background:#f59e0b;width:24px;height:24px;border-radius:50%;display:flex;align-items:center;justify-content:center;border:3px solid white;box-shadow:0 2px 8px rgba(0,0,0,0.3)"><svg width="12" height="12" viewBox="0 0 24 24" fill="white"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z"/></svg></div>',
        className: '',
        iconSize: [24, 24],
        iconAnchor: [12, 12]
      });
      L.marker([order.restaurant.latitude, order.restaurant.longitude], { icon: restaurantIcon })
        .addTo(map)
        .bindPopup(`<b>${escapeHtml(order.restaurant.name)}</b><br>${escapeHtml(order.restaurant.address)}`);
    }

    // Marcador do cliente
    if (order.delivery_address?.latitude && order.delivery_address?.longitude) {
      const customerIcon = L.divIcon({
        html: '<div style="background:#22c55e;width:24px;height:24px;border-radius:50%;display:flex;align-items:center;justify-content:center;border:3px solid white;box-shadow:0 2px 8px rgba(0,0,0,0.3)"><svg width="12" height="12" viewBox="0 0 24 24" fill="white"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z"/></svg></div>',
        className: '',
        iconSize: [24, 24],
        iconAnchor: [12, 12]
      });
      L.marker([order.delivery_address.latitude, order.delivery_address.longitude], { icon: customerIcon })
        .addTo(map)
        .bindPopup(`<b>${escapeHtml(order.customer?.name)}</b><br>${escapeHtml(order.delivery_address.street)}`);
    }

    // Ajusta zoom para mostrar ambos
    const bounds = [];
    if (order.restaurant?.latitude) bounds.push([order.restaurant.latitude, order.restaurant.longitude]);
    if (order.delivery_address?.latitude) bounds.push([order.delivery_address.latitude, order.delivery_address.longitude]);
    if (bounds.length > 0) {
      map.fitBounds(bounds, { padding: [50, 50] });
    }
  }, [showMap, order]);

  if (!showMap) return null;

  return (
    <div style={{
      position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.9)',
      display: 'flex', flexDirection: 'column', zIndex: 100
    }}>
      <div style={{
        padding: '1rem', display: 'flex',
        justifyContent: 'space-between', alignItems: 'center',
        background: 'white'
      }}>
        <h3 style={{ fontSize: '1rem', fontWeight: 600 }}>
          {mapTarget === 'restaurant' ? 'Restaurante' : 'Cliente'}
        </h3>
        <button onClick={onClose}
          style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#64748b' }}>
          <X size={24} />
        </button>
      </div>
      <div ref={mapRef} style={{ flex: 1, minHeight: '400px' }} />
      <div style={{ padding: '1rem', background: 'white', display: 'flex', gap: '0.75rem' }}>
        <button
          onClick={onNavigate}
          style={{
            flex: 1, padding: '0.875rem', borderRadius: '0.5rem',
            border: 'none', background: '#2563eb', color: 'white',
            fontSize: '0.9375rem', fontWeight: 600, cursor: 'pointer',
            display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem'
          }}
        >
          <Navigation size={18} /> Navegar
        </button>
        <button
          onClick={onCall}
          style={{
            flex: 1, padding: '0.875rem', borderRadius: '0.5rem',
            border: '1.5px solid #e2e8f0', background: 'white', color: '#374151',
            fontSize: '0.9375rem', fontWeight: 600, cursor: 'pointer',
            display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem'
          }}
        >
          <Phone size={18} /> Ligar
        </button>
      </div>
    </div>
  );
};

