    if (!restaurantId) {
      showToast('Selecione um estabelecimento', 'error');
      return;
    }
    const estName = establishments.find(e => e.id === parseInt(restaurantId))?.name || 'estabelecimento';
    if (!window.confirm(`Converter "${editing.user?.first_name}" para entregador próprio de "${estName}"?\n\nO entregador será desativado da plataforma e criado como entregador próprio.`)) return;

    try {
      setFormLoading(true);
      await api.post(`/api/admin/drivers/${editing.id}/convert-to-own`, { restaurant_id: parseInt(restaurantId) });
      showToast(`Entregador convertido para ${estName}!`, 'success');
      setShowEdit(false);
      loadDrivers();
    } catch (err) {
      showToast(err.response?.data?.error || 'Erro ao converter entregador', 'error');
    } finally {
      setFormLoading(false);
    }
  };

  const openCreateForm = () => { setFormData({ ...DEFAULT_FORM }); setFormError(''); setShowForm(true); };

  const copyRegistrationLink = () => {
    const link = `${window.location.origin}/register`;
    const notify = () => showToast('Link copiado!\n\nEnvie para o entregador se cadastrar:\n' + link, 'info');
    navigator.clipboard.writeText(link).then(notify).catch(() => {
      const ta = document.createElement('textarea'); ta.value = link;
      document.body.appendChild(ta); ta.select(); document.execCommand('copy'); document.body.removeChild(ta);
      notify();
    });
  };

  const handleFormChange = (e) => {
    setFormData(prev => ({ ...prev, [e.target.name]: e.target.value }));
    setFormError('');
  };

  const handleSubmitForm = async (e) => {
    e.preventDefault();
    if (!formData.email || !formData.first_name || !formData.last_name) {
      setFormError('Email, nome e sobrenome são obrigatórios');
      return;
    }

    try {
      setFormLoading(true);
      const result = await api.post('/api/admin/drivers', formData);
      setShowForm(false);
      loadDrivers();
      showToast('Entregador criado com sucesso! Email: ' + result.driver.email, 'info');
    } catch (err) {
      setFormError(err.response?.data?.error || 'Erro ao criar entregador');
    } finally {
      setFormLoading(false);
    }
  };

  const openDetails = async (driver) => {
    try { const data = await adminService.getDriverDetails(driver.id); setShowDetails(data); } catch (err) { console.error(err); }
  };

  const handleSearchChange = (value) => { setSearch(value); setPage(1); };
  const handleStatusChange = (value) => { setStatusFilter(value); setPage(1); };

  return (
    <div style={{ padding: '1.5rem', maxWidth: '1100px', margin: '0 auto' }}>
      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '1.5rem', flexWrap: 'wrap', gap: '1rem' }}>
        <div>
          <h1 style={{ fontSize: '1.75rem', fontWeight: 700, color: '#1e293b', marginBottom: '0.25rem' }}>Entregadores</h1>
          <p style={{ color: '#64748b', fontSize: '0.9375rem' }}>{total} entregador(es) cadastrado(s)</p>
        </div>
        <div style={{ display: 'flex', gap: '0.75rem' }}>
          <button onClick={copyRegistrationLink} style={{
            display: 'flex', alignItems: 'center', gap: '0.5rem', padding: '0.625rem 1.25rem',
            borderRadius: '0.5rem', border: '1.5px solid #e2e8f0', background: 'white', color: '#374151',
            fontSize: '0.875rem', fontWeight: 500, cursor: 'pointer'
          }}>
            <Copy size={16} /> LINK DE CADASTRO
          </button>
          <button onClick={openCreateForm} style={{
            display: 'flex', alignItems: 'center', gap: '0.5rem', padding: '0.625rem 1.25rem',
            borderRadius: '0.5rem', border: 'none', background: '#2563eb', color: 'white',
            fontSize: '0.875rem', fontWeight: 600, cursor: 'pointer'
          }}>
            <Plus size={18} /> NOVO ENTREGADOR
          </button>
        </div>
      </div>

      <PendingDriversBanner
        pendingDrivers={pendingDrivers}
        onApprove={handleApproveDriver}
        onReject={handleRejectDriver}
      />

      {error && (
        <div style={{ background: '#fef2f2', border: '1px solid #fecaca', color: '#dc2626', padding: '0.75rem 1rem', borderRadius: '0.5rem', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.875rem' }}>
          <AlertCircle size={16} /> {error}
        </div>
      )}

      <DriversTable
        drivers={drivers}
        loading={loading}
        search={search}
        statusFilter={statusFilter}
        page={page}
        totalPages={totalPages}
        onSearchChange={handleSearchChange}
        onStatusChange={handleStatusChange}
        onPageChange={setPage}
        onOpenDetails={openDetails}
        onOpenEdit={openEditForm}
        onDelete={handleDelete}
        onReload={loadDrivers}
      />

      {showForm && (
        <DriverCreateModal
          formData={formData}
          formError={formError}
          formLoading={formLoading}
          isSuperAdmin={isSuperAdmin}
          tenants={tenants}
          squares={squares}
          onClose={() => setShowForm(false)}
          onChange={handleFormChange}
          onSubmit={handleSubmitForm}
        />
      )}

      <DriverDetailsModal
        driver={showDetails}
        onClose={() => setShowDetails(null)}
      />

      {showEdit && (
        <DriverEditModal
          editing={editing}
          editData={editData}
          formError={formError}
          formLoading={formLoading}
          isSuperAdmin={isSuperAdmin}
          tenants={tenants}
          squares={squares}
          establishments={establishments}
          onClose={() => setShowEdit(false)}
          onChange={handleEditFieldChange}
          onSubmit={handleEdit}
          onConvertToOwn={handleConvertToOwn}
        />
      )}

      <style>{`
        @keyframes spin { to { transform: rotate(360deg); } }
        .table-header { display: grid; }
        .table-row:hover { background: #f8fafc; }
        @media (max-width: 768px) { .table-header { display: none; } .table-row { grid-template-columns: 1fr !important; } }
      `}</style>
    </div>
  );
};

export default AdminDriversPage;

import React, { useState, useEffect } from 'react';
import { DollarSign, Plus, Edit, Trash2, X, Save, RefreshCw, AlertCircle, CheckCircle, CloudRain, TrendingUp, Calendar, XCircle } from 'lucide-react';
import { adminService } from '@/lib/api';
import { useSquare } from '@/contexts/SquareContext';
import { showToast } from '@/components/Toast';

const AdminDynamicPricingPage = () => {
  const { squareId } = useSquare();
  const [configs, setConfigs] = useState([]);
  const [squares, setSquares] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [form, setForm] = useState({
    square_id: '',
    rainy_day_active: false, rainy_day_bonus: '3.00',
    high_demand_active: false, high_demand_threshold: '5', high_demand_bonus: '2.00',
    holiday_active: false, holiday_bonus: '5.00',
    cancellation_fee_active: false, cancellation_fee: '5.00'
  });

  useEffect(() => { loadData(); }, [squareId]);

  const loadData = async () => {
    try {
      setLoading(true);
      const [configsRes, squaresRes] = await Promise.all([
        adminService.getDynamicPricing(squareId),
        adminService.getSquares()
      ]);
      setConfigs(configsRes.dynamic_pricing || []);
      setSquares(squaresRes.squares || []);
    } catch {
      setError('Erro ao carregar dados');
    } finally {
      setLoading(false);
    }
  };

  const resetForm = () => {
    setForm({
      square_id: '',
      rainy_day_active: false, rainy_day_bonus: '3.00',
      high_demand_active: false, high_demand_threshold: '5', high_demand_bonus: '2.00',
      holiday_active: false, holiday_bonus: '5.00',
      cancellation_fee_active: false, cancellation_fee: '5.00'
    });
    setEditingId(null);
    setShowForm(false);
    setError('');
  };

  const handleEdit = (config) => {
    setForm({
      square_id: String(config.square_id || ''),
      rainy_day_active: config.rainy_day_active || false,
      rainy_day_bonus: String(config.rainy_day_bonus || '3.00'),
      high_demand_active: config.high_demand_active || false,
      high_demand_threshold: String(config.high_demand_threshold || '5'),
      high_demand_bonus: String(config.high_demand_bonus || '2.00'),
      holiday_active: config.holiday_active || false,
      holiday_bonus: String(config.holiday_bonus || '5.00'),
      cancellation_fee_active: config.cancellation_fee_active || false,
      cancellation_fee: String(config.cancellation_fee || '5.00')
    });
    setEditingId(config.id);
    setShowForm(true);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.square_id) { setError('Praça é obrigatória'); return; }
    try {
      const data = {
        square_id: parseInt(form.square_id),
        rainy_day_active: form.rainy_day_active,
        rainy_day_bonus: parseFloat(form.rainy_day_bonus) || 3.00,
        high_demand_active: form.high_demand_active,
        high_demand_threshold: parseInt(form.high_demand_threshold) || 5,
        high_demand_bonus: parseFloat(form.high_demand_bonus) || 2.00,
        holiday_active: form.holiday_active,
        holiday_bonus: parseFloat(form.holiday_bonus) || 5.00,
        cancellation_fee_active: form.cancellation_fee_active,
        cancellation_fee: parseFloat(form.cancellation_fee) || 5.00
      };
      if (editingId) {
        await adminService.updateDynamicPricing(editingId, data);
        setSuccess('Configuração atualizada!');
      } else {
        await adminService.createDynamicPricing(data);
        setSuccess('Configuração criada!');
      }
      resetForm();
      loadData();
      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      setError(err.response?.data?.error || 'Erro ao salvar');
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Excluir esta configuração de taxas?')) return;
    try {
      await adminService.deleteDynamicPricing(id);
      loadData();
    } catch (err) {
      showToast(err.response?.data?.error || 'Erro ao excluir', 'error');
    }
  };

  const toggleActive = async (config, field) => {
    try {
      await adminService.updateDynamicPricing(config.id, { [field]: !config[field] });
      loadData();
    } catch {
      showToast('Erro ao atualizar', 'error');
    }
  };

  const getSquareName = (id) => {
    const sq = squares.find(s => s.id === id);
    return sq ? `${sq.name} (${sq.city})` : `Praça #${id}`;
  };

  if (loading) {
    return (
      <div style={{ minHeight: '60vh', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ width: '3rem', height: '3rem', border: '3px solid #e2e8f0', borderTopColor: '#2563eb', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
      </div>
    );
  }

  return (
    <div style={{ padding: '1.5rem', maxWidth: '1100px', margin: '0 auto' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem' }}>
        <div>
          <h1 style={{ fontSize: '1.75rem', fontWeight: 700, color: '#1e293b' }}>Taxas Adicionais</h1>
          <p style={{ color: '#64748b', fontSize: '0.9375rem' }}>Configure taxas de chuva, demanda, feriado e cancelamento por praça</p>
        </div>
        <button onClick={() => { resetForm(); setShowForm(true); }}
          style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', padding: '0.625rem 1.25rem', borderRadius: '0.5rem', border: 'none', background: '#2563eb', color: 'white', fontSize: '0.875rem', fontWeight: 600, cursor: 'pointer' }}>
          <Plus size={16} /> Nova Configuração
        </button>
      </div>

      {error && <div style={{ background: '#fef2f2', border: '1px solid #fecaca', color: '#dc2626', padding: '0.75rem', borderRadius: '0.5rem', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.875rem' }}><AlertCircle size={16} /> {error}</div>}
      {success && <div style={{ background: '#dcfce7', border: '1px solid #86efac', color: '#166534', padding: '0.75rem', borderRadius: '0.5rem', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.875rem' }}><CheckCircle size={16} /> {success}</div>}

      {configs.length === 0 ? (
        <div style={{ background: 'white', borderRadius: '0.75rem', padding: '3rem', textAlign: 'center', boxShadow: '0 1px 3px rgba(0,0,0,0.05)' }}>
          <DollarSign size={48} style={{ color: '#64748b', marginBottom: '1rem' }} />
          <p style={{ color: '#64748b', fontSize: '1rem', marginBottom: '0.5rem' }}>Nenhuma configuração de taxas adicionais</p>
          <p style={{ color: '#64748b', fontSize: '0.875rem' }}>Crie uma configuração para cada praça</p>
        </div>
      ) : (
        <div style={{ display: 'grid', gap: '0.75rem' }}>
          {configs.map(config => (
            <div key={config.id} style={{ background: 'white', borderRadius: '0.75rem', padding: '1.25rem', boxShadow: '0 1px 3px rgba(0,0,0,0.05)' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '1rem' }}>
                <div>
                  <span style={{ fontWeight: 600, color: '#1e293b', fontSize: '1rem' }}>{getSquareName(config.square_id)}</span>
                </div>
                <div style={{ display: 'flex', gap: '0.25rem' }}>
                  <button onClick={() => handleEdit(config)} style={{ padding: '0.375rem', borderRadius: '0.375rem', border: 'none', background: 'transparent', cursor: 'pointer', color: '#2563eb' }} title="Editar">
                    <Edit size={16} />
                  </button>
                  <button onClick={() => handleDelete(config.id)} style={{ padding: '0.375rem', borderRadius: '0.375rem', border: 'none', background: 'transparent', cursor: 'pointer', color: '#dc2626' }} title="Excluir">
                    <Trash2 size={16} />
                  </button>
                </div>
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '0.75rem' }}>
                {/* Taxa de Chuva */}
                <div style={{ padding: '0.75rem', borderRadius: '0.5rem', background: config.rainy_day_active ? '#eff6ff' : '#f8fafc', border: `1px solid ${config.rainy_day_active ? '#bfdbfe' : '#e2e8f0'}` }}>
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '0.375rem' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.375rem' }}>
                      <CloudRain size={14} color={config.rainy_day_active ? '#2563eb' : '#64748b'} />
                      <span style={{ fontSize: '0.8125rem', fontWeight: 600, color: '#374151' }}>Taxa de Chuva</span>
                    </div>
                    <button onClick={() => toggleActive(config, 'rainy_day_active')} style={{ padding: '0.125rem 0.5rem', borderRadius: '9999px', border: 'none', background: config.rainy_day_active ? '#2563eb' : '#e2e8f0', color: config.rainy_day_active ? 'white' : '#64748b', fontSize: '0.6875rem', cursor: 'pointer', fontWeight: 600 }}>
                      {config.rainy_day_active ? 'ATIVA' : 'INATIVA'}
                    </button>
                  </div>
                  <span style={{ fontSize: '0.875rem', fontWeight: 700, color: '#1e293b' }}>+R$ {parseFloat(config.rainy_day_bonus || 0).toFixed(2)}</span>
                </div>

                {/* Alta Demanda */}
                <div style={{ padding: '0.75rem', borderRadius: '0.5rem', background: config.high_demand_active ? '#fefce8' : '#f8fafc', border: `1px solid ${config.high_demand_active ? '#fde68a' : '#e2e8f0'}` }}>
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '0.375rem' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.375rem' }}>
                      <TrendingUp size={14} color={config.high_demand_active ? '#ca8a04' : '#64748b'} />
                      <span style={{ fontSize: '0.8125rem', fontWeight: 600, color: '#374151' }}>Alta Demanda</span>
                    </div>
                    <button onClick={() => toggleActive(config, 'high_demand_active')} style={{ padding: '0.125rem 0.5rem', borderRadius: '9999px', border: 'none', background: config.high_demand_active ? '#ca8a04' : '#e2e8f0', color: config.high_demand_active ? 'white' : '#64748b', fontSize: '0.6875rem', cursor: 'pointer', fontWeight: 600 }}>
                      {config.high_demand_active ? 'ATIVA' : 'INATIVA'}
                    </button>
                  </div>
                  <span style={{ fontSize: '0.875rem', fontWeight: 700, color: '#1e293b' }}>+R$ {parseFloat(config.high_demand_bonus || 0).toFixed(2)}</span>
                  <span style={{ fontSize: '0.6875rem', color: '#64748b', marginLeft: '0.25rem' }}>({config.high_demand_threshold}+ pedidos)</span>
                </div>

                {/* Feriado */}
                <div style={{ padding: '0.75rem', borderRadius: '0.5rem', background: config.holiday_active ? '#fdf2f8' : '#f8fafc', border: `1px solid ${config.holiday_active ? '#fbcfe8' : '#e2e8f0'}` }}>
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '0.375rem' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.375rem' }}>
                      <Calendar size={14} color={config.holiday_active ? '#db2777' : '#64748b'} />
                      <span style={{ fontSize: '0.8125rem', fontWeight: 600, color: '#374151' }}>Feriado</span>
                    </div>
                    <button onClick={() => toggleActive(config, 'holiday_active')} style={{ padding: '0.125rem 0.5rem', borderRadius: '9999px', border: 'none', background: config.holiday_active ? '#db2777' : '#e2e8f0', color: config.holiday_active ? 'white' : '#64748b', fontSize: '0.6875rem', cursor: 'pointer', fontWeight: 600 }}>
                      {config.holiday_active ? 'ATIVA' : 'INATIVA'}
                    </button>
                  </div>
                  <span style={{ fontSize: '0.875rem', fontWeight: 700, color: '#1e293b' }}>+R$ {parseFloat(config.holiday_bonus || 0).toFixed(2)}</span>
                </div>

                {/* Cancelamento */}
                <div style={{ padding: '0.75rem', borderRadius: '0.5rem', background: config.cancellation_fee_active ? '#fef2f2' : '#f8fafc', border: `1px solid ${config.cancellation_fee_active ? '#fecaca' : '#e2e8f0'}` }}>
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '0.375rem' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.375rem' }}>
                      <XCircle size={14} color={config.cancellation_fee_active ? '#dc2626' : '#64748b'} />
                      <span style={{ fontSize: '0.8125rem', fontWeight: 600, color: '#374151' }}>Cancelamento</span>
                    </div>
                    <button onClick={() => toggleActive(config, 'cancellation_fee_active')} style={{ padding: '0.125rem 0.5rem', borderRadius: '9999px', border: 'none', background: config.cancellation_fee_active ? '#dc2626' : '#e2e8f0', color: config.cancellation_fee_active ? 'white' : '#64748b', fontSize: '0.6875rem', cursor: 'pointer', fontWeight: 600 }}>
                      {config.cancellation_fee_active ? 'ATIVA' : 'INATIVA'}
                    </button>
                  </div>
                  <span style={{ fontSize: '0.875rem', fontWeight: 700, color: '#1e293b' }}>R$ {parseFloat(config.cancellation_fee || 0).toFixed(2)}</span>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Modal de formulário */}
      {showForm && (
        <>
          <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', zIndex: 99999 }} onClick={resetForm} />
          <div style={{ position: 'fixed', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', background: 'white', borderRadius: '0.75rem', width: '90%', maxWidth: '550px', maxHeight: '90vh', overflow: 'auto', zIndex: 100000, boxShadow: '0 20px 60px rgba(0,0,0,0.3)' }}>
            <div style={{ padding: '1.25rem 1.5rem', borderBottom: '1px solid #f1f5f9', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <h2 style={{ fontSize: '1.125rem', fontWeight: 700, color: '#1e293b' }}>{editingId ? 'Editar Taxas' : 'Nova Configuração de Taxas'}</h2>
              <button onClick={resetForm} style={{ border: 'none', background: 'none', cursor: 'pointer', color: '#64748b' }}><X size={20} /></button>
            </div>
            <form onSubmit={handleSubmit} style={{ padding: '1.5rem' }}>
              <div style={{ marginBottom: '1.25rem' }}>
                <label style={{ display: 'block', fontSize: '0.8125rem', fontWeight: 500, color: '#374151', marginBottom: '0.375rem' }}>Praça *</label>
                <select value={form.square_id} onChange={e => setForm(p => ({ ...p, square_id: e.target.value }))} required disabled={!!editingId}
                  style={{ width: '100%', padding: '0.625rem 0.75rem', border: '1.5px solid #e2e8f0', borderRadius: '0.5rem', fontSize: '0.875rem', outline: 'none', opacity: editingId ? 0.6 : 1 }}>
                  <option value="">Selecione uma praça</option>
                  {squares.map(sq => <option key={sq.id} value={sq.id}>{sq.name} ({sq.city}/{sq.state})</option>)}
                </select>
              </div>

              {/* Taxa de Chuva */}
              <div style={{ marginBottom: '1rem', padding: '1rem', borderRadius: '0.5rem', background: '#eff6ff', border: '1px solid #bfdbfe' }}>
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '0.75rem' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                    <CloudRain size={16} color="#2563eb" />
                    <span style={{ fontWeight: 600, color: '#1e3a5f', fontSize: '0.875rem' }}>Taxa de Chuva</span>
                  </div>
                  <label style={{ display: 'flex', alignItems: 'center', gap: '0.375rem', cursor: 'pointer' }}>
                    <input type="checkbox" checked={form.rainy_day_active} onChange={e => setForm(p => ({ ...p, rainy_day_active: e.target.checked }))} style={{ width: '1rem', height: '1rem' }} />
                    <span style={{ fontSize: '0.75rem', color: '#374151' }}>Ativar</span>
                  </label>
                </div>
                <div>
                  <label style={{ display: 'block', fontSize: '0.75rem', color: '#374151', marginBottom: '0.25rem' }}>Valor do bônus (R$)</label>
                  <input type="number" step="0.01" value={form.rainy_day_bonus} onChange={e => setForm(p => ({ ...p, rainy_day_bonus: e.target.value }))}
                    style={{ width: '100%', padding: '0.5rem', border: '1.5px solid #bfdbfe', borderRadius: '0.375rem', fontSize: '0.875rem', outline: 'none', boxSizing: 'border-box' }} />
                </div>
              </div>

              {/* Alta Demanda */}
              <div style={{ marginBottom: '1rem', padding: '1rem', borderRadius: '0.5rem', background: '#fefce8', border: '1px solid #fde68a' }}>
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '0.75rem' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                    <TrendingUp size={16} color="#ca8a04" />
                    <span style={{ fontWeight: 600, color: '#713f12', fontSize: '0.875rem' }}>Alta Demanda</span>
                  </div>
                  <label style={{ display: 'flex', alignItems: 'center', gap: '0.375rem', cursor: 'pointer' }}>
                    <input type="checkbox" checked={form.high_demand_active} onChange={e => setForm(p => ({ ...p, high_demand_active: e.target.checked }))} style={{ width: '1rem', height: '1rem' }} />
                    <span style={{ fontSize: '0.75rem', color: '#374151' }}>Ativar</span>
                  </label>
                </div>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.75rem' }}>
                  <div>
                    <label style={{ display: 'block', fontSize: '0.75rem', color: '#374151', marginBottom: '0.25rem' }}>Limite de pedidos</label>
                    <input type="number" value={form.high_demand_threshold} onChange={e => setForm(p => ({ ...p, high_demand_threshold: e.target.value }))}
                      style={{ width: '100%', padding: '0.5rem', border: '1.5px solid #fde68a', borderRadius: '0.375rem', fontSize: '0.875rem', outline: 'none', boxSizing: 'border-box' }} />
                  </div>
                  <div>
                    <label style={{ display: 'block', fontSize: '0.75rem', color: '#374151', marginBottom: '0.25rem' }}>Bônus (R$)</label>
                    <input type="number" step="0.01" value={form.high_demand_bonus} onChange={e => setForm(p => ({ ...p, high_demand_bonus: e.target.value }))}
                      style={{ width: '100%', padding: '0.5rem', border: '1.5px solid #fde68a', borderRadius: '0.375rem', fontSize: '0.875rem', outline: 'none', boxSizing: 'border-box' }} />
                  </div>
                </div>
              </div>

              {/* Feriado */}
              <div style={{ marginBottom: '1rem', padding: '1rem', borderRadius: '0.5rem', background: '#fdf2f8', border: '1px solid #fbcfe8' }}>
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '0.75rem' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                    <Calendar size={16} color="#db2777" />
                    <span style={{ fontWeight: 600, color: '#831843', fontSize: '0.875rem' }}>Feriado</span>
                  </div>
                  <label style={{ display: 'flex', alignItems: 'center', gap: '0.375rem', cursor: 'pointer' }}>
                    <input type="checkbox" checked={form.holiday_active} onChange={e => setForm(p => ({ ...p, holiday_active: e.target.checked }))} style={{ width: '1rem', height: '1rem' }} />
                    <span style={{ fontSize: '0.75rem', color: '#374151' }}>Ativar</span>
                  </label>
                </div>
                <div>
                  <label style={{ display: 'block', fontSize: '0.75rem', color: '#374151', marginBottom: '0.25rem' }}>Valor do bônus (R$)</label>
                  <input type="number" step="0.01" value={form.holiday_bonus} onChange={e => setForm(p => ({ ...p, holiday_bonus: e.target.value }))}
                    style={{ width: '100%', padding: '0.5rem', border: '1.5px solid #fbcfe8', borderRadius: '0.375rem', fontSize: '0.875rem', outline: 'none', boxSizing: 'border-box' }} />
                </div>
              </div>

              {/* Cancelamento */}
              <div style={{ marginBottom: '1rem', padding: '1rem', borderRadius: '0.5rem', background: '#fef2f2', border: '1px solid #fecaca' }}>
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '0.75rem' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                    <XCircle size={16} color="#dc2626" />
                    <span style={{ fontWeight: 600, color: '#7f1d1d', fontSize: '0.875rem' }}>Taxa de Cancelamento</span>
                  </div>
                  <label style={{ display: 'flex', alignItems: 'center', gap: '0.375rem', cursor: 'pointer' }}>
                    <input type="checkbox" checked={form.cancellation_fee_active} onChange={e => setForm(p => ({ ...p, cancellation_fee_active: e.target.checked }))} style={{ width: '1rem', height: '1rem' }} />
                    <span style={{ fontSize: '0.75rem', color: '#374151' }}>Ativar</span>
                  </label>
                </div>
                <div>
                  <label style={{ display: 'block', fontSize: '0.75rem', color: '#374151', marginBottom: '0.25rem' }}>Valor da taxa (R$)</label>
                  <input type="number" step="0.01" value={form.cancellation_fee} onChange={e => setForm(p => ({ ...p, cancellation_fee: e.target.value }))}
                    style={{ width: '100%', padding: '0.5rem', border: '1.5px solid #fecaca', borderRadius: '0.375rem', fontSize: '0.875rem', outline: 'none', boxSizing: 'border-box' }} />
                </div>
              </div>

              <div style={{ display: 'flex', gap: '0.75rem', justifyContent: 'flex-end', marginTop: '1.5rem' }}>
                <button type="button" onClick={resetForm} style={{ padding: '0.625rem 1.25rem', borderRadius: '0.5rem', border: '1.5px solid #e2e8f0', background: 'white', fontSize: '0.875rem', cursor: 'pointer' }}>Cancelar</button>
                <button type="submit" style={{ padding: '0.625rem 1.25rem', borderRadius: '0.5rem', border: 'none', background: '#2563eb', color: 'white', fontSize: '0.875rem', fontWeight: 600, cursor: 'pointer' }}>
                  <Save size={14} style={{ marginRight: '0.375rem', verticalAlign: 'middle' }} />
                  {editingId ? 'Atualizar' : 'Criar Configuração'}
                </button>
              </div>
            </form>
          </div>
        </>
      )}

      <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
    </div>
  );
};

export default AdminDynamicPricingPage;

import React, { useState, useEffect } from 'react';
import { Plus, Copy, AlertCircle } from 'lucide-react';
import { adminService } from '@/lib/api';
import api from '@/lib/api';
import { useSquare } from '@/contexts/SquareContext';
import { showToast } from '@/components/Toast';
import EstablishmentStats from './establishments/EstablishmentStats';
import PendingApprovals from './establishments/PendingApprovals';
import EstablishmentsList from './establishments/EstablishmentsList';
import EstablishmentForm from './establishments/EstablishmentForm';
import EstablishmentDetails from './establishments/EstablishmentDetails';

const AdminEstablishmentsPage = () => {
  const { squareId } = useSquare();
  const [establishments, setEstablishments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [total, setTotal] = useState(0);
  const [squares, setSquares] = useState([]);
  const [tenants, setTenants] = useState([]);
  const [pendingEstablishments, setPendingEstablishments] = useState([]);

  const user = JSON.parse(localStorage.getItem('user') || '{}');
  const isSuperAdmin = user?.user_type === 'ADMIN' && user?.is_super_admin;

  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);
  const [showDetails, setShowDetails] = useState(null);

  useEffect(() => {
    loadEstablishments();
    loadSquares();
    loadPendingEstablishments();
    if (isSuperAdmin) loadTenants();
  }, [page, search, squareId]);

  const loadSquares = async () => {
    try { const data = await adminService.getSquares(); setSquares(data.squares || []); } catch (e) {}
  };

  const loadTenants = async () => {
    try { const res = await api.get('/api/admin/tenants'); setTenants(res.data.tenants || []); } catch (e) { setTenants([]); }
  };

  const loadPendingEstablishments = async () => {
    try {
      const res = await api.get('/api/admin/pending-users');
      setPendingEstablishments((res.data.users || []).filter(u => u.user_type === 'CLIENT'));
    } catch (err) {}
  };

  const loadEstablishments = async () => {
    try {
      setLoading(true);
      const data = await adminService.getEstablishments(page, 20, search, squareId);
      setEstablishments(data.establishments);
      setTotalPages(data.pages);
      setTotal(data.total);
    } catch (err) {
      setError('Erro ao carregar estabelecimentos');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleApprove = async (userId) => {
    try {
      await api.post(`/api/admin/users/${userId}/approve`);
      showToast('Estabelecimento aprovado!', 'success');
      loadPendingEstablishments();
      loadEstablishments();
    } catch (err) { showToast(err.response?.data?.error || 'Erro ao aprovar', 'error'); }
  };

  const handleReject = async (userId) => {
    if (!window.confirm('Rejeitar e excluir este cadastro?')) return;
    try {
      await api.post(`/api/admin/users/${userId}/reject`);
      showToast('Cadastro rejeitado', 'info');
      loadPendingEstablishments();
    } catch (err) { showToast(err.response?.data?.error || 'Erro ao rejeitar', 'error'); }
  };

  const handleToggleOwnDrivers = async (establishment) => {
    const newValue = !establishment.has_own_drivers;
    const confirmMsg = newValue
      ? `Ativar entregadores próprios para "${establishment.name}"?\n\nO estabelecimento terá acesso ao menu "Meus Entregadores" e poderá cadastrar seus próprios entregadores.`
      : `Desativar entregadores próprios para "${establishment.name}"?\n\nO estabelecimento usará apenas entregadores da plataforma MUV.`;
    if (!window.confirm(confirmMsg)) return;
    try {
      await api.put(`/api/admin/establishments/${establishment.id}/subscription`, { has_own_drivers: newValue });
      setShowDetails(null);
      await loadEstablishments();
    } catch (err) { showToast(err.response?.data?.error || 'Erro ao alterar configuração', 'error'); }
  };

  const openCreateForm = () => { setEditing(null); setShowForm(true); };
  const openEditForm = (est) => { setEditing(est); setShowForm(true); };

  const handleFormSave = () => { setShowForm(false); loadEstablishments(); };

  const copyRegistrationLink = () => {
    const link = `${window.location.origin}/client/register`;
    navigator.clipboard.writeText(link).then(() => {
      showToast('Link copiado!\n\nEnvie para o estabelecimento se cadastrar:\n' + link, 'info');
    }).catch(() => {
      const textArea = document.createElement('textarea');
      textArea.value = link;
      document.body.appendChild(textArea);
      textArea.select();
      document.execCommand('copy');
      document.body.removeChild(textArea);
      showToast('Link copiado!\n\nEnvie para o estabelecimento se cadastrar:\n' + link, 'info');
    });
  };

  const handleDelete = async (id, hasOrders) => {
    if (hasOrders) {
      if (!window.confirm('Este estabelecimento tem pedidos vinculados. Deseja excluir mesmo assim? Todos os pedidos serão apagados.')) return;
    } else {
      if (!window.confirm('Tem certeza que deseja excluir este estabelecimento?')) return;
    }
    try { await adminService.deleteEstablishment(id, hasOrders); loadEstablishments(); }
    catch (err) { showToast(err.response?.data?.error || 'Erro ao excluir', 'error'); }
  };

  const openDetails = async (id) => {
    try { const data = await adminService.getEstablishmentDetails(id); setShowDetails(data); }
    catch (err) { showToast('Erro ao carregar detalhes', 'error'); }
  };

  const toggleActive = async (est) => {
    try { await adminService.updateEstablishment(est.id, { is_active: !est.is_active }); loadEstablishments(); }
    catch (err) { showToast('Erro ao alterar status', 'error'); }
  };

  return (
    <div style={{ padding: '1.5rem', maxWidth: '1280px', margin: '0 auto' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '1.5rem', flexWrap: 'wrap', gap: '1rem' }}>
        <div>
          <h1 style={{ fontSize: '1.75rem', fontWeight: 700, color: '#1e293b', marginBottom: '0.25rem' }}>Estabelecimentos</h1>
          <p style={{ color: '#64748b', fontSize: '0.9375rem' }}>Gerencie todos os estabelecimentos do sistema</p>
        </div>
        <div style={{ display: 'flex', gap: '0.75rem' }}>
          <button onClick={copyRegistrationLink} style={{
            display: 'flex', alignItems: 'center', gap: '0.5rem', padding: '0.625rem 1.25rem',
            borderRadius: '0.5rem', border: '1.5px solid #e2e8f0', background: 'white', color: '#374151',
            fontSize: '0.875rem', fontWeight: 500, cursor: 'pointer'
          }}>
            <Copy size={16} /> LINK DE CADASTRO
          </button>
          <button onClick={openCreateForm} style={{
            display: 'flex', alignItems: 'center', gap: '0.5rem', padding: '0.625rem 1.25rem',
            borderRadius: '0.5rem', background: '#2563eb', color: 'white', border: 'none',
            fontSize: '0.875rem', fontWeight: 600, cursor: 'pointer', transition: 'all 0.15s'
          }}
            onMouseEnter={e => e.currentTarget.style.background = '#1d4ed8'}
            onMouseLeave={e => e.currentTarget.style.background = '#2563eb'}
          >
            <Plus size={18} /> NOVO ESTABELECIMENTO
          </button>
        </div>
      </div>

      {error && (
        <div style={{ background: '#fef2f2', border: '1px solid #fecaca', color: '#dc2626', padding: '0.75rem 1rem', borderRadius: '0.5rem', marginBottom: '1.5rem', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.875rem' }}>
          <AlertCircle size={16} /> {error}
        </div>
      )}

      <EstablishmentStats establishments={establishments} total={total} />
      <PendingApprovals pendingEstablishments={pendingEstablishments} onApprove={handleApprove} onReject={handleReject} />
      <EstablishmentsList
        establishments={establishments} loading={loading} search={search}
        page={page} totalPages={totalPages}
        onSearch={e => { setSearch(e.target.value); setPage(1); }}
        onPageChange={setPage} onOpenDetails={openDetails}
        onEdit={openEditForm} onDelete={handleDelete} onToggleActive={toggleActive}
      />

      {showForm && (
        <EstablishmentForm
          editing={editing} isSuperAdmin={isSuperAdmin}
          squares={squares} tenants={tenants}
          onClose={() => setShowForm(false)} onSave={handleFormSave}
        />
      )}

      {showDetails && (
        <EstablishmentDetails
          details={showDetails}
          onClose={() => setShowDetails(null)}
          onEdit={details => { setShowDetails(null); openEditForm(details); }}
          onToggleOwnDrivers={handleToggleOwnDrivers}
        />
      )}

      <style>{`
        @keyframes spin { to { transform: rotate(360deg); } }
        .table-header { display: grid; }
        .table-row:hover { background: #f8fafc; }
        @media (max-width: 768px) {
          .table-header { display: none; }
          .table-row { grid-template-columns: 1fr !important; gap: 0.5rem; }
        }
      `}</style>
    </div>
  );
};

export default AdminEstablishmentsPage;

import React, { useState, useEffect } from 'react';
import {
  DollarSign, TrendingUp, TrendingDown, Package, Clock,
  AlertCircle, Store, Bike, ArrowUpRight, BarChart3,
  Percent, Wallet, ArrowDownRight, CreditCard
} from 'lucide-react';
import api, { adminService, utils } from '@/lib/api';
import { useSquare } from '@/contexts/SquareContext';
import DateRangeFilter from '@/components/DateRangeFilter';

const AdminFinancePage = () => {
  const { squareId } = useSquare();
  const [data, setData] = useState(null);
  const [estData, setEstData] = useState([]);
  const [driverPayments, setDriverPayments] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [period, setPeriod] = useState('month');
  const [dateRange, setDateRange] = useState(null);
  const [commission, setCommission] = useState(30); // % que o admin retém
  const [savingCommission, setSavingCommission] = useState(false);

  useEffect(() => { loadData(); }, [squareId]);
  useEffect(() => { loadData(); }, [dateRange]);

  const loadData = async () => {
    try {
      setLoading(true);

      const params = {};
      if (squareId) params.square_id = squareId;

      const [finance, establishments, paymentsRes, configRes] = await Promise.all([
        adminService.getFinanceDashboard('custom', dateRange?.startDate, dateRange?.endDate, squareId),
        adminService.getFinanceByEstablishment('custom', dateRange?.startDate, dateRange?.endDate, squareId),
        api.get('/api/admin/driver-payments', { params }),
        api.get('/api/admin/settings')
      ]);

      setData(finance);
      setEstData(establishments.establishments || []);
      setDriverPayments(paymentsRes.data);
      if (configRes.data.commission_rate) setCommission(parseInt(configRes.data.commission_rate));
    } catch (err) {
      setError('Erro ao carregar dados financeiros');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const saveCommission = async () => {
    try {
      setSavingCommission(true);
      await api.put('/api/admin/settings', { commission_rate: commission.toString() });
    } catch (err) {
      console.error(err);
    } finally {
      setSavingCommission(false);
    }
  };

  // Calculos financeiros - baseado em FRETE (km), NAO em valor dos itens
  // Frete total cobrado dos estabelecimentos
  const totalFromEstablishments = data?.total_delivery_fees || 0;
  // O que entregadores devem receber (70% do frete)
  const driverPercentage = 100 - commission;
  const totalToDrivers = totalFromEstablishments * (driverPercentage / 100);
  // Lucro do admin (30% do frete)
  const adminRetention = totalFromEstablishments * (commission / 100);
  const retentionRate = commission;

  if (loading) {
    return (
      <div style={{ minHeight: '60vh', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ width: '3rem', height: '3rem', border: '3px solid #e2e8f0', borderTopColor: '#2563eb', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
      </div>
    );
  }

  return (
    <div style={{ padding: '1.5rem', maxWidth: '1280px', margin: '0 auto' }}>
      {/* Header */}
      <div style={{ marginBottom: '1.5rem' }}>
        <h1 style={{ fontSize: '1.75rem', fontWeight: 700, color: '#1e293b', marginBottom: '0.25rem' }}>Financeiro</h1>
        <p style={{ color: '#64748b', fontSize: '0.9375rem' }}>Controle de recebimentos, pagamentos e comissões</p>
      </div>

      {error && (
        <div style={{ background: '#fef2f2', border: '1px solid #fecaca', color: '#dc2626', padding: '0.75rem 1rem', borderRadius: '0.5rem', marginBottom: '1.5rem', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.875rem' }}>
          <AlertCircle size={16} /> {error}
        </div>
      )}

      {/* Filtro de Datas */}
      <DateRangeFilter onChange={(range) => setDateRange(range)} />

      {/* Fluxo Financeiro */}
      <div style={{ background: 'white', borderRadius: '0.75rem', boxShadow: '0 1px 3px rgba(0,0,0,0.05)', marginBottom: '1.5rem', overflow: 'hidden' }}>
        <div style={{ padding: '1.25rem 1.5rem', borderBottom: '1px solid #f1f5f9', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <Wallet size={18} style={{ color: '#2563eb' }} />
          <span style={{ fontWeight: 600, color: '#1e293b' }}>Fluxo Financeiro</span>
        </div>
        <div style={{ padding: '1.5rem' }}>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '1rem' }}>
            {/* Recebido dos estabelecimentos */}
            <div style={{ background: '#f0fdf4', borderRadius: '0.75rem', padding: '1.25rem', border: '1px solid #bbf7d0' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '0.5rem' }}>
                <ArrowDownRight size={18} style={{ color: '#16a34a' }} />
                <span style={{ fontSize: '0.8125rem', color: '#16a34a', fontWeight: 500 }}>Frete Cobrado (Estabelecimentos)</span>
              </div>
              <p style={{ fontSize: '1.5rem', fontWeight: 700, color: '#166534' }}>{utils.formatCurrency(totalFromEstablishments)}</p>
              <p style={{ fontSize: '0.6875rem', color: '#16a34a', marginTop: '0.25rem' }}>Frete total cobrado</p>
            </div>

            {/* Pago aos entregadores */}
            <div style={{ background: '#fef2f2', borderRadius: '0.75rem', padding: '1.25rem', border: '1px solid #fecaca' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '0.5rem' }}>
                <ArrowUpRight size={18} style={{ color: '#dc2626' }} />
                <span style={{ fontSize: '0.8125rem', color: '#dc2626', fontWeight: 500 }}>A Pagar (Entregadores)</span>
              </div>
              <p style={{ fontSize: '1.5rem', fontWeight: 700, color: '#991b1b' }}>{utils.formatCurrency(totalToDrivers)}</p>
              <p style={{ fontSize: '0.6875rem', color: '#dc2626', marginTop: '0.25rem' }}>{driverPayments?.total_drivers || 0} entregadores</p>
            </div>

            {/* Lucro do admin */}
            <div style={{ background: '#eff6ff', borderRadius: '0.75rem', padding: '1.25rem', border: '1px solid #bfdbfe' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '0.5rem' }}>
                <TrendingUp size={18} style={{ color: '#2563eb' }} />
                <span style={{ fontSize: '0.8125rem', color: '#2563eb', fontWeight: 500 }}>Retenção (Nosso Lucro)</span>
              </div>
              <p style={{ fontSize: '1.5rem', fontWeight: 700, color: '#1e40af' }}>{utils.formatCurrency(adminRetention)}</p>
              <p style={{ fontSize: '0.6875rem', color: '#2563eb', marginTop: '0.25rem' }}>{retentionRate}% de retenção</p>
            </div>
          </div>

          {/* Barra de composicao */}
          <div style={{ marginTop: '1.5rem' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.5rem' }}>
              <span style={{ fontSize: '0.75rem', color: '#64748b' }}>Composição do Frete</span>
              <span style={{ fontSize: '0.75rem', color: '#64748b' }}>100%</span>
            </div>
            <div style={{ height: '2rem', borderRadius: '0.5rem', overflow: 'hidden', display: 'flex' }}>
              <div style={{ width: `${100 - commission}%`, background: '#22c55e', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '0.6875rem', fontWeight: 600, color: 'white' }}>
                Entregadores ({100 - commission}%)
              </div>
              <div style={{ width: `${commission}%`, background: '#2563eb', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '0.6875rem', fontWeight: 600, color: 'white' }}>
                Admin ({commission}%)
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Configuracao de comissao */}
      <div style={{ background: 'white', borderRadius: '0.75rem', boxShadow: '0 1px 3px rgba(0,0,0,0.05)', marginBottom: '1.5rem' }}>
        <div style={{ padding: '1.25rem 1.5rem', borderBottom: '1px solid #f1f5f9', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <Percent size={18} style={{ color: '#8b5cf6' }} />
          <span style={{ fontWeight: 600, color: '#1e293b' }}>Taxa de Retenção (Comissão)</span>
        </div>
        <div style={{ padding: '1.5rem', display: 'flex', alignItems: 'center', gap: '1.5rem', flexWrap: 'wrap' }}>
          <div style={{ flex: 1, minWidth: '200px' }}>
            <label style={{ display: 'block', fontSize: '0.8125rem', fontWeight: 500, color: '#374151', marginBottom: '0.375rem' }}>
              Percentual retido pelo admin (%)
            </label>
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
              <input
                type="range"
                min="0" max="50" value={commission}
                onChange={e => setCommission(parseInt(e.target.value))}
                style={{ flex: 1 }}
              />
              <span style={{ fontSize: '1.5rem', fontWeight: 700, color: '#1e293b', minWidth: '60px', textAlign: 'right' }}>
                {commission}%
              </span>
            </div>
            <p style={{ fontSize: '0.75rem', color: '#64748b', marginTop: '0.25rem' }}>
              Entregadores recebem {100 - commission}% • Admin retém {commission}%
            </p>
          </div>
          <button onClick={saveCommission} disabled={savingCommission} style={{
            padding: '0.625rem 1.5rem', borderRadius: '0.5rem', border: 'none',
            background: '#8b5cf6', color: 'white', fontSize: '0.875rem', fontWeight: 600,
            cursor: savingCommission ? 'not-allowed' : 'pointer', opacity: savingCommission ? 0.7 : 1
          }}>
            {savingCommission ? 'Salvando...' : 'Salvar Taxa'}
          </button>
        </div>
      </div>

      {/* Resumo por Estabelecimento */}
      <div style={{ background: 'white', borderRadius: '0.75rem', boxShadow: '0 1px 3px rgba(0,0,0,0.05)', marginBottom: '1.5rem' }}>
        <div style={{ padding: '1.25rem 1.5rem', borderBottom: '1px solid #f1f5f9', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <Store size={18} style={{ color: '#0d9488' }} />
          <span style={{ fontWeight: 600, color: '#1e293b' }}>Recebimentos por Estabelecimento</span>
        </div>
        <div style={{ overflowX: 'auto' }}>
          <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr 1fr 1fr 1fr', padding: '0.75rem 1.5rem', borderBottom: '1px solid #f1f5f9', background: '#f8fafc', fontSize: '0.6875rem', fontWeight: 600, color: '#64748b', textTransform: 'uppercase', minWidth: '600px' }}>
            <span>Estabelecimento</span><span style={{ textAlign: 'center' }}>Pedidos</span><span style={{ textAlign: 'right' }}>Frete Total</span><span style={{ textAlign: 'right' }}>Ticket Médio</span>
          </div>
          {estData.length === 0 ? (
            <p style={{ textAlign: 'center', padding: '2rem', color: '#64748b' }}>Sem dados</p>
          ) : (
            estData.map((est, i) => (
              <div key={est.id} style={{ display: 'grid', gridTemplateColumns: '2fr 1fr 1fr 1fr 1fr', padding: '0.75rem 1.5rem', borderBottom: i < estData.length - 1 ? '1px solid #f8fafc' : 'none', fontSize: '0.8125rem', minWidth: '600px' }}>
                <span style={{ fontWeight: 500, color: '#1e293b' }}>{est.name}</span>
                <span style={{ textAlign: 'center', color: '#64748b' }}>{est.total_orders}</span>
                <span style={{ textAlign: 'right', color: '#16a34a', fontWeight: 500 }}>{utils.formatCurrency(est.delivery_fees || 0)}</span>
                <span style={{ textAlign: 'right', color: '#0d9488', fontWeight: 600 }}>{utils.formatCurrency(est.delivery_fees)}</span>
                <span style={{ textAlign: 'right', color: '#64748b' }}>{utils.formatCurrency(est.delivery_fees && est.total_orders ? (est.delivery_fees / est.total_orders) : 0)}</span>
              </div>
            ))
          )}
        </div>
      </div>

      {/* Pendencias de Pagamento aos Entregadores */}
      <div style={{ background: 'white', borderRadius: '0.75rem', boxShadow: '0 1px 3px rgba(0,0,0,0.05)' }}>
        <div style={{ padding: '1.25rem 1.5rem', borderBottom: '1px solid #f1f5f9', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <Bike size={18} style={{ color: '#f59e0b' }} />
          <span style={{ fontWeight: 600, color: '#1e293b' }}>Pagamentos Pendentes aos Entregadores</span>
        </div>
        <div style={{ overflowX: 'auto' }}>
          <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr 1fr 1fr 1fr', padding: '0.75rem 1.5rem', borderBottom: '1px solid #f1f5f9', background: '#f8fafc', fontSize: '0.6875rem', fontWeight: 600, color: '#64748b', textTransform: 'uppercase', minWidth: '600px' }}>
            <span>Entregador</span><span style={{ textAlign: 'center' }}>Entregas</span><span style={{ textAlign: 'center' }}>Avaliação</span><span style={{ textAlign: 'center' }}>Pagamentos</span><span style={{ textAlign: 'right' }}>Valor Pendente</span>
          </div>
          {driverPayments?.drivers?.length === 0 ? (
            <p style={{ textAlign: 'center', padding: '2rem', color: '#64748b' }}>Nenhum pagamento pendente</p>
          ) : (
            driverPayments?.drivers?.map((driver, i) => (
              <div key={driver.id} style={{ display: 'grid', gridTemplateColumns: '2fr 1fr 1fr 1fr 1fr', padding: '0.75rem 1.5rem', borderBottom: i < (driverPayments?.drivers?.length || 0) - 1 ? '1px solid #f8fafc' : 'none', fontSize: '0.8125rem', minWidth: '600px' }}>
                <div>
                  <span style={{ fontWeight: 500, color: '#1e293b' }}>{driver.name}</span>
                  {driver.pix_key && <p style={{ fontSize: '0.625rem', color: '#0d9488' }}>PIX: {driver.pix_key}</p>}
                </div>
                <span style={{ textAlign: 'center', color: '#64748b' }}>{driver.total_deliveries}</span>
                <span style={{ textAlign: 'center', color: driver.rating >= 4 ? '#16a34a' : driver.rating >= 3 ? '#f59e0b' : '#dc2626' }}>
                  {driver.rating ? `${driver.rating} ⭐` : '-'}
                </span>
                <span style={{ textAlign: 'center' }}>
                  <span style={{ padding: '0.125rem 0.5rem', borderRadius: '9999px', fontSize: '0.6875rem', fontWeight: 600, background: '#fef3c7', color: '#d97706' }}>
                    {driver.pending_payments}
                  </span>
                </span>
                <span style={{ textAlign: 'right', fontWeight: 700, color: '#dc2626' }}>
                  {utils.formatCurrency(driver.pending_amount)}
                </span>
              </div>
            ))
          )}
        </div>
      </div>

      <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
    </div>
  );
};

export default AdminFinancePage;

import React, { useState, useEffect } from 'react';
import { FileText, RefreshCw, CheckCircle, AlertCircle, QrCode, ExternalLink, Bell } from 'lucide-react';
import api from '@/lib/api';

const AdminInvoicesPage = () => {
  const [invoices, setInvoices] = useState([]);
  const [restaurants, setRestaurants] = useState([]);
  const [loading, setLoading] = useState(true);
  const [generating, setGenerating] = useState(false);
  const [chargingId, setChargingId] = useState(null);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [filter, setFilter] = useState('all');
  const [paymentLinks, setPaymentLinks] = useState({});
  const [selectedRestaurant, setSelectedRestaurant] = useState('');
  const [showGenerateModal, setShowGenerateModal] = useState(false);

  useEffect(() => { loadInvoices(); loadRestaurants(); }, [filter]);

  const loadRestaurants = async () => {
    try {
      const response = await api.get('/api/admin/establishments');
      setRestaurants(response.data.establishments || response.data || []);
    } catch { /* silent */ }
  };

  const loadInvoices = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams();
      if (filter !== 'all') params.append('status', filter.toUpperCase());
      const response = await api.get(`/api/admin/invoices?${params.toString()}`);
      setInvoices(response.data.invoices || []);
    } catch {
      setError('Erro ao carregar faturas');
    } finally {
      setLoading(false);
    }
  };

  const handleGenerate = async (period, restaurantId) => {
    try {
      setGenerating(true);
      setError('');
      let body = {};
      if (period === 'current_week') {
        const today = new Date();
        const monday = new Date(today);
        monday.setDate(today.getDate() - today.getDay() + (today.getDay() === 0 ? -6 : 1));
        const sunday = new Date(monday);
        sunday.setDate(monday.getDate() + 6);
        body.week_start = monday.toISOString().split('T')[0] + 'T00:00:00';
        body.week_end = sunday.toISOString().split('T')[0] + 'T23:59:59';
      }
      if (restaurantId) body.restaurant_id = parseInt(restaurantId);
      const response = await api.post('/api/admin/invoices/generate', body);
      setSuccess(response.data.message + (response.data.skipped?.length ? ` (${response.data.skipped.length} já existentes)` : ''));
      setShowGenerateModal(false);
      setSelectedRestaurant('');
      loadInvoices();
      setTimeout(() => setSuccess(''), 5000);
    } catch (err) {
      setError(err.response?.data?.error || 'Erro ao gerar faturas');
    } finally {
      setGenerating(false);
    }
  };

  const handlePay = async (id) => {
    if (!confirm('Confirmar pagamento? Isso desbloqueará o saldo dos entregadores.')) return;
    try {
      const response = await api.post(`/api/admin/invoices/${id}/pay`);
      setSuccess(response.data.message);
      loadInvoices();
      setTimeout(() => setSuccess(''), 5000);
    } catch (err) {
      setError(err.response?.data?.error || 'Erro ao processar pagamento');
    }
  };

  const handleCharge = async (id) => {
    if (!confirm('Gerar cobrança PIX no Asaas para esta fatura?')) return;
    try {
      setChargingId(id);
      setError('');
      const response = await api.post(`/api/admin/invoices/${id}/charge`);
      if (response.data.payment_url) {
        setPaymentLinks(prev => ({ ...prev, [id]: response.data.payment_url }));
        setSuccess('Cobrança PIX criada! Clique no link para copiar ou envie para o estabelecimento.');
      }
      setTimeout(() => setSuccess(''), 5000);
    } catch (err) {
      setError(err.response?.data?.error || 'Erro ao gerar cobrança. Verifique se o Asaas está configurado.');
    } finally {
      setChargingId(null);
    }
  };

  const handleSendLink = async (id) => {
    const url = paymentLinks[id];
    if (!url) return;
    try {
      await api.post(`/api/admin/invoices/${id}/send-link`, { payment_url: url });
      setSuccess('Link de pagamento enviado para o estabelecimento!');
      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      setError(err.response?.data?.error || 'Erro ao enviar link.');
    }
  };

  const statusBadge = (status) => {
    const styles = {
      PENDING: { bg: '#fef3c7', color: '#d97706', label: 'Pendente' },
      PAID: { bg: '#dcfce7', color: '#166534', label: 'Paga' },
      OVERDUE: { bg: '#fef2f2', color: '#dc2626', label: 'Vencida' }
    };
    const s = styles[status] || styles.PENDING;
    return (
      <span style={{ padding: '0.25rem 0.75rem', borderRadius: '9999px', fontSize: '0.75rem', fontWeight: 600, background: s.bg, color: s.color }}>
        {s.label}
      </span>
    );
  };

  if (loading) {
    return (
      <div style={{ minHeight: '60vh', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ width: '3rem', height: '3rem', border: '3px solid #e2e8f0', borderTopColor: '#2563eb', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
      </div>
    );
  }

  return (
    <div style={{ padding: '1.5rem', maxWidth: '1000px', margin: '0 auto' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem', flexWrap: 'wrap', gap: '1rem' }}>
        <div>
          <h1 style={{ fontSize: '1.75rem', fontWeight: 700, color: '#1e293b' }}>Faturas Semanais</h1>
          <p style={{ color: '#64748b', fontSize: '0.9375rem' }}>Faturas dos estabelecimentos por semana</p>
        </div>
        <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
          <button onClick={loadInvoices} style={{ display: 'flex', alignItems: 'center', gap: '0.375rem', padding: '0.5rem 1rem', borderRadius: '0.5rem', border: '1px solid #e2e8f0', background: 'white', cursor: 'pointer', fontSize: '0.8125rem', color: '#64748b' }}>
            <RefreshCw size={14} /> Atualizar
          </button>
          <button onClick={() => handleGenerate('previous_week')} disabled={generating} style={{ padding: '0.5rem 1rem', borderRadius: '0.5rem', border: 'none', background: '#2563eb', color: 'white', cursor: generating ? 'not-allowed' : 'pointer', fontSize: '0.8125rem', fontWeight: 600, opacity: generating ? 0.7 : 1 }}>
            {generating ? 'Gerando...' : 'Gerar Sem. Anterior'}
          </button>
          <button onClick={() => handleGenerate('current_week')} disabled={generating} style={{ padding: '0.5rem 1rem', borderRadius: '0.5rem', border: 'none', background: '#8b5cf6', color: 'white', cursor: generating ? 'not-allowed' : 'pointer', fontSize: '0.8125rem', fontWeight: 600, opacity: generating ? 0.7 : 1 }}>
            {generating ? 'Gerando...' : 'Gerar Sem. Atual'}
          </button>
          <button onClick={() => setShowGenerateModal(true)} style={{ padding: '0.5rem 1rem', borderRadius: '0.5rem', border: '2px dashed #2563eb', background: 'white', color: '#2563eb', cursor: 'pointer', fontSize: '0.8125rem', fontWeight: 600 }}>
            Gerar p/ Cliente
          </button>
        </div>
      </div>

      {showGenerateModal && (
        <>
          <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', zIndex: 99999 }} onClick={() => setShowGenerateModal(false)} />
          <div style={{ position: 'fixed', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', background: 'white', borderRadius: '0.75rem', width: '90%', maxWidth: '450px', zIndex: 100000, boxShadow: '0 20px 60px rgba(0,0,0,0.3)' }}>
            <div style={{ padding: '1.25rem 1.5rem', borderBottom: '1px solid #f1f5f9' }}>
              <h2 style={{ fontSize: '1.125rem', fontWeight: 700, color: '#1e293b' }}>Gerar Fatura para Cliente Específico</h2>
            </div>
            <div style={{ padding: '1.5rem' }}>
              <div style={{ marginBottom: '1rem' }}>
                <label style={{ display: 'block', fontSize: '0.8125rem', fontWeight: 500, color: '#374151', marginBottom: '0.375rem' }}>Estabelecimento</label>
                <select value={selectedRestaurant} onChange={e => setSelectedRestaurant(e.target.value)} style={{ width: '100%', padding: '0.625rem 0.75rem', border: '1.5px solid #e2e8f0', borderRadius: '0.5rem', fontSize: '0.875rem', outline: 'none' }}>
                  <option value="">Selecione...</option>
                  {restaurants.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
                </select>
              </div>
              <div style={{ display: 'flex', gap: '0.75rem', justifyContent: 'flex-end' }}>
                <button onClick={() => setShowGenerateModal(false)} style={{ padding: '0.625rem 1.25rem', borderRadius: '0.5rem', border: '1.5px solid #e2e8f0', background: 'white', fontSize: '0.875rem', cursor: 'pointer' }}>Cancelar</button>
                <button onClick={() => handleGenerate('previous_week', selectedRestaurant)} disabled={!selectedRestaurant || generating} style={{ padding: '0.625rem 1.25rem', borderRadius: '0.5rem', border: 'none', background: '#2563eb', color: 'white', fontSize: '0.875rem', fontWeight: 600, cursor: !selectedRestaurant ? 'not-allowed' : 'pointer', opacity: !selectedRestaurant ? 0.5 : 1 }}>
                  Sem. Anterior
                </button>
                <button onClick={() => handleGenerate('current_week', selectedRestaurant)} disabled={!selectedRestaurant || generating} style={{ padding: '0.625rem 1.25rem', borderRadius: '0.5rem', border: 'none', background: '#8b5cf6', color: 'white', fontSize: '0.875rem', fontWeight: 600, cursor: !selectedRestaurant ? 'not-allowed' : 'pointer', opacity: !selectedRestaurant ? 0.5 : 1 }}>
                  Sem. Atual
                </button>
              </div>
            </div>
          </div>
        </>
      )}

      {error && <div style={{ background: '#fef2f2', border: '1px solid #fecaca', color: '#dc2626', padding: '0.75rem', borderRadius: '0.5rem', marginBottom: '1rem', fontSize: '0.875rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}><AlertCircle size={16} /> {error}</div>}
      {success && <div style={{ background: '#dcfce7', border: '1px solid #86efac', color: '#166534', padding: '0.75rem', borderRadius: '0.5rem', marginBottom: '1rem', fontSize: '0.875rem' }}>{success}</div>}

      {/* Filtro de status */}
      <div style={{ display: 'flex', gap: '0.5rem', marginBottom: '1.5rem' }}>
        {['all', 'pending', 'paid'].map(f => (
          <button key={f} onClick={() => setFilter(f)} style={{ padding: '0.5rem 1rem', borderRadius: '0.5rem', border: filter === f ? '2px solid #2563eb' : '1px solid #e2e8f0', background: filter === f ? '#eff6ff' : 'white', color: filter === f ? '#2563eb' : '#64748b', cursor: 'pointer', fontSize: '0.8125rem', fontWeight: filter === f ? 600 : 400 }}>
            {f === 'all' ? `Todas (${invoices.length})` : f === 'pending' ? 'Pendentes' : 'Pagas'}
          </button>
        ))}
      </div>

      {invoices.length === 0 ? (
        <div style={{ background: 'white', borderRadius: '0.75rem', padding: '3rem', textAlign: 'center', boxShadow: '0 1px 3px rgba(0,0,0,0.05)' }}>
          <FileText size={48} style={{ color: '#64748b', marginBottom: '1rem' }} />
          <p style={{ color: '#64748b', fontSize: '1rem' }}>Nenhuma fatura encontrada</p>
          <p style={{ color: '#64748b', fontSize: '0.875rem', marginTop: '0.5rem' }}>Clique em "Gerar Sem. Anterior" ou "Gerar Sem. Atual" para criar faturas</p>
        </div>
      ) : (
        <div style={{ display: 'grid', gap: '0.75rem' }}>
          {invoices.map(inv => (
            <div key={inv.id} style={{ background: 'white', borderRadius: '0.75rem', padding: '1.25rem', boxShadow: '0 1px 3px rgba(0,0,0,0.05)', borderLeft: `4px solid ${inv.status === 'PAID' ? '#22c55e' : '#f59e0b'}` }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', flexWrap: 'wrap', gap: '1rem' }}>
                <div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '0.5rem' }}>
                    <span style={{ fontWeight: 600, color: '#1e293b', fontSize: '1rem' }}>{inv.restaurant_name}</span>
                    {statusBadge(inv.status)}
                  </div>
                  <p style={{ color: '#64748b', fontSize: '0.8125rem', marginBottom: '0.25rem' }}>
                    Semana: {new Date(inv.week_start + 'Z').toLocaleDateString('pt-BR')} a {new Date(inv.week_end + 'Z').toLocaleDateString('pt-BR')}
                  </p>
                  <p style={{ color: '#64748b', fontSize: '0.8125rem' }}>
                    {inv.deliveries_count} entregas
                  </p>
                </div>
                <div style={{ textAlign: 'right' }}>
                  <p style={{ fontWeight: 700, color: '#1e293b', fontSize: '1.25rem', marginBottom: '0.25rem' }}>
                    R$ {(inv.total_amount || 0).toFixed(2).replace('.', ',')}
                  </p>
                  <p style={{ color: '#16a34a', fontSize: '0.8125rem', marginBottom: '0.75rem' }}>
                    Entregadores: R$ {(inv.driver_earnings || 0).toFixed(2).replace('.', ',')}
                  </p>
                  {inv.status === 'PENDING' && (
                    <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap', justifyContent: 'flex-end' }}>
                      {paymentLinks[inv.id] ? (
                        <>
                          <a href={paymentLinks[inv.id]} target="_blank" rel="noopener noreferrer"
                            style={{ display: 'inline-flex', alignItems: 'center', gap: '0.375rem', padding: '0.5rem 1rem', borderRadius: '0.5rem', border: 'none', background: '#8b5cf6', color: 'white', fontSize: '0.8125rem', fontWeight: 600, textDecoration: 'none' }}>
                            <ExternalLink size={14} /> Abrir Link
                          </a>
                          <button onClick={() => handleSendLink(inv.id)}
                            style={{ display: 'flex', alignItems: 'center', gap: '0.375rem', padding: '0.5rem 1rem', borderRadius: '0.5rem', border: 'none', background: '#0ea5e9', color: 'white', cursor: 'pointer', fontSize: '0.8125rem', fontWeight: 600 }}>
                            <Bell size={14} /> Enviar Link
                          </button>
                        </>
                      ) : (
                        <button onClick={() => handleCharge(inv.id)} disabled={chargingId === inv.id}
                          style={{ display: 'flex', alignItems: 'center', gap: '0.375rem', padding: '0.5rem 1rem', borderRadius: '0.5rem', border: 'none', background: '#8b5cf6', color: 'white', cursor: chargingId === inv.id ? 'not-allowed' : 'pointer', fontSize: '0.8125rem', fontWeight: 600, opacity: chargingId === inv.id ? 0.7 : 1 }}>
                          <QrCode size={14} /> {chargingId === inv.id ? 'Gerando...' : 'Gerar Cobrança PIX'}
                        </button>
                      )}
                      <button onClick={() => handlePay(inv.id)} style={{ display: 'flex', alignItems: 'center', gap: '0.375rem', padding: '0.5rem 1rem', borderRadius: '0.5rem', border: 'none', background: '#22c55e', color: 'white', cursor: 'pointer', fontSize: '0.8125rem', fontWeight: 600 }}>
                        <CheckCircle size={14} /> Marcar como Paga
                      </button>
                    </div>
                  )}
                  {inv.status === 'PAID' && inv.paid_at && (
                    <p style={{ color: '#16a34a', fontSize: '0.75rem' }}>
                      Paga em: {new Date(inv.paid_at + 'Z').toLocaleDateString('pt-BR')}
                    </p>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
    </div>
  );
};

export default AdminInvoicesPage;

import React, { useState, useEffect } from 'react';
import {
  Package, AlertCircle, Store, User, MapPin, Clock,
  ChevronLeft, ChevronRight, Bike, Edit, Trash2, Eye
} from 'lucide-react';
import { adminService, utils } from '@/lib/api';
import { useNavigate } from 'react-router-dom';
import { useSquare } from '@/contexts/SquareContext';
import DateRangeFilter from '@/components/DateRangeFilter';
import { showToast } from '@/components/Toast';
import { ORDER_STATUS, getStatusLabel } from '@/constants/status';
import { showConfirm } from '@/components/ConfirmDialog';
import StatusFilterBar from './admin-orders/StatusFilterBar';
import EditOrderModal from './admin-orders/EditOrderModal';

const STATUS_FILTERS = [
  { key: '', label: 'Todos', color: '#64748b' },
  { key: 'SCHEDULED', label: 'Agendado', color: '#6366f1' },
  { key: 'PENDING', label: 'Pendente', color: '#f59e0b' },
  { key: 'ACCEPTED', label: 'Aceito', color: '#2563eb' },
  { key: 'PICKED_UP', label: 'Coletado', color: '#3b82f6' },
  { key: 'DELIVERED', label: 'Entregue', color: '#22c55e' },
  { key: 'CANCELLED', label: 'Cancelado', color: '#ef4444' },
];

const AdminOrdersPage = () => {
  const navigate = useNavigate();
  const { squareId } = useSquare();
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [editingOrder, setEditingOrder] = useState(null);
  const [editData, setEditData] = useState({});
  const [dateRange, setDateRange] = useState(null);

  useEffect(() => { loadOrders(); }, [page, statusFilter, dateRange, squareId]);

  const loadOrders = async () => {
    try {
      setLoading(true);
      const response = await adminService.getAllOrders(page, 20, statusFilter, dateRange?.startDate, dateRange?.endDate, squareId);
      setOrders(response.orders || []);
      setTotalPages(response.pages || 1);
    } catch (err) {
      setError('Erro ao carregar pedidos');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteOrder = async (orderId) => {
    showConfirm('Excluir este pedido? Esta ação não pode ser desfeita.', async () => {
      try {
        await adminService.adminDeleteOrder(orderId);
        loadOrders();
      } catch (err) {
        showToast(err.response?.data?.error || 'Erro ao excluir', 'error');
      }
    });
  };

  const openEditOrder = (order) => {
    setEditingOrder(order);
    setEditData({
      status: order.status,
      delivery_fee: order.delivery_fee,
      total_amount: order.total_amount,
      payment_method: order.payment_method,
      customer_name: order.customer?.name || '',
      customer_phone: order.customer?.phone || '',
      delivery_address: order.delivery_address?.street || '',
      delivery_neighborhood: order.delivery_address?.neighborhood || '',
      delivery_city: order.delivery_address?.city || '',
      delivery_state: order.delivery_address?.state || '',
      delivery_zip_code: order.delivery_address?.zip_code || '',
      delivery_complement: order.delivery_address?.complement || '',
      special_instructions: order.special_instructions || '',
      distribution_method: order.distribution_method || 'nearest'
    });
  };

  const handleEditOrder = async (e) => {
    e.preventDefault();
    try {
      await adminService.adminUpdateOrder(editingOrder.id, editData);
      setEditingOrder(null);
      loadOrders();
    } catch (err) {
      showToast(err.response?.data?.error || 'Erro ao atualizar', 'error');
    }
  };

  if (loading && orders.length === 0) {
    return (
      <div style={{ minHeight: '60vh', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ width: '3rem', height: '3rem', border: '3px solid #e2e8f0', borderTopColor: '#2563eb', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
      </div>
    );
  }

  return (
    <div style={{ padding: '1.5rem', maxWidth: '1100px', margin: '0 auto' }}>
      {/* Header */}
      <div style={{ marginBottom: '1.5rem' }}>
        <h1 style={{ fontSize: '1.75rem', fontWeight: 700, color: '#1e293b', marginBottom: '0.25rem' }}>Pedidos</h1>
        <p style={{ color: '#64748b', fontSize: '0.9375rem' }}>Gerencie todos os pedidos do sistema</p>
      </div>

      {/* Erro */}
      {error && (
        <div style={{ background: '#fef2f2', border: '1px solid #fecaca', color: '#dc2626', padding: '0.75rem 1rem', borderRadius: '0.5rem', marginBottom: '1.5rem', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.875rem' }}>
          <AlertCircle size={16} /> {error}
        </div>
      )}

      {/* Filtro de Datas */}
      <DateRangeFilter onChange={(range) => { setDateRange(range); setPage(1); }} />

      {/* Filtros */}
      <StatusFilterBar statusFilter={statusFilter} onFilterChange={(key) => { setStatusFilter(key); setPage(1); }} statusFilters={STATUS_FILTERS} />

      {/* Lista */}
      {orders.length === 0 ? (
        <div style={{ background: 'white', borderRadius: '0.75rem', padding: '4rem 2rem', textAlign: 'center', boxShadow: '0 1px 3px rgba(0,0,0,0.05)' }}>
          <Package size={48} style={{ color: '#cbd5e1', margin: '0 auto 1rem' }} />
          <p style={{ fontWeight: 600, color: '#1e293b', marginBottom: '0.25rem' }}>Nenhum pedido encontrado</p>
          <p style={{ fontSize: '0.875rem', color: '#64748b' }}>Tente ajustar os filtros</p>
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
          {orders.map(order => <OrderCard key={order.id} order={order} onEdit={openEditOrder} onDelete={handleDeleteOrder} onViewDetail={(id) => navigate(`/admin/orders/${id}`)} />)}
        </div>
      )}

      {/* Paginação */}
      {totalPages > 1 && (
        <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '1rem', marginTop: '1.5rem' }}>
          <button onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1}
            style={{ display: 'flex', alignItems: 'center', gap: '0.375rem', padding: '0.5rem 1rem', borderRadius: '0.5rem', border: '1px solid #e2e8f0', background: page === 1 ? '#f8fafc' : 'white', color: page === 1 ? '#cbd5e1' : '#475569', fontSize: '0.875rem', cursor: page === 1 ? 'not-allowed' : 'pointer' }}>
            <ChevronLeft size={16} /> Anterior
          </button>
          <span style={{ fontSize: '0.875rem', color: '#64748b', fontWeight: 500 }}>{page} / {totalPages}</span>
          <button onClick={() => setPage(p => Math.min(totalPages, p + 1))} disabled={page === totalPages}
            style={{ display: 'flex', alignItems: 'center', gap: '0.375rem', padding: '0.5rem 1rem', borderRadius: '0.5rem', border: '1px solid #e2e8f0', background: page === totalPages ? '#f8fafc' : 'white', color: page === totalPages ? '#cbd5e1' : '#475569', fontSize: '0.875rem', cursor: page === totalPages ? 'not-allowed' : 'pointer' }}>
            Próxima <ChevronRight size={16} />
          </button>
        </div>
      )}

      {/* Modal Editar Pedido */}
      {editingOrder && (
        <EditOrderModal
          editingOrder={editingOrder}
          editData={editData}
          setEditData={setEditData}
          onClose={() => setEditingOrder(null)}
          onSubmit={handleEditOrder}
          statusFilters={STATUS_FILTERS}
        />
      )}

      <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
    </div>
  );
};

const OrderCard = ({ order, onEdit, onDelete, onViewDetail }) => {
  const statusColor = ORDER_STATUS[order.status] || { bg: '#f1f5f9', color: '#64748b' };

  return (
    <div style={{
      background: 'white', borderRadius: '0.75rem',
      boxShadow: '0 1px 3px rgba(0,0,0,0.05)',
      transition: 'all 0.15s', overflow: 'hidden'
    }}
    onMouseEnter={e => e.currentTarget.style.boxShadow = '0 4px 12px rgba(0,0,0,0.08)'}
    onMouseLeave={e => e.currentTarget.style.boxShadow = '0 1px 3px rgba(0,0,0,0.05)'}>
      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '0.875rem 1.25rem', borderBottom: '1px solid #f1f5f9', background: '#fafbfc' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.625rem' }}>
          <span style={{ fontFamily: 'monospace', fontSize: '0.8125rem', color: '#64748b', fontWeight: 500 }}>#{order.order_number}</span>
          <span style={{ padding: '0.25rem 0.75rem', borderRadius: '9999px', fontSize: '0.6875rem', fontWeight: 600, background: statusColor.bg, color: statusColor.color }}>
            {utils.getStatusText(order.status)}
          </span>
          <span style={{ padding: '0.25rem 0.625rem', borderRadius: '9999px', fontSize: '0.6875rem', fontWeight: 500, background: '#f1f5f9', color: '#64748b' }}>
            {utils.getStatusText(order.payment_method)}
          </span>
          {order.own_driver_route && (
            <span style={{ padding: '0.25rem 0.625rem', borderRadius: '9999px', fontSize: '0.6875rem', fontWeight: 600, background: '#dbeafe', color: '#1d4ed8' }}>
              {order.own_driver_route.name}
            </span>
          )}
        </div>
        <div style={{ textAlign: 'right' }}>
          <p style={{ fontWeight: 700, color: '#1e293b' }}>{utils.formatCurrency(order.total_amount)}</p>
          <p style={{ fontSize: '0.6875rem', color: '#64748b' }}>Taxa: {utils.formatCurrency(order.delivery_fee)}</p>
        </div>
      </div>

      {/* Conteúdo */}
      <div style={{ padding: '1rem 1.25rem' }}>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '0.875rem' }}>
          {/* Restaurante */}
          <div style={{ display: 'flex', gap: '0.625rem' }}>
            <div style={{ width: '2rem', height: '2rem', borderRadius: '0.375rem', background: '#fef3c7', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
              <Store size={14} style={{ color: '#d97706' }} />
            </div>
            <div style={{ minWidth: 0 }}>
              <p style={{ fontSize: '0.625rem', color: '#64748b', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Restaurante</p>
              <p style={{ fontWeight: 500, color: '#1e293b', fontSize: '0.8125rem', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{order.restaurant?.name}</p>
            </div>
          </div>

          {/* Cliente */}
          <div style={{ display: 'flex', gap: '0.625rem' }}>
            <div style={{ width: '2rem', height: '2rem', borderRadius: '0.375rem', background: '#dbeafe', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
              <User size={14} style={{ color: '#2563eb' }} />
            </div>
            <div style={{ minWidth: 0 }}>
              <p style={{ fontSize: '0.625rem', color: '#64748b', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Cliente</p>
              <p style={{ fontWeight: 500, color: '#1e293b', fontSize: '0.8125rem' }}>{order.customer?.name}</p>
            </div>
          </div>

          {/* Endereço */}
          <div style={{ display: 'flex', gap: '0.625rem' }}>
            <div style={{ width: '2rem', height: '2rem', borderRadius: '0.375rem', background: '#dcfce7', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
              <MapPin size={14} style={{ color: '#16a34a' }} />
            </div>
            <div style={{ minWidth: 0 }}>
              <p style={{ fontSize: '0.625rem', color: '#64748b', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Entrega</p>
              <p style={{ fontWeight: 500, color: '#1e293b', fontSize: '0.8125rem', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{order.delivery_address?.street}</p>
            </div>
          </div>
        </div>

        {/* Footer */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '0.875rem', paddingTop: '0.75rem', borderTop: '1px solid #f8fafc' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.375rem' }}>
            {order.driver && (
              <span style={{ display: 'flex', alignItems: 'center', gap: '0.25rem', fontSize: '0.75rem', color: '#2563eb', background: '#eff6ff', padding: '0.25rem 0.625rem', borderRadius: '9999px' }}>
                <Bike size={11} /> {order.driver.name}
              </span>
            )}
          </div>
          <span style={{ display: 'flex', alignItems: 'center', gap: '0.25rem', fontSize: '0.6875rem', color: '#64748b' }}>
            <Clock size={11} /> {utils.formatDateTime(order.created_at)}
          </span>
          <div style={{ display: 'flex', gap: '0.25rem' }}>
            <button onClick={(e) => { e.stopPropagation(); onViewDetail(order.id); }} style={{ padding: '0.25rem', borderRadius: '0.25rem', border: 'none', background: 'transparent', cursor: 'pointer', color: '#6366f1' }} title="Ver Detalhes">
              <Eye size={14} />
            </button>
            <button onClick={(e) => { e.stopPropagation(); onEdit(order); }} style={{ padding: '0.25rem', borderRadius: '0.25rem', border: 'none', background: 'transparent', cursor: 'pointer', color: '#2563eb' }} title="Editar">
              <Edit size={14} />
            </button>
            <button onClick={(e) => { e.stopPropagation(); onDelete(order.id); }} style={{ padding: '0.25rem', borderRadius: '0.25rem', border: 'none', background: 'transparent', cursor: 'pointer', color: '#dc2626' }} title="Excluir">
              <Trash2 size={14} />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminOrdersPage;

import React, { useState, useEffect } from 'react';
import { DollarSign, Plus, Edit, Trash2, X, Save, RefreshCw, AlertCircle, CheckCircle } from 'lucide-react';
import { adminService } from '@/lib/api';
import { showToast } from '@/components/Toast';

const AdminPricingPage = () => {
  const [tables, setTables] = useState([]);
  const [squares, setSquares] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [form, setForm] = useState({
    name: '', description: '', square_id: '', price_per_km: '2.95',
    min_distance_km: '4', min_delivery_fee: '', max_delivery_fee: '50',
    driver_percentage: '65', gamification_percentage: '5', is_active: true
  });

  useEffect(() => { loadData(); }, []);

  const loadData = async () => {
    try {
      setLoading(true);
      const [tablesRes, squaresRes] = await Promise.all([
        adminService.getPricingTables(),
        adminService.getSquares()
      ]);
      setTables(tablesRes.pricing_tables || []);
      setSquares(squaresRes.squares || []);
    } catch (err) {
      setError('Erro ao carregar dados');
    } finally {
      setLoading(false);
    }
  };

  const resetForm = () => {
    setForm({ name: '', description: '', square_id: '', price_per_km: '2.95', min_distance_km: '4', min_delivery_fee: '', max_delivery_fee: '50', driver_percentage: '65', gamification_percentage: '5', is_active: true });
    setEditingId(null);
    setShowForm(false);
    setError('');
  };

  const handleEdit = (table) => {
    setForm({
      name: table.name || '', description: table.description || '',
      square_id: String(table.square_id || ''),
      price_per_km: String(table.price_per_km || '2.95'),
      min_distance_km: String(table.min_distance_km || '4'),
      min_delivery_fee: String(table.min_delivery_fee || ''),
      max_delivery_fee: String(table.max_delivery_fee || '50'),
      driver_percentage: String(table.driver_percentage || '65'),
      gamification_percentage: String(table.gamification_percentage || '5'),
      is_active: table.is_active !== false
    });
    setEditingId(table.id);
    setShowForm(true);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.name || !form.square_id) { setError('Nome e praça são obrigatórios'); return; }
    try {
      const data = {
        name: form.name, description: form.description || null,
        square_id: parseInt(form.square_id),
        price_per_km: parseFloat(form.price_per_km) || 2.95,
        min_distance_km: parseFloat(form.min_distance_km) || 4,
        min_delivery_fee: form.min_delivery_fee ? parseFloat(form.min_delivery_fee) : null,
        max_delivery_fee: parseFloat(form.max_delivery_fee) || 50,
        driver_percentage: parseFloat(form.driver_percentage) || 65,
        gamification_percentage: parseFloat(form.gamification_percentage) || 5,
        is_active: form.is_active
      };
      if (editingId) {
        await adminService.updatePricingTable(editingId, data);
        setSuccess('Tabela atualizada!');
      } else {
        await adminService.createPricingTable(data);
        setSuccess('Tabela criada!');
      }
      resetForm();
      loadData();
      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      setError(err.response?.data?.error || 'Erro ao salvar');
    }
  };

  const handleDelete = async (id, name) => {
    if (!window.confirm(`Excluir tabela "${name}"?`)) return;
    try {
      await adminService.deletePricingTable(id);
      loadData();
    } catch (err) {
      showToast(err.response?.data?.error || 'Erro ao excluir', 'error');
    }
  };

  const getSquareName = (id) => {
    const sq = squares.find(s => s.id === id);
    return sq ? `${sq.name} (${sq.city})` : `Praça #${id}`;
  };

  if (loading) {
    return (
      <div style={{ minHeight: '60vh', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ width: '3rem', height: '3rem', border: '3px solid #e2e8f0', borderTopColor: '#2563eb', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
      </div>
    );
  }

  return (
    <div style={{ padding: '1.5rem', maxWidth: '1100px', margin: '0 auto' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem' }}>
        <div>
          <h1 style={{ fontSize: '1.75rem', fontWeight: 700, color: '#1e293b' }}>Tabelas de Preços</h1>
          <p style={{ color: '#64748b', fontSize: '0.9375rem' }}>Gerencie as tabelas de preços por praça</p>
        </div>
        <button onClick={() => { resetForm(); setShowForm(true); }}
          style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', padding: '0.625rem 1.25rem', borderRadius: '0.5rem', border: 'none', background: '#2563eb', color: 'white', fontSize: '0.875rem', fontWeight: 600, cursor: 'pointer' }}>
          <Plus size={16} /> Nova Tabela
        </button>
      </div>

      {error && <div style={{ background: '#fef2f2', border: '1px solid #fecaca', color: '#dc2626', padding: '0.75rem', borderRadius: '0.5rem', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.875rem' }}><AlertCircle size={16} /> {error}</div>}
      {success && <div style={{ background: '#dcfce7', border: '1px solid #86efac', color: '#166534', padding: '0.75rem', borderRadius: '0.5rem', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.875rem' }}><CheckCircle size={16} /> {success}</div>}

      {/* Lista de tabelas */}
      {tables.length === 0 ? (
        <div style={{ background: 'white', borderRadius: '0.75rem', padding: '3rem', textAlign: 'center', boxShadow: '0 1px 3px rgba(0,0,0,0.05)' }}>
          <DollarSign size={48} style={{ color: '#64748b', marginBottom: '1rem' }} />
          <p style={{ color: '#64748b', fontSize: '1rem', marginBottom: '0.5rem' }}>Nenhuma tabela de preços cadastrada</p>
          <p style={{ color: '#64748b', fontSize: '0.875rem' }}>Crie uma tabela para configurar preços por km</p>
        </div>
      ) : (
        <div style={{ display: 'grid', gap: '0.75rem' }}>
          {tables.map(table => (
            <div key={table.id} style={{ background: 'white', borderRadius: '0.75rem', padding: '1.25rem', boxShadow: '0 1px 3px rgba(0,0,0,0.05)', borderLeft: `4px solid ${table.is_active ? '#2563eb' : '#64748b'}` }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                <div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '0.25rem' }}>
                    <span style={{ fontWeight: 600, color: '#1e293b', fontSize: '1rem' }}>{table.name}</span>
                    {!table.is_active && <span style={{ padding: '0.125rem 0.375rem', background: '#f1f5f9', borderRadius: '9999px', fontSize: '0.625rem', color: '#64748b' }}>Inativa</span>}
                  </div>
                  <p style={{ color: '#64748b', fontSize: '0.75rem', marginBottom: '0.5rem' }}>
                    {getSquareName(table.square_id)} {table.description ? `• ${table.description}` : ''}
                  </p>
                  <div style={{ display: 'flex', gap: '1rem', flexWrap: 'wrap' }}>
                    <span style={{ fontSize: '0.75rem', color: '#475569' }}><strong>R$/km:</strong> R$ {parseFloat(table.price_per_km || 0).toFixed(2)}</span>
                    <span style={{ fontSize: '0.75rem', color: '#475569' }}><strong>Mín:</strong> {table.min_distance_km} km</span>
                    <span style={{ fontSize: '0.75rem', color: '#475569' }}><strong>Frete mín:</strong> R$ {parseFloat(table.min_delivery_fee || 0).toFixed(2)}</span>
                    <span style={{ fontSize: '0.75rem', color: '#475569' }}><strong>Frete máx:</strong> R$ {parseFloat(table.max_delivery_fee || 50).toFixed(2)}</span>
                    <span style={{ fontSize: '0.75rem', color: '#475569' }}><strong>Entregador:</strong> {table.driver_percentage}% · <strong>Gamificação:</strong> {table.gamification_percentage || 5}%</span>
                  </div>
                </div>
                <div style={{ display: 'flex', gap: '0.25rem' }}>
                  <button onClick={() => handleEdit(table)} style={{ padding: '0.375rem', borderRadius: '0.375rem', border: 'none', background: 'transparent', cursor: 'pointer', color: '#2563eb' }} title="Editar">
                    <Edit size={16} />
                  </button>
                  <button onClick={() => handleDelete(table.id, table.name)} style={{ padding: '0.375rem', borderRadius: '0.375rem', border: 'none', background: 'transparent', cursor: 'pointer', color: '#dc2626' }} title="Excluir">
                    <Trash2 size={16} />
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Modal de formulário */}
      {showForm && (
        <>
          <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', zIndex: 99999 }} onClick={resetForm} />
          <div style={{ position: 'fixed', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', background: 'white', borderRadius: '0.75rem', width: '90%', maxWidth: '500px', maxHeight: '90vh', overflow: 'auto', zIndex: 100000, boxShadow: '0 20px 60px rgba(0,0,0,0.3)' }}>
            <div style={{ padding: '1.25rem 1.5rem', borderBottom: '1px solid #f1f5f9', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <h2 style={{ fontSize: '1.125rem', fontWeight: 700, color: '#1e293b' }}>{editingId ? 'Editar Tabela' : 'Nova Tabela de Preços'}</h2>
              <button onClick={resetForm} style={{ border: 'none', background: 'none', cursor: 'pointer', color: '#64748b' }}><X size={20} /></button>
            </div>
            <form onSubmit={handleSubmit} style={{ padding: '1.5rem' }}>
              <div style={{ marginBottom: '1rem' }}>
                <label style={{ display: 'block', fontSize: '0.8125rem', fontWeight: 500, color: '#374151', marginBottom: '0.375rem' }}>Nome da Tabela *</label>
                <input value={form.name} onChange={e => setForm(p => ({ ...p, name: e.target.value }))} placeholder="Ex: Tabela A, Tabela VIP" required style={{ width: '100%', padding: '0.625rem 0.75rem', border: '1.5px solid #e2e8f0', borderRadius: '0.5rem', fontSize: '0.875rem', outline: 'none', boxSizing: 'border-box' }} />
              </div>

              <div style={{ marginBottom: '1rem' }}>
                <label style={{ display: 'block', fontSize: '0.8125rem', fontWeight: 500, color: '374151', marginBottom: '0.375rem' }}>Praça *</label>
                <select value={form.square_id} onChange={e => setForm(p => ({ ...p, square_id: e.target.value }))} required style={{ width: '100%', padding: '0.625rem 0.75rem', border: '1.5px solid #e2e8f0', borderRadius: '0.5rem', fontSize: '0.875rem', outline: 'none' }}>
                  <option value="">Selecione uma praça</option>
                  {squares.map(sq => <option key={sq.id} value={sq.id}>{sq.name} ({sq.city}/{sq.state})</option>)}
                </select>
              </div>

              <div style={{ marginBottom: '1rem' }}>
                <label style={{ display: 'block', fontSize: '0.8125rem', fontWeight: 500, color: '#374151', marginBottom: '0.375rem' }}>Descrição</label>
                <input value={form.description} onChange={e => setForm(p => ({ ...p, description: e.target.value }))} placeholder="Descrição opcional" style={{ width: '100%', padding: '0.625rem 0.75rem', border: '1.5px solid #e2e8f0', borderRadius: '0.5rem', fontSize: '0.875rem', outline: 'none', boxSizing: 'border-box' }} />
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem', marginBottom: '1rem' }}>
                <div>
                  <label style={{ display: 'block', fontSize: '0.8125rem', fontWeight: 500, color: '#374151', marginBottom: '0.375rem' }}>R$ por km *</label>
                  <input type="number" step="0.01" value={form.price_per_km} onChange={e => setForm(p => ({ ...p, price_per_km: e.target.value }))} required style={{ width: '100%', padding: '0.625rem 0.75rem', border: '1.5px solid #e2e8f0', borderRadius: '0.5rem', fontSize: '0.875rem', outline: 'none', boxSizing: 'border-box' }} />
                </div>
                <div>
                  <label style={{ display: 'block', fontSize: '0.8125rem', fontWeight: 500, color: '#374151', marginBottom: '0.375rem' }}>Distância mín. (km)</label>
                  <input type="number" step="0.5" value={form.min_distance_km} onChange={e => setForm(p => ({ ...p, min_distance_km: e.target.value }))} style={{ width: '100%', padding: '0.625rem 0.75rem', border: '1.5px solid #e2e8f0', borderRadius: '0.5rem', fontSize: '0.875rem', outline: 'none', boxSizing: 'border-box' }} />
                </div>
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem', marginBottom: '1rem' }}>
                <div>
