import React, { useState, useEffect } from 'react';
import {
  Users, Search, Plus, Edit, Trash2, AlertCircle, X,
  Bike, Store, Shield, Mail, Phone, CheckCircle
} from 'lucide-react';
import api, { adminService, utils } from '@/lib/api';
import { showToast } from '@/components/Toast';
import TrashModal from '@/components/TrashModal';

const AdminUsersPage = () => {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [search, setSearch] = useState('');
  const [typeFilter, setTypeFilter] = useState('');
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [total, setTotal] = useState(0);
  const [tenants, setTenants] = useState([]);
  const [squares, setSquares] = useState([]);

  // Verificar se é super admin
  const user = JSON.parse(localStorage.getItem('user') || '{}');
  const isSuperAdmin = user?.user_type === 'ADMIN' && user?.is_super_admin;

  // Modais
  const [showForm, setShowForm] = useState(false);
  const [showEdit, setShowEdit] = useState(null);
  const [showDetails, setShowDetails] = useState(null);
  const [showTrash, setShowTrash] = useState(false);
  const [formData, setFormData] = useState({ email: '', password: 'admin123', first_name: '', last_name: '', tenant_id: '' });
  const [editData, setEditData] = useState({});
  const [formError, setFormError] = useState('');
  const [formLoading, setFormLoading] = useState(false);

  useEffect(() => { loadUsers(); loadTenants(); loadSquares(); }, [page, typeFilter]);

  const loadTenants = async () => {
    try {
      const res = await api.get('/api/platform/tenants');
      setTenants(res.data.tenants || []);
    } catch (err) {
      console.error(err);
    }
  };

  const loadSquares = async () => {
    try {
      const res = await api.get('/api/admin/squares');
      setSquares(res.data.squares || []);
    } catch (err) {
      console.error(err);
    }
  };

  const loadUsers = async () => {
    try {
      setLoading(true);
      const data = await adminService.getAllUsers(page, 20, typeFilter, search);
      setUsers(data.users);
      setTotalPages(data.pages);
      setTotal(data.total);
    } catch (err) {
      setError('Erro ao carregar usuários');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const openCreateAdmin = () => {
    setFormData({ email: '', password: 'admin123', first_name: '', last_name: '' });
    setFormError('');
    setShowForm(true);
  };

  const handleCreateAdmin = async (e) => {
    e.preventDefault();
    if (!formData.email || !formData.first_name) {
      setFormError('Email e nome são obrigatórios');
      return;
    }
    try {
      setFormLoading(true);
      const result = await adminService.createAdminUser(formData);
      setShowForm(false);
      loadUsers();
      showToast(`Admin criado!\nEmail: ${result.user.email}\nSenha: ${result.user.password}`, 'info');
    } catch (err) {
      setFormError(err.response?.data?.error || 'Erro ao criar admin');
    } finally {
      setFormLoading(false);
    }
  };

  const openEdit = (user) => {
    setEditData({
      first_name: user.first_name || '',
      last_name: user.last_name || '',
      phone: user.phone || '',
      email: user.email || '',
      status: user.status || 'ACTIVE',
      tenant_id: user.tenant_id || '',
      square_id: user.square_id || ''
    });
    setShowEdit(user);
  };

  const handleEdit = async (e) => {
    e.preventDefault();
    try {
      setFormLoading(true);
      await adminService.updateUser(showEdit.id, editData);
      setShowEdit(null);
      loadUsers();
    } catch (err) {
      showToast(err.response?.data?.error || 'Erro ao atualizar', 'error');
    } finally {
      setFormLoading(false);
    }
  };

  const handleDelete = async (userId, userName) => {
    if (!window.confirm(`Excluir ${userName}? Esta ação não pode ser desfeita.`)) return;
    try {
      await adminService.deleteUser(userId);
      loadUsers();
    } catch (err) {
      showToast(err.response?.data?.error || 'Erro ao excluir', 'error');
    }
  };

  const getTypeIcon = (type) => {
    switch (type) {
      case 'ADMIN': return <Shield size={14} style={{ color: '#8b5cf6' }} />;
      case 'DRIVER': return <Bike size={14} style={{ color: '#2563eb' }} />;
      case 'CLIENT': return <Store size={14} style={{ color: '#0d9488' }} />;
      default: return <Users size={14} style={{ color: '#64748b' }} />;
    }
  };

  const getTypeLabel = (type) => {
    switch (type) {
      case 'ADMIN': return 'Admin';
      case 'DRIVER': return 'Entregador';
      case 'CLIENT': return 'Estabelecimento';
      default: return type;
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'ACTIVE': return { bg: '#dcfce7', color: '#16a34a' };
      case 'INACTIVE': return { bg: '#fef3c7', color: '#d97706' };
      case 'SUSPENDED': return { bg: '#fee2e2', color: '#dc2626' };
      default: return { bg: '#f1f5f9', color: '#64748b' };
    }
  };

  if (loading) {
    return (
      <div style={{ minHeight: '60vh', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ width: '3rem', height: '3rem', border: '3px solid #e2e8f0', borderTopColor: '#2563eb', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
      </div>
    );
  }

  return (
    <div style={{ padding: '1.5rem', maxWidth: '1100px', margin: '0 auto' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '1.5rem', flexWrap: 'wrap', gap: '1rem' }}>
        <div>
          <h1 style={{ fontSize: '1.75rem', fontWeight: 700, color: '#1e293b', marginBottom: '0.25rem' }}>Usuários</h1>
          <p style={{ color: '#64748b', fontSize: '0.9375rem' }}>{total} usuário(s) cadastrado(s)</p>
        </div>
        <div style={{ display: 'flex', gap: '0.75rem' }}>
          <button onClick={() => setShowTrash(true)} style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', padding: '0.625rem 1.25rem', borderRadius: '0.5rem', border: '1px solid #e2e8f0', background: 'white', color: '#64748b', fontSize: '0.875rem', cursor: 'pointer' }}>
            <Trash2 size={18} /> Lixeira
          </button>
          <button onClick={openCreateAdmin} style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', padding: '0.625rem 1.25rem', borderRadius: '0.5rem', border: 'none', background: '#8b5cf6', color: 'white', fontSize: '0.875rem', fontWeight: 600, cursor: 'pointer' }}>
            <Plus size={18} /> NOVO ADMIN
          </button>
        </div>
      </div>

      {error && (
        <div style={{ background: '#fef2f2', border: '1px solid #fecaca', color: '#dc2626', padding: '0.75rem 1rem', borderRadius: '0.5rem', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.875rem' }}>
          <AlertCircle size={16} /> {error}
        </div>
      )}

      {/* Filtros */}
      <div style={{ background: 'white', borderRadius: '0.75rem', boxShadow: '0 1px 3px rgba(0,0,0,0.05)', padding: '1rem 1.25rem', marginBottom: '1rem', display: 'flex', gap: '0.75rem', alignItems: 'center', flexWrap: 'wrap' }}>
        <div style={{ flex: 1, minWidth: '200px', position: 'relative' }}>
          <Search size={16} style={{ position: 'absolute', left: '0.75rem', top: '50%', transform: 'translateY(-50%)', color: '#64748b' }} />
          <input type="text" placeholder="Buscar por nome, e-mail ou telefone..." value={search} onChange={e => { setSearch(e.target.value); setPage(1); loadUsers(); }}
            style={{ width: '100%', padding: '0.625rem 0.75rem 0.625rem 2.5rem', border: '1.5px solid #e2e8f0', borderRadius: '0.5rem', fontSize: '0.875rem', outline: 'none', boxSizing: 'border-box' }} />
        </div>
        <div style={{ display: 'flex', gap: '0.375rem' }}>
          {[{ key: '', label: 'Todos' }, { key: 'ADMIN', label: 'Admins' }, { key: 'DRIVER', label: 'Entregadores' }, { key: 'CLIENT', label: 'Estabelecimentos' }].map(f => (
            <button key={f.key} onClick={() => { setTypeFilter(f.key); setPage(1); }} style={{ padding: '0.5rem 1rem', borderRadius: '9999px', border: 'none', fontSize: '0.8125rem', fontWeight: 500, cursor: 'pointer', background: typeFilter === f.key ? '#2563eb' : '#f1f5f9', color: typeFilter === f.key ? 'white' : '#64748b' }}>{f.label}</button>
          ))}
        </div>
      </div>

      {/* Lista */}
      {users.length === 0 ? (
        <div style={{ background: 'white', borderRadius: '0.75rem', padding: '3rem 2rem', textAlign: 'center', boxShadow: '0 1px 3px rgba(0,0,0,0.05)' }}>
          <Users size={48} style={{ color: '#cbd5e1', margin: '0 auto 1rem' }} />
          <p style={{ fontWeight: 600, color: '#1e293b' }}>Nenhum usuário encontrado</p>
        </div>
      ) : (
        <>
          <div style={{ background: 'white', borderRadius: '0.75rem', boxShadow: '0 1px 3px rgba(0,0,0,0.05)', overflow: 'hidden' }}>
            {users.map(user => {
              const statusStyle = getStatusColor(user.status);
              return (
                <div key={user.id} style={{ display: 'flex', alignItems: 'center', padding: '0.875rem 1.25rem', borderBottom: '1px solid #f8fafc', gap: '1rem', flexWrap: 'wrap' }}>
                  <div style={{ width: '2rem', height: '2rem', borderRadius: '50%', background: '#f8fafc', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                    {getTypeIcon(user.user_type)}
                  </div>
                  <div style={{ flex: 1, minWidth: '150px' }}>
                    <p style={{ fontWeight: 500, color: '#1e293b', fontSize: '0.875rem' }}>{user.first_name} {user.last_name}</p>
                    <p style={{ fontSize: '0.6875rem', color: '#64748b' }}>{user.email}</p>
                  </div>
                  <span style={{ padding: '0.125rem 0.5rem', borderRadius: '9999px', fontSize: '0.6875rem', fontWeight: 600, background: '#f1f5f9', color: '#64748b' }}>{getTypeLabel(user.user_type)}</span>
                  <span style={{ padding: '0.125rem 0.5rem', borderRadius: '9999px', fontSize: '0.6875rem', fontWeight: 600, background: statusStyle.bg, color: statusStyle.color }}>{user.status}</span>
                  <div style={{ display: 'flex', gap: '0.25rem' }}>
                    <button onClick={() => openEdit(user)} style={{ padding: '0.375rem', borderRadius: '0.375rem', border: 'none', background: 'transparent', cursor: 'pointer', color: '#64748b' }} title="Editar"><Edit size={16} /></button>
                    <button onClick={() => handleDelete(user.id, user.first_name + ' ' + user.last_name)} style={{ padding: '0.375rem', borderRadius: '0.375rem', border: 'none', background: 'transparent', cursor: 'pointer', color: '#dc2626' }} title="Excluir"><Trash2 size={16} /></button>
                  </div>
                </div>
              );
            })}
          </div>
          {totalPages > 1 && (
            <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '0.5rem', marginTop: '1rem' }}>
              <button onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1} style={pagBtn(page === 1)}>Anterior</button>
              <span style={{ fontSize: '0.875rem', color: '#64748b' }}>{page} / {totalPages}</span>
              <button onClick={() => setPage(p => Math.min(totalPages, p + 1))} disabled={page === totalPages} style={pagBtn(page === totalPages)}>Próxima</button>
            </div>
          )}
        </>
      )}

      {/* Modal Criar Admin */}
      {showForm && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 100, padding: '1rem' }}>
          <div style={{ background: 'white', borderRadius: '0.75rem', width: '100%', maxWidth: '450px', boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1)' }}>
            <div style={{ padding: '1.25rem 1.5rem', borderBottom: '1px solid #f1f5f9', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <h2 style={{ fontSize: '1.125rem', fontWeight: 700, color: '#1e293b' }}>Novo Admin</h2>
              <button onClick={() => setShowForm(false)} style={{ border: 'none', background: 'none', cursor: 'pointer', color: '#64748b' }}><X size={20} /></button>
            </div>
            <form onSubmit={handleCreateAdmin} style={{ padding: '1.5rem' }}>
              {formError && <div style={{ background: '#fef2f2', border: '1px solid #fecaca', color: '#dc2626', padding: '0.625rem', borderRadius: '0.5rem', marginBottom: '1rem', fontSize: '0.8125rem' }}><AlertCircle size={14} /> {formError}</div>}
              <FormField label="Email *"><input type="email" name="email" value={formData.email} onChange={e => setFormData(p => ({ ...p, email: e.target.value }))} style={inputStyle} placeholder="admin@muv.log.br" /></FormField>
              <FormField label="Nome *"><input type="text" name="first_name" value={formData.first_name} onChange={e => setFormData(p => ({ ...p, first_name: e.target.value }))} style={inputStyle} /></FormField>
              <FormField label="Sobrenome"><input type="text" name="last_name" value={formData.last_name} onChange={e => setFormData(p => ({ ...p, last_name: e.target.value }))} style={inputStyle} /></FormField>
              <FormField label="Senha"><input type="text" name="password" value={formData.password} onChange={e => setFormData(p => ({ ...p, password: e.target.value }))} style={inputStyle} /></FormField>
              <FormField label="Tenant">
                <select name="tenant_id" value={formData.tenant_id} onChange={e => setFormData(p => ({ ...p, tenant_id: e.target.value }))} style={inputStyle}>
                  <option value="">Nenhum (Super Admin)</option>
                  {tenants.map(t => (
                    <option key={t.id} value={t.id}>{t.name}</option>
                  ))}
                </select>
              </FormField>
              <div style={{ display: 'flex', gap: '0.75rem', justifyContent: 'flex-end', marginTop: '1rem' }}>
                <button type="button" onClick={() => setShowForm(false)} style={btnSecondary}>Cancelar</button>
                <button type="submit" disabled={formLoading} style={{ ...btnPrimary, opacity: formLoading ? 0.7 : 1 }}>{formLoading ? 'Criando...' : 'Criar Admin'}</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Modal Editar */}
      {showEdit && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 100, padding: '1rem' }}>
          <div style={{ background: 'white', borderRadius: '0.75rem', width: '100%', maxWidth: '450px', boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1)' }}>
            <div style={{ padding: '1.25rem 1.5rem', borderBottom: '1px solid #f1f5f9', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <h2 style={{ fontSize: '1.125rem', fontWeight: 700, color: '#1e293b' }}>Editar Usuário</h2>
              <button onClick={() => setShowEdit(null)} style={{ border: 'none', background: 'none', cursor: 'pointer', color: '#64748b' }}><X size={20} /></button>
            </div>
            <form onSubmit={handleEdit} style={{ padding: '1.5rem' }}>
              <FormField label="Nome"><input type="text" value={editData.first_name} onChange={e => setEditData(p => ({ ...p, first_name: e.target.value }))} style={inputStyle} /></FormField>
              <FormField label="Sobrenome"><input type="text" value={editData.last_name} onChange={e => setEditData(p => ({ ...p, last_name: e.target.value }))} style={inputStyle} /></FormField>
              <FormField label="Email"><input type="email" value={editData.email} onChange={e => setEditData(p => ({ ...p, email: e.target.value }))} style={inputStyle} /></FormField>
              <FormField label="Telefone"><input type="text" value={editData.phone} onChange={e => setEditData(p => ({ ...p, phone: e.target.value }))} style={inputStyle} /></FormField>
              <FormField label="Status">
                <select value={editData.status} onChange={e => setEditData(p => ({ ...p, status: e.target.value }))} style={inputStyle}>
                  <option value="ACTIVE">Ativo</option>
                  <option value="INACTIVE">Inativo</option>
                  <option value="SUSPENDED">Suspenso</option>
                </select>
              </FormField>

              {/* Tenant — visível apenas para super admin */}
              {isSuperAdmin && (
                <FormField label="Organização (Tenant)">
                  <select value={editData.tenant_id || ''} onChange={e => setEditData(p => ({ ...p, tenant_id: e.target.value }))} style={inputStyle}>
                    <option value="">Nenhuma</option>
                    {tenants.map(t => (
                      <option key={t.id} value={t.id}>{t.name}</option>
                    ))}
                  </select>
                </FormField>
              )}

              {/* Praça — visível para usuários do tipo CLIENT */}
              {showEdit?.user_type === 'CLIENT' && (
                <FormField label="Praça">
                  <select value={editData.square_id || ''} onChange={e => setEditData(p => ({ ...p, square_id: e.target.value }))} style={inputStyle}>
                    <option value="">Selecione uma praça</option>
                    {squares.map(sq => (
                      <option key={sq.id} value={sq.id}>{sq.name} - {sq.city}/{sq.state}</option>
                    ))}
                  </select>
                </FormField>
              )}

              <div style={{ display: 'flex', gap: '0.75rem', justifyContent: 'flex-end', marginTop: '1rem' }}>
                <button type="button" onClick={() => setShowEdit(null)} style={btnSecondary}>Cancelar</button>
                <button type="submit" disabled={formLoading} style={{ ...btnPrimary, opacity: formLoading ? 0.7 : 1 }}>{formLoading ? 'Salvando...' : 'Salvar'}</button>
              </div>
            </form>
          </div>
        </div>
      )}

      <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
      
      <TrashModal
        isOpen={showTrash}
        onClose={() => setShowTrash(false)}
        onRestore={loadUsers}
      />
    </div>
  );
};

const FormField = ({ label, children }) => (
  <div style={{ marginBottom: '1rem' }}>
    <label style={{ display: 'block', fontSize: '0.8125rem', fontWeight: 500, color: '#374151', marginBottom: '0.375rem' }}>{label}</label>
    {children}
  </div>
);

const inputStyle = { width: '100%', padding: '0.625rem 0.75rem', border: '1.5px solid #e2e8f0', borderRadius: '0.5rem', fontSize: '0.875rem', outline: 'none', boxSizing: 'border-box' };
const btnPrimary = { padding: '0.625rem 1.25rem', borderRadius: '0.5rem', border: 'none', background: '#2563eb', color: 'white', fontSize: '0.875rem', fontWeight: 600, cursor: 'pointer' };
const btnSecondary = { padding: '0.625rem 1.25rem', borderRadius: '0.5rem', border: '1.5px solid #e2e8f0', background: 'white', fontSize: '0.875rem', fontWeight: 500, cursor: 'pointer', color: '#475569' };
const pagBtn = (disabled) => ({ padding: '0.5rem 1rem', borderRadius: '0.375rem', border: '1px solid #e2e8f0', background: 'white', cursor: disabled ? 'not-allowed' : 'pointer', opacity: disabled ? 0.5 : 1, fontSize: '0.875rem' });

export default AdminUsersPage;

import React, { useState, useEffect } from 'react';
import { DollarSign, RefreshCw, AlertCircle, CheckCircle, XCircle, Clock } from 'lucide-react';
import api from '@/lib/api';

const AdminWithdrawalsPage = () => {
  const [withdrawals, setWithdrawals] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  useEffect(() => { loadWithdrawals(); }, []);

  const loadWithdrawals = async () => {
    try {
      setLoading(true);
      const response = await api.get('/api/admin/withdrawals');
      setWithdrawals(response.data.withdrawals || []);
    } catch (err) {
      setError('Erro ao carregar saques');
    } finally {
      setLoading(false);
    }
  };

  const handleProcess = async (id, action) => {
    try {
      await api.post(`/api/admin/withdrawals/${id}/process`, { action });
      setSuccess(action === 'approve' ? 'Saque aprovado!' : 'Saque rejeitado!');
      loadWithdrawals();
      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      setError(err.response?.data?.error || 'Erro ao processar');
    }
  };

  if (loading) {
    return (
      <div style={{ minHeight: '60vh', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ width: '3rem', height: '3rem', border: '3px solid #e2e8f0', borderTopColor: '#2563eb', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
      </div>
    );
  }

  return (
    <div style={{ padding: '1.5rem', maxWidth: '900px', margin: '0 auto' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem' }}>
        <div>
          <h1 style={{ fontSize: '1.75rem', fontWeight: 700, color: '#1e293b' }}>Saques Pendentes</h1>
          <p style={{ color: '#64748b', fontSize: '0.9375rem' }}>Processe as solicitações de saque dos entregadores</p>
        </div>
        <button onClick={loadWithdrawals} style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', padding: '0.5rem 1rem', borderRadius: '0.5rem', border: '1px solid #e2e8f0', background: 'white', cursor: 'pointer', fontSize: '0.875rem', color: '#64748b' }}>
          <RefreshCw size={16} /> Atualizar
        </button>
      </div>

      {error && <div style={{ background: '#fef2f2', border: '1px solid #fecaca', color: '#dc2626', padding: '0.75rem', borderRadius: '0.5rem', marginBottom: '1rem', fontSize: '0.875rem' }}>{error}</div>}
      {success && <div style={{ background: '#dcfce7', border: '1px solid #86efac', color: '#166534', padding: '0.75rem', borderRadius: '0.5rem', marginBottom: '1rem', fontSize: '0.875rem' }}>{success}</div>}

      {withdrawals.length === 0 ? (
        <div style={{ background: 'white', borderRadius: '0.75rem', padding: '3rem', textAlign: 'center', boxShadow: '0 1px 3px rgba(0,0,0,0.05)' }}>
          <DollarSign size={48} style={{ color: '#64748b', marginBottom: '1rem' }} />
          <p style={{ color: '#64748b', fontSize: '1rem' }}>Nenhuma solicitação de saque pendente</p>
        </div>
      ) : (
        <div style={{ display: 'grid', gap: '0.75rem' }}>
          {withdrawals.map(w => (
            <div key={w.id} style={{ background: 'white', borderRadius: '0.75rem', padding: '1.25rem', boxShadow: '0 1px 3px rgba(0,0,0,0.05)', borderLeft: '4px solid #f59e0b' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                <div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '0.5rem' }}>
                    <span style={{ fontWeight: 600, color: '#1e293b', fontSize: '1rem' }}>{w.driver_name}</span>
                    <span style={{ padding: '0.125rem 0.5rem', background: '#fef3c7', borderRadius: '9999px', fontSize: '0.625rem', color: '#d97706', fontWeight: 600 }}>Pendente</span>
                  </div>
                  <p style={{ color: '#64748b', fontSize: '0.75rem', marginBottom: '0.25rem' }}>{w.driver_email}</p>
                  {w.pix_key && (
                    <p style={{ color: '#64748b', fontSize: '0.75rem', marginBottom: '0.25rem' }}>
                      <strong>PIX:</strong> {w.pix_key}
                    </p>
                  )}
                  <p style={{ color: '#64748b', fontSize: '0.6875rem' }}>
                    <Clock size={12} style={{ verticalAlign: 'middle', marginRight: '0.25rem' }} />
                    {w.created_at ? new Date(w.created_at + 'Z').toLocaleString('pt-BR') : ''}
                  </p>
                </div>
                <div style={{ textAlign: 'right' }}>
                  <p style={{ fontWeight: 700, color: '#1e293b', fontSize: '1.25rem', marginBottom: '0.75rem' }}>
                    R$ {(w.amount || 0).toFixed(2).replace('.', ',')}
                  </p>
                  <div style={{ display: 'flex', gap: '0.5rem' }}>
                    <button
                      onClick={() => handleProcess(w.id, 'reject')}
                      style={{ padding: '0.5rem 1rem', borderRadius: '0.5rem', border: '1px solid #ef4444', background: 'white', color: '#ef4444', cursor: 'pointer', fontSize: '0.8125rem', fontWeight: 500 }}
                    >
                      <XCircle size={14} style={{ verticalAlign: 'middle', marginRight: '0.25rem' }} />
                      Rejeitar
                    </button>
                    <button
                      onClick={() => handleProcess(w.id, 'approve')}
                      style={{ padding: '0.5rem 1rem', borderRadius: '0.5rem', border: 'none', background: '#22c55e', color: 'white', cursor: 'pointer', fontSize: '0.8125rem', fontWeight: 600 }}
                    >
                      <CheckCircle size={14} style={{ verticalAlign: 'middle', marginRight: '0.25rem' }} />
                      Aprovar
                    </button>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
    </div>
  );
};

export default AdminWithdrawalsPage;

import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, RefreshCw, AlertCircle } from 'lucide-react';
import api, { adminService, orderService, utils } from '@/lib/api';
import { showToast } from '@/components/Toast';
import StatusActions from './order-detail/StatusActions';
import OrderTimeline from './order-detail/OrderTimeline';
import OrderInfoCards from './order-detail/OrderInfoCards';
import EditOrderModal from './order-detail/EditOrderModal';
import MapModal from './order-detail/MapModal';

const STATUS_CONFIG = {
  SCHEDULED: { color: '#6366f1', bg: '#e0e7ff', text: 'Agendado', icon: '⏰' },
  PENDING: { color: '#ef4444', bg: '#fee2e2', text: 'Tocando', icon: '🔔' },
  ACCEPTED: { color: '#2563eb', bg: '#dbeafe', text: 'Aceito', icon: '✅' },
  PREPARING: { color: '#8b5cf6', bg: '#f3e8ff', text: 'Preparando', icon: '👨‍🍳' },
  READY: { color: '#06b6d4', bg: '#cffafe', text: 'Pronto', icon: '📦' },
  PICKED_UP: { color: '#f59e0b', bg: '#fef3c7', text: 'Coletado', icon: '🏍️' },
  DELIVERED: { color: '#22c55e', bg: '#dcfce7', text: 'Entregue', icon: '✅' },
  CANCELLED: { color: '#ef4444', bg: '#fee2e2', text: 'Cancelado', icon: '❌' },
};

const OrderDetailPage = () => {
  const { orderId } = useParams();
  const navigate = useNavigate();
  const [order, setOrder] = useState(null);
  const [drivers, setDrivers] = useState({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showEdit, setShowEdit] = useState(false);
  const [editForm, setEditForm] = useState({});
  const [editLoading, setEditLoading] = useState(false);
  const [showMap, setShowMap] = useState(false);
  const mapRef = useRef(null);
  const mapInstanceRef = useRef(null);

  useEffect(() => {
    loadOrder();
    loadDrivers();
    const interval = setInterval(loadOrder, 10000);
    return () => clearInterval(interval);
  }, [orderId]);

  const loadOrder = async () => {
    try {
      const response = await orderService.getOrderDetails(orderId);
      setOrder(response.order || response);
      setError('');
    } catch (err) {
      setError('Erro ao carregar pedido');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const loadDrivers = async () => {
    try {
      const response = await adminService.getDrivers(1, 100);
      const driversMap = {};
      (response.drivers || []).forEach(d => {
        driversMap[d.id] = d.user ? `${d.user.first_name} ${d.user.last_name}` : `Entregador #${d.id}`;
      });
      setDrivers(driversMap);
    } catch (err) {
      console.error('Erro ao carregar entregadores:', err);
    }
  };

  const handleChangeStatus = async (newStatus) => {
    try {
      if (newStatus === 'CANCELLED') {
        const hasDriver = order.driver_id || order.establishment_driver_id;
        let refundDriver = false;
        let reason = '';

        if (hasDriver) {
          const confirmMsg = 'Deseja estornar o valor ao entregador?\n\n' +
            'Clique "OK" para estornar ou "Cancelar" para apenas cancelar o pedido.';
          refundDriver = window.confirm(confirmMsg);
        }

        reason = window.prompt('Motivo do cancelamento (opcional):') || '';

        await api.put(`/api/orders/${orderId}/cancel`, {
          refund_driver: refundDriver,
          reason: reason
        });
      } else {
        await orderService.updateOrderStatus(orderId, newStatus);
      }
      loadOrder();
    } catch (err) {
      showToast('Erro ao alterar status: ' + (err.response?.data?.error || err.message), 'error');
    }
  };

  const handleEdit = async () => {
    try {
      setEditLoading(true);
      await api.put(`/api/orders/${orderId}/edit`, editForm);
      setShowEdit(false);
      loadOrder();
      showToast('Pedido atualizado com sucesso!', 'success');
    } catch (err) {
      showToast('Erro ao editar pedido: ' + (err.response?.data?.error || err.message), 'error');
    } finally {
      setEditLoading(false);
    }
  };

  const openEditModal = () => {
    if (!order) return;
    setEditForm({
      customer_name: order.customer?.name || '',
      customer_phone: order.customer?.phone || '',
      delivery_address: order.delivery_address?.street || '',
      delivery_neighborhood: order.delivery_address?.neighborhood || '',
      delivery_city: order.delivery_address?.city || '',
      delivery_state: order.delivery_address?.state || '',
      delivery_zip_code: order.delivery_address?.zip_code || '',
      special_instructions: order.special_instructions || ''
    });
    setShowEdit(true);
  };

  const handleFormChange = (field, value) => {
    setEditForm(p => ({ ...p, [field]: value }));
  };

  const hasGeolocation = order && (
    (order.delivery_latitude && order.delivery_longitude) ||
    (order.pickup_latitude && order.pickup_longitude)
  );

  const handleShowMap = () => {
    if (!hasGeolocation) {
      showToast('Este pedido não possui dados de geolocalização.', 'info');
      return;
    }
    setShowMap(true);
    setTimeout(() => initMap(), 100);
  };

  const initMap = () => {
    if (!mapRef.current || !window.L) return;
    if (mapInstanceRef.current) {
      mapInstanceRef.current.remove();
    }
    const L = window.L;
    const map = L.map(mapRef.current);
    mapInstanceRef.current = map;
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      attribution: '&copy; OpenStreetMap contributors'
    }).addTo(map);
    const markers = [];
    if (order.pickup_latitude && order.pickup_longitude) {
      const pickupMarker = L.marker([order.pickup_latitude, order.pickup_longitude])
        .addTo(map)
        .bindPopup(`<b>Coleta</b><br>${order.restaurant?.name || 'Estabelecimento'}`);
      markers.push(pickupMarker);
    }
    if (order.delivery_latitude && order.delivery_longitude) {
      const deliveryMarker = L.marker([order.delivery_latitude, order.delivery_longitude])
        .addTo(map)
        .bindPopup(`<b>Entrega</b><br>${order.delivery_address?.street || 'Endereço de entrega'}`);
      markers.push(deliveryMarker);
    }
    if (markers.length > 0) {
      const group = L.featureGroup(markers);
      map.fitBounds(group.getBounds().pad(0.1));
    }
  };

  const toLocalTime = (dateStr) => {
    if (!dateStr) return null;
    const str = dateStr.endsWith('Z') ? dateStr : dateStr + 'Z';
    return new Date(str);
  };

  const formatLocalDateTime = (dateStr) => {
    const date = toLocalTime(dateStr);
    return date ? date.toLocaleString('pt-BR') : '';
  };

  const parseSpecialInstructions = (si) => {
    if (!si) return {};
    const info = {};
    try {
      const parsed = JSON.parse(si);
      Object.assign(info, parsed);
    } catch {
      // Não é JSON, parse como tags
    }
    const rejections = [];
    const reReject = /REJECTED_BY_(\d+)/g;
    let match;
    while ((match = reReject.exec(si)) !== null) {
      rejections.push(parseInt(match[1]));
    }
    info.rejections = rejections;
    const timeouts = [];
    const reTimeout = /TIMEOUT_BY_(\d+)/g;
    while ((match = reTimeout.exec(si)) !== null) {
      timeouts.push(parseInt(match[1]));
    }
    info.timeouts = timeouts;
    const offerMatch = si.match(/OFFERED_TO_(\d+)(?:_(\d+))?/);
    info.current_offer = offerMatch ? parseInt(offerMatch[1]) : null;
    info.offer_timestamp = offerMatch && offerMatch[2] ? parseInt(offerMatch[2]) : null;
    return info;
  };

  const getStatusDetail = (order, si) => {
    switch (order.status) {
      case 'SCHEDULED': return 'Será lançado automaticamente';
      case 'PENDING':
        if (si.current_offer) {
          const driverName = drivers[si.current_offer] || `Entregador #${si.current_offer}`;
          return `Oferecido para ${driverName}`;
        }
        return 'Aguardando entregador aceitar';
      case 'ACCEPTED': return `Aceito por ${order.driver?.user?.first_name || 'entregador'}`;
      case 'PICKED_UP': return 'Em rota de entrega';
      case 'DELIVERED': return 'Entrega concluída';
      case 'CANCELLED': return 'Pedido cancelado';
      default: return '';
    }
  };

  const getTimeline = () => {
    if (!order) return [];
    const timeline = [];
    const si = parseSpecialInstructions(order.special_instructions);

    timeline.push({
      status: 'CREATED', time: order.created_at, label: 'Pedido criado',
      detail: `Pedido #${order.order_number}`, icon: '📝', color: '#64748b'
    });

    if (order.scheduled_at) {
      timeline.push({
        status: 'SCHEDULED', time: order.scheduled_at, label: 'Agendado para',
        detail: 'Lançamento programado', icon: '⏰', color: '#6366f1'
      });
    }

    const statusConfig = STATUS_CONFIG[order.status];
    if (statusConfig) {
      timeline.push({
        status: order.status, time: order.updated_at, label: statusConfig.text,
        detail: getStatusDetail(order, si), icon: statusConfig.icon,
        color: statusConfig.color, current: true
      });
    }

    if (si.rejections && si.rejections.length > 0) {
      si.rejections.forEach((driverId) => {
        const driverName = drivers[driverId] || `Entregador #${driverId}`;
        timeline.push({
          status: 'REJECTED', time: null, label: `${driverName} recusou`,
          detail: 'Pedido repassado para próximo entregador', icon: '❌', color: '#ef4444'
        });
      });
    }

    if (si.timeouts && si.timeouts.length > 0) {
      si.timeouts.forEach((driverId) => {
        const driverName = drivers[driverId] || `Entregador #${driverId}`;
        timeline.push({
          status: 'TIMEOUT', time: null, label: `${driverName} não respondeu`,
          detail: 'Timeout - pedido repassado para próximo entregador', icon: '⏰', color: '#f59e0b'
        });
      });
    }

    if (si.current_offer && order.status === 'PENDING') {
      const driverName = drivers[si.current_offer] || `Entregador #${si.current_offer}`;
      timeline.push({
        status: 'OFFERED', time: null, label: `Oferecido para ${driverName}`,
        detail: 'Aguardando aceite', icon: '📱', color: '#f59e0b'
      });
    }

    return timeline;
  };

  if (loading) {
    return (
      <div style={{ minHeight: '60vh', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ width: '3rem', height: '3rem', border: '3px solid #e2e8f0', borderTopColor: '#2563eb', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
      </div>
    );
  }

  if (error || !order) {
    return (
      <div style={{ padding: '2rem', textAlign: 'center' }}>
        <AlertCircle size={48} style={{ color: '#ef4444', marginBottom: '1rem' }} />
        <p style={{ color: '#64748b' }}>{error || 'Pedido não encontrado'}</p>
        <button onClick={() => navigate('/admin/orders')} style={{ marginTop: '1rem', padding: '0.5rem 1rem', borderRadius: '0.5rem', border: 'none', background: '#2563eb', color: 'white', cursor: 'pointer' }}>
          Voltar para Pedidos
        </button>
      </div>
    );
  }

  const statusConfig = STATUS_CONFIG[order.status] || {};
  const si = parseSpecialInstructions(order.special_instructions);
  const timeline = getTimeline();

  return (
    <div style={{ padding: '1.5rem', maxWidth: '900px', margin: '0 auto' }}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '1.5rem' }}>
        <button onClick={() => navigate('/admin/orders')} style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', padding: '0.5rem 1rem', borderRadius: '0.5rem', border: '1px solid #e2e8f0', background: 'white', cursor: 'pointer', fontSize: '0.875rem', color: '#64748b' }}>
          <ArrowLeft size={16} /> Voltar
        </button>
        <div style={{ flex: 1 }}>
          <h1 style={{ fontSize: '1.5rem', fontWeight: 700, color: '#1e293b' }}>
            Pedido #{order.order_number}
          </h1>
          <p style={{ color: '#64748b', fontSize: '0.875rem' }}>
            Criado em {formatLocalDateTime(order.created_at)}
          </p>
        </div>
        <button onClick={loadOrder} style={{ display: 'flex', alignItems: 'center', gap: '0.375rem', padding: '0.5rem 0.75rem', borderRadius: '0.5rem', border: '1px solid #e2e8f0', background: 'white', cursor: 'pointer', fontSize: '0.75rem', color: '#64748b' }}>
          <RefreshCw size={14} /> Atualizar
        </button>
      </div>

      <StatusActions
        order={order}
        statusConfig={statusConfig}
        statusDetail={getStatusDetail(order, si)}
        onEdit={openEditModal}
        onShowMap={handleShowMap}
        onChangeStatus={handleChangeStatus}
      />

      <OrderTimeline timeline={timeline} statusConfig={statusConfig} formatLocalDateTime={formatLocalDateTime} />

      <OrderInfoCards order={order} si={si} utils={utils} />

      {showMap && <MapModal order={order} mapRef={mapRef} onClose={() => setShowMap(false)} />}

      {showEdit && (
        <EditOrderModal
          order={order}
          editForm={editForm}
          editLoading={editLoading}
          onClose={() => setShowEdit(false)}
          onSave={handleEdit}
          onFormChange={handleFormChange}
        />
      )}

      <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
    </div>
  );
};

