import StepIndicator from './client-register/StepIndicator';
import BrandingSide from './client-register/BrandingSide';

const ClientRegisterPage = () => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({
    // Dados do estabelecimento
    name: '', cnpj: '', phone: '', email: '',
    // Acesso
    password: '', confirmPassword: '',
    // Endereço
    address_street: '', address_number: '', address_neighborhood: '',
    address_city: 'Capão da Canoa', address_state: 'RS', address_zip: '',
    // Configurações
    preparation_minutes: '10',
    pickup_confirmation_type: 'code',
    delivery_confirmation_type: 'code',
  });
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [localError, setLocalError] = useState('');

  const { error, clearError } = useAuth();
  const navigate = useNavigate();

  const handleChange = (e) => {
    setFormData(prev => ({ ...prev, [e.target.name]: e.target.value }));
    clearError();
    setLocalError('');
