    }
    if (step === 2) {
      if (!formData.email) { setLocalError('Email é obrigatório'); return false; }
      if (formData.password !== formData.confirmPassword) { setLocalError('As senhas não coincidem'); return false; }
      if (formData.password.length < 6) { setLocalError('A senha deve ter pelo menos 6 caracteres'); return false; }
    }
    if (step === 3 && (!formData.address_street || !formData.address_number || !formData.address_neighborhood)) {
      setLocalError('Preencha rua, número e bairro');
      return false;
    }
    return true;
  };

  const nextStep = () => { if (validateStep()) { setStep(s => s + 1); setLocalError(''); } };
  const prevStep = () => { setStep(s => s - 1); setLocalError(''); };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validateStep()) return;

    setIsLoading(true);
    try {
      const response = await fetch(`${import.meta.env.VITE_API_URL || 'https://muvlog-api-890250693883.us-central1.run.app'}/api/auth/register-client`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          first_name: formData.name,
          last_name: '',
          email: formData.email,
          phone: formData.phone,
          password: formData.password,
          cnpj: formData.cnpj || null,
          establishment_name: formData.name,
          address: `${formData.address_street}, ${formData.address_number} - ${formData.address_neighborhood}, ${formData.address_city} - ${formData.address_state}, ${formData.address_zip}`,
          preparation_minutes: parseInt(formData.preparation_minutes) || 10,
          pickup_confirmation_type: formData.pickup_confirmation_type,
          delivery_confirmation_type: formData.delivery_confirmation_type,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        setLocalError(data.error || 'Erro ao criar conta');
        return;
      }

      // Limpar token antigo e salvar token do novo cadastro
      localStorage.removeItem('token');
      localStorage.removeItem('user');
      if (data.access_token) {
        localStorage.setItem('token', data.access_token);
        localStorage.setItem('user', JSON.stringify(data.user));
      }

      navigate('/pending-approval');
    } catch (err) {
      setLocalError('Erro ao conectar com o servidor');
    } finally {
      setIsLoading(false);
    }
  };

  const currentError = localError || error;

  const inputStyle = {
    width: '100%', padding: '0.625rem 0.875rem', borderRadius: '0.5rem',
    border: '1.5px solid #e2e8f0', fontSize: '0.875rem', outline: 'none',
    boxSizing: 'border-box', fontFamily: 'inherit'
  };

  const labelStyle = {
    display: 'block', fontSize: '0.8125rem', fontWeight: 500, color: '#374151', marginBottom: '0.375rem'
  };

  return (
    <div className="auth-split-layout">
      <BrandingSide />

      {/* Lado direito - Formulário */}
      <div className="auth-form-panel">
        <div className="auth-form-container auth-animate-in">
          <div style={{ marginBottom: '1.5rem', textAlign: 'center' }}>
            <h2 style={{ fontSize: '1.75rem', fontWeight: 700, color: '#1e293b', marginBottom: '0.5rem' }}>
              Cadastro de Estabelecimento
            </h2>
            <p style={{ color: '#64748b', fontSize: '0.9375rem' }}>
              Preencha os dados do seu estabelecimento
            </p>
          </div>

          <StepIndicator step={step} />

          <div className="auth-form-card">
            <div style={{ minHeight: currentError ? 'auto' : '0' }}>
              {currentError && (
                <div className="auth-error">
                  <svg width="16" height="16" viewBox="0 0 16 16" fill="currentColor">
                    <path d="M8 1C4.1 1 1 4.1 1 8s3.1 7 7 7 7-3.1 7-7-3.1-7-7-7zm-.5 3h1v5h-1V4zm.5 7.5c-.4 0-.7-.3-.7-.7s.3-.7.7-.7.7.3.7.7-.3.7-.7.7z"/>
                  </svg>
                  {currentError}
                </div>
              )}
            </div>

            <form onSubmit={handleSubmit}>
              {/* Etapa 1 - Dados do Estabelecimento */}
              {step === 1 && (
                <div className="auth-animate-in" key="step1">
                  <div style={{ marginBottom: '1rem' }}>
                    <label style={labelStyle}>Nome do Estabelecimento *</label>
                    <p style={{ fontSize: '0.75rem', color: '#64748b', marginTop: '0.25rem', marginBottom: '0.25rem' }}>Nome que aparecerá para os entregadores e clientes</p>
                    <input name="name" style={inputStyle} placeholder="Ex: Farmácia da Esquina"
                      value={formData.name} onChange={handleChange} required />
                  </div>
                  <div style={{ marginBottom: '1rem' }}>
                    <label style={labelStyle}>CNPJ</label>
                    <p style={{ fontSize: '0.75rem', color: '#64748b', marginTop: '0.25rem', marginBottom: '0.25rem' }}>Cadastro Nacional da Pessoa Jurídica (opcional para pessoa física)</p>
                    <input name="cnpj" style={inputStyle} placeholder="00.000.000/0001-00"
                      value={formData.cnpj} onChange={handleChange} />
                  </div>
                  <div style={{ marginBottom: '1rem' }}>
                    <label style={labelStyle}>Telefone *</label>
                    <p style={{ fontSize: '0.75rem', color: '#64748b', marginTop: '0.25rem', marginBottom: '0.25rem' }}>Telefone para contato com entregadores</p>
                    <input name="phone" style={inputStyle} placeholder="(51) 99999-9999"
                      value={formData.phone} onChange={handleChange} required />
                  </div>
                  <div style={{ marginBottom: '1.5rem' }}>
                    <label style={labelStyle}>Email *</label>
                    <input type="email" name="email" style={inputStyle} placeholder="contato@estabelecimento.com"
                      value={formData.email} onChange={handleChange} required />
                  </div>
                  <button type="button" className="auth-btn-primary" onClick={nextStep}>
                    Próximo <ArrowRight size={18} />
                  </button>
                </div>
              )}

              {/* Etapa 2 - Acesso */}
              {step === 2 && (
                <div className="auth-animate-in" key="step2">
                  <div style={{ marginBottom: '1rem' }}>
                    <label style={labelStyle}>Senha *</label>
                    <div className="password-wrapper">
                      <input type={showPassword ? 'text' : 'password'} name="password" style={{ ...inputStyle, paddingRight: '2.75rem' }}
                        placeholder="Mínimo 6 caracteres" value={formData.password} onChange={handleChange} required />
                      <button type="button" className="password-toggle" onClick={() => setShowPassword(!showPassword)}>
                        {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                      </button>
                    </div>
                  </div>
                  <div style={{ marginBottom: '1.5rem' }}>
                    <label style={labelStyle}>Confirmar Senha *</label>
                    <div className="password-wrapper">
                      <input type={showConfirmPassword ? 'text' : 'password'} name="confirmPassword" style={{ ...inputStyle, paddingRight: '2.75rem' }}
                        placeholder="Confirme sua senha" value={formData.confirmPassword} onChange={handleChange} required />
                      <button type="button" className="password-toggle" onClick={() => setShowConfirmPassword(!showConfirmPassword)}>
                        {showConfirmPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                      </button>
                    </div>
                  </div>
                  <div style={{ display: 'flex', gap: '0.75rem' }}>
                    <button type="button" className="auth-btn-secondary" onClick={prevStep} style={{ flex: 1 }}>
                      <ArrowLeft size={18} /> Voltar
                    </button>
                    <button type="button" className="auth-btn-primary" onClick={nextStep} style={{ flex: 2 }}>
                      Próximo <ArrowRight size={18} />
                    </button>
                  </div>
                </div>
              )}

              {/* Etapa 3 - Endereço */}
              {step === 3 && (
                <div className="auth-animate-in" key="step3">
                  <div style={{ marginBottom: '1rem' }}>
                    <label style={labelStyle}>Rua/Avenida *</label>
                    <p style={{ fontSize: '0.75rem', color: '#64748b', marginTop: '0.25rem', marginBottom: '0.25rem' }}>Endereço completo do estabelecimento (ponto de coleta)</p>
                    <input name="address_street" style={inputStyle} placeholder="Ex: Rua das Flores"
                      value={formData.address_street} onChange={handleChange} required />
                  </div>
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem', marginBottom: '1rem' }}>
                    <div>
                      <label style={labelStyle}>Número *</label>
                      <input name="address_number" style={inputStyle} placeholder="123"
                        value={formData.address_number} onChange={handleChange} required />
                    </div>
                    <div>
                      <label style={labelStyle}>Bairro *</label>
                      <input name="address_neighborhood" style={inputStyle} placeholder="Centro"
                        value={formData.address_neighborhood} onChange={handleChange} required />
                    </div>
                  </div>
                  <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '1rem', marginBottom: '1rem' }}>
                    <div>
                      <label style={labelStyle}>Cidade</label>
                      <input name="address_city" style={inputStyle} placeholder="Capão da Canoa"
                        value={formData.address_city} onChange={handleChange} />
                    </div>
                    <div>
                      <label style={labelStyle}>UF</label>
                      <input name="address_state" style={inputStyle} placeholder="RS"
                        value={formData.address_state} onChange={handleChange} />
                    </div>
                  </div>
                  <div style={{ marginBottom: '1.5rem' }}>
                    <label style={labelStyle}>CEP</label>
                    <input name="address_zip" style={inputStyle} placeholder="95555-000"
                      value={formData.address_zip} onChange={handleChange} />
                  </div>
                  <div style={{ display: 'flex', gap: '0.75rem' }}>
                    <button type="button" className="auth-btn-secondary" onClick={prevStep} style={{ flex: 1 }}>
                      <ArrowLeft size={18} /> Voltar
                    </button>
                    <button type="button" className="auth-btn-primary" onClick={nextStep} style={{ flex: 2 }}>
                      Próximo <ArrowRight size={18} />
                    </button>
                  </div>
                </div>
              )}

              {/* Etapa 4 - Configurações */}
              {step === 4 && (
                <div className="auth-animate-in" key="step4">
                  <div style={{ marginBottom: '1rem' }}>
                    <label style={labelStyle}>Tempo de Preparo (minutos)</label>
                    <p style={{ fontSize: '0.75rem', color: '#64748b', marginTop: '0.25rem', marginBottom: '0.25rem' }}>Tempo médio que o estabelecimento leva para preparar um pedido (em minutos)</p>
                    <input type="number" name="preparation_minutes" style={inputStyle} placeholder="10"
                      value={formData.preparation_minutes} onChange={handleChange} min="1" max="120" />
                  </div>
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem', marginBottom: '1rem' }}>
                    <div>
                      <label style={labelStyle}>Confirmação de Coleta</label>
                      <p style={{ fontSize: '0.75rem', color: '#64748b', marginTop: '0.25rem', marginBottom: '0.25rem' }}>Como o entregador confirma que coletou o pedido (código, foto, ou nenhum)</p>
                      <select name="pickup_confirmation_type" value={formData.pickup_confirmation_type} onChange={handleChange} style={inputStyle}>
                        <option value="code">Código</option>
                        <option value="photo">Foto</option>
                        <option value="code_and_photo">Código + Foto</option>
                        <option value="none">Nenhuma</option>
                      </select>
                    </div>
                    <div>
                      <label style={labelStyle}>Confirmação de Entrega</label>
                      <p style={{ fontSize: '0.75rem', color: '#64748b', marginTop: '0.25rem', marginBottom: '0.25rem' }}>Como o entregador confirma que entregou o pedido (código, foto, ou nenhum)</p>
                      <select name="delivery_confirmation_type" value={formData.delivery_confirmation_type} onChange={handleChange} style={inputStyle}>
                        <option value="code">Código</option>
                        <option value="photo">Foto</option>
                        <option value="code_and_photo">Código + Foto</option>
                        <option value="none">Nenhuma</option>
                      </select>
                    </div>
                  </div>
                  <div style={{ padding: '0.75rem', background: '#f0fdf4', borderRadius: '0.5rem', border: '1px solid #bbf7d0', marginBottom: '1.5rem' }}>
                    <p style={{ fontSize: '0.75rem', color: '#166534' }}>
                      <strong>Praça e Tabela de Preços</strong> serão definidos pelo administrador após aprovação do cadastro.
                    </p>
                  </div>
                  <div style={{ display: 'flex', gap: '0.75rem' }}>
                    <button type="button" className="auth-btn-secondary" onClick={prevStep} style={{ flex: 1 }}>
                      <ArrowLeft size={18} /> Voltar
                    </button>
                    <button type="submit" className="auth-btn-primary" disabled={isLoading} style={{ flex: 2 }}>
                      {isLoading ? (
                        <span style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem' }}>
                          <span style={{ width: '1rem', height: '1rem', border: '2px solid rgba(255,255,255,0.3)', borderTopColor: 'white', borderRadius: '50%', animation: 'spin 0.6s linear infinite', display: 'inline-block' }} />
                          Criando conta...
                        </span>
                      ) : (
                        <span style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem' }}>
                          Criar Conta <Check size={18} />
                        </span>
                      )}
                    </button>
                  </div>
                </div>
              )}
            </form>
          </div>

          <div style={{ marginTop: '1.5rem', textAlign: 'center' }}>
            <p style={{ color: '#64748b', fontSize: '0.875rem' }}>
              Já tem uma conta?{' '}
              <Link to="/client/login" className="auth-footer-link">Faça login</Link>
            </p>
          </div>
        </div>
      </div>

      <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
    </div>
  );
};

export default ClientRegisterPage;

import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Package, AlertCircle, Store } from 'lucide-react';
import { orderService, adminService } from '@/lib/api';
import { useAuth } from '@/contexts/AuthContext';
import { Card, Label, inputStyle } from './new-order/shared';
import CustomerFields from './new-order/CustomerFields';
import DeliveryAddressFields from './new-order/DeliveryAddressFields';
import PaymentFields from './new-order/PaymentFields';
import OrderSummary from './new-order/OrderSummary';
import PinMapModal from './new-order/PinMapModal';
import SuccessView from './new-order/SuccessView';

const NewOrderPage = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);
  const [createdOrder, setCreatedOrder] = useState(null);
  const [showDistribution, setShowDistribution] = useState(false);
  const [establishments, setEstablishments] = useState([]);
  const [pricingTable, setPricingTable] = useState(null);
  const [hasOwnDrivers, setHasOwnDrivers] = useState(false);
  const [estimatedFee, setEstimatedFee] = useState(null);
  const [calculatingFee, setCalculatingFee] = useState(false);
  const [showPinMap, setShowPinMap] = useState(false);
  const [pinLocation, setPinLocation] = useState(null);
  const [pinAdjusted, setPinAdjusted] = useState(false);
  const [mapInitialized, setMapInitialized] = useState(false);
  const mapContainerRef = useRef(null);
  const previewMapRef = useRef(null);
  const previewMapInstanceRef = useRef(null);
  const mapInstanceRef = useRef(null);
  const markerRef = useRef(null);
  const isAdmin = user?.user_type === 'ADMIN';

  const [form, setForm] = useState({
    selected_establishment: '',
    customer_name: '',
    customer_phone: '',
    delivery_address: '',
    delivery_number: '',
    delivery_complement: '',
    delivery_neighborhood: '',
    delivery_city: 'Capão da Canoa',
    delivery_state: 'RS',
    delivery_zip_code: '',
    product_value: '',
    product_payment_type: 'ESTABLISHMENT',
    product_payment_method: 'CASH',
    change_for: '',
    special_instructions: '',
  });

  useEffect(() => {
    if (!isAdmin) {
      import('@/lib/api').then(({ default: api }) => {
        api.get('/api/user/profile').then(res => {
          setHasOwnDrivers(res.data.has_own_drivers || false);
        }).catch(() => {});
      });
    }
  }, [isAdmin]);

  useEffect(() => {
    if (!document.querySelector('link[href*="leaflet.css"]')) {
      const link = document.createElement('link');
      link.rel = 'stylesheet';
      link.href = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';
      document.head.appendChild(link);
    }
    if (!window.L) {
      const script = document.createElement('script');
      script.src = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
      script.async = true;
      document.head.appendChild(script);
    }
  }, []);

  useEffect(() => {
    if (isAdmin) {
      adminService.getEstablishments(1, 100).then(data => {
        setEstablishments(data.establishments || []);
      }).catch(err => console.error(err));
    }
  }, [isAdmin]);

  useEffect(() => {
    if (form.selected_establishment) {
      const est = establishments.find(e => e.id === parseInt(form.selected_establishment));
      if (est && est.pricing_table_id) {
        adminService.getPricingTable(est.pricing_table_id).then(data => {
          setPricingTable(data.pricing_table);
        }).catch(() => setPricingTable(null));
      } else {
        setPricingTable(null);
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [form.selected_establishment]);

  const calculateFee = async (customLat = null, customLng = null) => {
    if (!form.delivery_address || !form.delivery_number || !form.delivery_neighborhood) {
      setError('Preencha o endereço completo para calcular o frete');
      return;
    }
    try {
      setCalculatingFee(true);
      setError('');
      const fullAddress = form.delivery_address + ', ' + form.delivery_number + ' - ' + form.delivery_neighborhood + ', ' + form.delivery_city + ' - ' + form.delivery_state;
      const { default: api } = await import('@/lib/api');
      const payload = {
        delivery_address: fullAddress,
        delivery_city: form.delivery_city,
        delivery_state: form.delivery_state,
        restaurant_id: isAdmin ? form.selected_establishment : undefined
      };
      if (customLat && customLng) {
        payload.latitude = customLat;
        payload.longitude = customLng;
      }
      const res = await api.post('/api/orders/estimate-fee', payload);
      setEstimatedFee(res.data);
      if (res.data.latitude && res.data.longitude) {
        setPinLocation({ lat: res.data.latitude, lng: res.data.longitude });
        setTimeout(() => initPreviewMap(res.data.latitude, res.data.longitude), 300);
      }
      if (res.data.distance_km === 0 && !customLat) {
        setError('Não foi possível calcular a distância. Use "Ajustar no Mapa" para marcar o local exato.');
      }
    } catch (err) {
      const errorMsg = err.response?.data?.error || 'Erro ao calcular frete';
      if (errorMsg.includes('Estabelecimento não encontrado')) {
        setError('Estabelecimento não encontrado. Verifique se o cadastro foi aprovado pelo administrador.');
      } else {
        setError(errorMsg);
      }
    } finally {
      setCalculatingFee(false);
    }
  };

  const initPinMap = (lat, lng) => {
    if (!mapContainerRef.current || !window.L) return;
    const L = window.L;
    if (mapInstanceRef.current) mapInstanceRef.current.remove();
    const map = L.map(mapContainerRef.current).setView([lat, lng], 15);
    mapInstanceRef.current = map;
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      attribution: '&copy; OpenStreetMap'
    }).addTo(map);
    const marker = L.marker([lat, lng], { draggable: true }).addTo(map);
    markerRef.current = marker;
    marker.on('dragend', function(e) {
      const pos = e.target.getLatLng();
      setPinLocation({ lat: pos.lat, lng: pos.lng });
    });
    setMapInitialized(true);
  };

  const initPreviewMap = (lat, lng) => {
    if (!previewMapRef.current || !window.L) return;
    const L = window.L;
    if (previewMapInstanceRef.current) previewMapInstanceRef.current.remove();
    const map = L.map(previewMapRef.current).setView([lat, lng], 16);
    previewMapInstanceRef.current = map;
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      attribution: '&copy; OpenStreetMap'
    }).addTo(map);
    L.marker([lat, lng]).addTo(map);
  };

  const handleConfirmPin = async () => {
    if (!pinLocation) return;
    setShowPinMap(false);
    setPinAdjusted(true);
    await calculateFee(pinLocation.lat, pinLocation.lng);
  };

  const handleResetPin = () => {
    setPinAdjusted(false);
    setPinLocation(null);
    setEstimatedFee(null);
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm(prev => ({ ...prev, [name]: value }));
    setError('');
  };

  const handleOpenPinMap = () => {
    setShowPinMap(true);
    if (pinLocation) setTimeout(() => initPinMap(pinLocation.lat, pinLocation.lng), 200);
  };

  const DISTANCE_KM = 0;
  const PRICE_PER_KM = pricingTable?.price_per_km || 2.95;
  const MIN_DISTANCE_KM = pricingTable?.min_distance_km || 4;
  const DELIVERY_FEE = 0;
  const PRODUCT_VALUE = parseFloat((form.product_value || '').replace(',', '.')) || 0;
  const TOTAL = DELIVERY_FEE;

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    if (isAdmin && !form.selected_establishment) { setError('Selecione um estabelecimento'); return; }
    if (!form.customer_name.trim()) { setError('Nome do cliente é obrigatório'); return; }
    if (!form.customer_phone.trim()) { setError('Telefone do cliente é obrigatório'); return; }
    if (!form.delivery_address.trim()) { setError('Endereço é obrigatório'); return; }
    if (!form.delivery_number.trim()) { setError('Número é obrigatório'); return; }
    if (!form.delivery_neighborhood.trim()) { setError('Bairro é obrigatório'); return; }
    if (!estimatedFee) { setError('Calcule o frete antes de enviar o pedido'); return; }
    if (form.product_payment_type === 'DELIVERY' && !form.product_value) { setError('Valor dos itens é obrigatório para cobrança na entrega'); return; }
    try {
      setIsLoading(true);
      const fullAddress = form.delivery_address + ', ' + form.delivery_number + (form.delivery_complement ? ' - ' + form.delivery_complement : '');
      const DELIVERY_FEE = estimatedFee.delivery_fee || 0;
      const orderItems = [{ name: 'Entrega', quantity: 1, price: 0 }];
      if (form.product_payment_type === 'DELIVERY' && PRODUCT_VALUE > 0) {
        orderItems.push({ name: 'Produtos', quantity: 1, price: PRODUCT_VALUE });
      }
      const subtotal = orderItems.reduce((sum, item) => sum + (item.price * item.quantity), 0);
      const orderData = {
        ...(isAdmin && { restaurant_id: form.selected_establishment }),
        customer_name: form.customer_name,
        customer_phone: form.customer_phone,
        delivery_address: fullAddress,
        delivery_neighborhood: form.delivery_neighborhood,
        delivery_city: form.delivery_city,
        delivery_state: form.delivery_state,
        delivery_zip_code: form.delivery_zip_code,
        items: orderItems,
        subtotal: subtotal,
        delivery_fee: DELIVERY_FEE,
        total_amount: subtotal + DELIVERY_FEE,
        payment_method: form.product_payment_method,
        special_instructions: form.special_instructions || '',
        product_payment_type: form.product_payment_type,
        product_payment_method: form.product_payment_method,
        change_for: form.change_for || null,
        ...(form.product_payment_type === 'DELIVERY' && { product_value: PRODUCT_VALUE }),
      };
      if (pinLocation) {
        orderData.delivery_latitude = pinLocation.lat;
        orderData.delivery_longitude = pinLocation.lng;
      }
      const response = await orderService.createOrder(orderData);
      setSuccess(true);
      if (!isAdmin && hasOwnDrivers && response.order) {
        setCreatedOrder(response.order);
        setShowDistribution(true);
      } else {
        setTimeout(() => navigate(isAdmin ? '/admin/orders' : '/client/orders'), 2000);
      }
    } catch (err) {
      console.error('Erro ao criar pedido:', err);
      const msg = err.response?.data?.error || err.message || 'Erro ao criar pedido';
      setError(msg);
    } finally {
      setIsLoading(false);
    }
  };

  if (success) {
    return (
      <SuccessView
        showDistribution={showDistribution}
        createdOrder={createdOrder}
        onCloseDistribution={() => { setShowDistribution(false); navigate('/client/orders'); }}
        onDistributed={() => { setShowDistribution(false); navigate('/client/orders'); }}
      />
    );
  }

  return (
    <div style={{ padding: '1.5rem', maxWidth: '700px', margin: '0 auto' }}>
      <div style={{ marginBottom: '1.5rem' }}>
        <button onClick={() => navigate(isAdmin ? '/admin' : '/client')} style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#64748b', display: 'flex', alignItems: 'center', gap: '0.375rem', marginBottom: '0.75rem', fontSize: '0.875rem' }}>
          <ArrowLeft size={16} /> Voltar
        </button>
        <h1 style={{ fontSize: '1.5rem', fontWeight: 700, color: '#1e293b' }}>Lançar Novo Pedido</h1>
      </div>

      {error && (
        <div style={{ background: '#fef2f2', border: '1px solid #fecaca', color: '#dc2626', padding: '0.75rem 1rem', borderRadius: '0.5rem', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.875rem' }}>
          <AlertCircle size={16} /> {error}
        </div>
      )}

      <form onSubmit={handleSubmit}>
        {isAdmin && (
          <Card title="Estabelecimento" icon={<Store size={16} />}>
            <Label>Selecionar Estabelecimento *</Label>
            <select name="selected_establishment" value={form.selected_establishment} onChange={handleChange} required style={inputStyle}>
              <option value="">Selecione um estabelecimento</option>
              {establishments.map(est => (
                <option key={est.id} value={est.id}>{est.name} - {est.address}</option>
              ))}
            </select>
          </Card>
        )}

        <CustomerFields form={form} handleChange={handleChange} />

        <DeliveryAddressFields
          form={form}
          handleChange={handleChange}
          feeCalculatorProps={{
            pricingTable, pricePerKm: PRICE_PER_KM, minDistanceKm: MIN_DISTANCE_KM,
            estimatedFee, pinLocation, previewMapRef, calculatingFee,
            calculateFee, pinAdjusted, handleResetPin, onOpenPinMap: handleOpenPinMap,
          }}
        />

        <PaymentFields form={form} setForm={setForm} handleChange={handleChange} />

        <Card title="Observações" icon={<Package size={16} />}>
          <textarea name="special_instructions" value={form.special_instructions} onChange={handleChange} placeholder="Ex: Urgente, cuidado ao manusear..." rows={3} style={{ ...inputStyle, resize: 'vertical' }} />
        </Card>

        <OrderSummary form={form} estimatedFee={estimatedFee} productValue={PRODUCT_VALUE} />

        <button type="submit" disabled={isLoading} style={{ width: '100%', padding: '1rem', borderRadius: '0.75rem', border: 'none', background: '#0d9488', color: 'white', fontSize: '1rem', fontWeight: 600, cursor: isLoading ? 'not-allowed' : 'pointer', opacity: isLoading ? 0.7 : 1, boxShadow: '0 4px 14px rgba(13, 148, 136, 0.3)' }}>
          {isLoading ? 'Enviando Pedido...' : 'Enviar Pedido'}
        </button>
      </form>

      {showPinMap && (
        <PinMapModal
          pinLocation={pinLocation}
          mapContainerRef={mapContainerRef}
          onClose={() => setShowPinMap(false)}
          onConfirm={handleConfirmPin}
        />
      )}
    </div>
  );
};

export default NewOrderPage;

import React, { useState, useEffect } from 'react';
import { RefreshCw, Wallet, Settings, BarChart3 } from 'lucide-react';
import api from '@/lib/api';
import TabBtn from './own-driver-financial/TabBtn';
import FinancialStats from './own-driver-financial/FinancialStats';
import PaymentHistory from './own-driver-financial/PaymentHistory';
import PaymentConfigForm from './own-driver-financial/PaymentConfigForm';
import ComparisonView from './own-driver-financial/ComparisonView';

const OwnDriverFinancialPage = () => {
  const [activeTab, setActiveTab] = useState('earnings');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  // Dados
  const [paymentConfig, setPaymentConfig] = useState(null);
  const [earnings, setEarnings] = useState([]);
  const [summary, setSummary] = useState(null);
  const [drivers, setDrivers] = useState([]);
  const [comparison, setComparison] = useState(null);

  // Filtros
  const [period, setPeriod] = useState('week');
  const [driverFilter, setDriverFilter] = useState('');
  const [paidFilter, setPaidFilter] = useState('');

  // Edição
  const [editingConfig, setEditingConfig] = useState(false);
  const [configForm, setConfigForm] = useState({
    payment_type: 'PER_DELIVERY',
    fixed_value: 5.00,
    km_value: 1.50,
    percentage: 70.0,
    delivery_value: 3.00,
    max_deliveries: 10
  });

  useEffect(() => { loadData(); }, [period, driverFilter, paidFilter]);

  const loadData = async () => {
    try {
      setLoading(true);
      setError('');
      await Promise.all([
        loadPaymentConfig(),
        loadEarnings(),
        loadDrivers(),
        loadComparison()
      ]);
    } catch (err) {
      setError('Erro ao carregar dados');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const loadPaymentConfig = async () => {
    try {
      const res = await api.get('/api/admin/establishment-drivers/payment-config');
      setPaymentConfig(res.data);
      setConfigForm(res.data);
    } catch (err) {
      console.error('Erro ao carregar config:', err);
    }
  };

  const loadEarnings = async () => {
    try {
      const params = { period };
      if (driverFilter) params.driver_id = driverFilter;
      if (paidFilter) params.is_paid = paidFilter;

      const res = await api.get('/api/admin/establishment-drivers/earnings', { params });
      setEarnings(res.data.earnings || []);
      setSummary(res.data.summary || {});
    } catch (err) {
      console.error('Erro ao carregar ganhos:', err);
    }
  };

  const loadDrivers = async () => {
    try {
      const userRes = await api.get('/api/user/profile');
      const restaurantId = userRes.data.restaurant_id;
      if (restaurantId) {
        const res = await api.get(`/api/admin/establishment-drivers?restaurant_id=${restaurantId}`);
        setDrivers(res.data.drivers || []);
      }
    } catch (err) {
      console.error('Erro ao carregar entregadores:', err);
    }
  };

  const loadComparison = async () => {
    try {
      const res = await api.get('/api/admin/establishment-drivers/earnings/comparison', {
        params: { period }
      });
      setComparison(res.data);
    } catch (err) {
      console.error('Erro ao carregar comparativo:', err);
    }
  };

  const handleSaveConfig = async () => {
    try {
      const payload = { payment_type: configForm.payment_type };
      if (configForm.payment_type === 'PER_KM') {
        payload.km_value = configForm.km_value;
      } else if (configForm.payment_type === 'PERCENTAGE') {
        payload.percentage = configForm.percentage;
      } else if (configForm.payment_type === 'FIXED_PLUS_DELIVERY') {
        payload.fixed_value = configForm.fixed_value;
        payload.delivery_value = configForm.delivery_value;
      } else if (configForm.payment_type === 'FIXED_UP_TO_PLUS_DELIVERY') {
        payload.fixed_value = configForm.fixed_value;
        payload.delivery_value = configForm.delivery_value;
        payload.max_deliveries = configForm.max_deliveries;
      } else {
        payload.fixed_value = configForm.fixed_value;
      }
      await api.put('/api/admin/establishment-drivers/payment-config', payload);
      setPaymentConfig(configForm);
      setEditingConfig(false);
      setSuccess('Configuração salva!');
      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      setError('Erro ao salvar configuração');
    }
  };

  const handlePayEarning = async (earningId) => {
    try {
      await api.post(`/api/admin/establishment-drivers/earnings/${earningId}/pay`, {
        payment_method: 'PIX'
      });
      loadEarnings();
      setSuccess('Pagamento registrado!');
      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      setError('Erro ao registrar pagamento');
    }
  };

  const handlePayAll = async (driverId) => {
    if (!confirm('Marcar todos os ganhos pendentes como pagos?')) return;
    try {
      const res = await api.post('/api/admin/establishment-drivers/earnings/pay-all', {
        driver_id: driverId,
        payment_method: 'PIX'
      });
      loadEarnings();
      setSuccess(`${res.data.count} pagamentos registrados! Total: R$ ${(res.data.total_paid || 0).toFixed(2)}`);
      setTimeout(() => setSuccess(''), 5000);
    } catch (err) {
      setError('Erro ao registrar pagamentos');
    }
  };

  if (loading) {
    return (
      <div style={{ minHeight: '60vh', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ width: '3rem', height: '3rem', border: '3px solid #e2e8f0', borderTopColor: '#2563eb', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
      </div>
    );
  }

  return (
    <div style={{ padding: '1.5rem', maxWidth: '1200px', margin: '0 auto' }}>
      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem' }}>
        <div>
          <h1 style={{ fontSize: '1.75rem', fontWeight: 700, color: '#1e293b' }}>
            Financeiro - Entregadores Próprios
          </h1>
          <p style={{ color: '#64748b', fontSize: '0.9375rem' }}>
            Controle de pagamentos e ganhos dos seus entregadores
          </p>
        </div>
        <button onClick={loadData} style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', padding: '0.5rem 1rem', borderRadius: '0.5rem', border: '1px solid #e2e8f0', background: 'white', cursor: 'pointer', fontSize: '0.875rem', color: '#64748b' }}>
          <RefreshCw size={16} /> Atualizar
        </button>
      </div>

      {/* Alerts */}
      {error && (
        <div style={{ background: '#fef2f2', border: '1px solid #fecaca', color: '#dc2626', padding: '0.75rem', borderRadius: '0.5rem', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.875rem' }}>
          {error}
        </div>
      )}
      {success && (
        <div style={{ background: '#dcfce7', border: '1px solid #86efac', color: '#166534', padding: '0.75rem', borderRadius: '0.5rem', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.875rem' }}>
          {success}
        </div>
      )}

      {/* Tabs */}
      <div style={{ display: 'flex', gap: '0.5rem', marginBottom: '1.5rem', borderBottom: '2px solid #e2e8f0', paddingBottom: '0.5rem' }}>
        <TabBtn active={activeTab === 'earnings'} onClick={() => setActiveTab('earnings')}>
          <Wallet size={16} /> Ganhos
        </TabBtn>
        <TabBtn active={activeTab === 'config'} onClick={() => setActiveTab('config')}>
          <Settings size={16} /> Configuração
        </TabBtn>
        <TabBtn active={activeTab === 'comparison'} onClick={() => setActiveTab('comparison')}>
          <BarChart3 size={16} /> Comparativo
        </TabBtn>
      </div>

      {/* Tab: Ganhos */}
      {activeTab === 'earnings' && (
        <div>
          <FinancialStats summary={summary} />
          <PaymentHistory
            earnings={earnings}
            summary={summary}
            drivers={drivers}
            driverFilter={driverFilter}
            paidFilter={paidFilter}
            period={period}
            onPeriodChange={setPeriod}
            onDriverFilterChange={setDriverFilter}
            onPaidFilterChange={setPaidFilter}
            onPayEarning={handlePayEarning}
            onPayAll={handlePayAll}
          />
        </div>
      )}

      {/* Tab: Configuração */}
      {activeTab === 'config' && (
        <PaymentConfigForm
          configForm={configForm}
          onConfigFormChange={setConfigForm}
          onSave={handleSaveConfig}
        />
      )}

      {/* Tab: Comparativo */}
      {activeTab === 'comparison' && comparison && (
        <ComparisonView comparison={comparison} />
      )}

      <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
    </div>
  );
};

export default OwnDriverFinancialPage;

import React, { useState, useEffect } from 'react';
import {
  BarChart3, Users, Clock, DollarSign, Star, TrendingUp,
  Package, AlertCircle, Filter, Target
} from 'lucide-react';
import api from '@/lib/api';
import { utils } from '@/lib/api';

const OwnDriverMetricsPage = () => {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [metrics, setMetrics] = useState([]);
  const [summary, setSummary] = useState(null);
  const [drivers, setDrivers] = useState([]);
  const [period, setPeriod] = useState('month');
  const [driverFilter, setDriverFilter] = useState('');

  useEffect(() => { loadData(); }, [period, driverFilter]);

  const loadData = async () => {
    try {
      setLoading(true);
      setError('');
      await Promise.all([loadDrivers(), loadMetrics()]);
    } catch (err) {
      setError('Erro ao carregar dados');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const loadDrivers = async () => {
    try {
      const userRes = await api.get('/api/user/profile');
      const restaurantId = userRes.data.restaurant_id;
      if (restaurantId) {
        const res = await api.get(`/api/admin/establishment-drivers?restaurant_id=${restaurantId}`);
        setDrivers(res.data.drivers || []);
      }
    } catch (err) {
      console.error('Erro ao carregar entregadores:', err);
    }
  };

  const loadMetrics = async () => {
    try {
      const params = { period };
      if (driverFilter) params.driver_id = driverFilter;
      const res = await api.get('/api/admin/establishment-drivers/metrics', { params });
      setMetrics(res.data.drivers || []);
      setSummary(res.data.summary || {});
    } catch (err) {
      console.error('Erro ao carregar métricas:', err);
    }
  };

  const getRatingColor = (rating) => {
    if (rating >= 4.5) return '#16a34a';
    if (rating >= 3.5) return '#0d9488';
    if (rating >= 2.5) return '#f59e0b';
    return '#ef4444';
  };

  const getRatingLabel = (rating) => {
    if (rating >= 4.5) return 'Excelente';
    if (rating >= 3.5) return 'Bom';
    if (rating >= 2.5) return 'Regular';
    return 'Atenção';
  };

  if (loading) {
    return (
      <div style={{ padding: '1.5rem', maxWidth: '1100px', margin: '0 auto' }}>
        <div style={{ minHeight: '50vh', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <div style={{ width: '3rem', height: '3rem', border: '3px solid #e2e8f0', borderTopColor: '#0d9488', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
        </div>
        <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
      </div>
    );
  }

  return (
    <div style={{ padding: '1.5rem', maxWidth: '1100px', margin: '0 auto' }}>
      {/* Header */}
      <div style={{ marginBottom: '1.5rem' }}>
        <h1 style={{ fontSize: '1.75rem', fontWeight: 700, color: '#1e293b', marginBottom: '0.25rem' }}>
          Desempenho dos Entregadores
        </h1>
        <p style={{ color: '#64748b', fontSize: '0.9375rem' }}>
          Métricas e avaliações dos seus entregadores próprios
        </p>
      </div>

      {/* Erro */}
      {error && (
        <div style={{ background: '#fef2f2', border: '1px solid #fecaca', color: '#dc2626', padding: '0.75rem 1rem', borderRadius: '0.5rem', marginBottom: '1.5rem', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.875rem' }}>
          <AlertCircle size={16} /> {error}
        </div>
      )}

      {/* Filtros */}
      <div style={{ background: 'white', borderRadius: '0.75rem', boxShadow: '0 1px 3px rgba(0,0,0,0.05)', padding: '1rem 1.25rem', marginBottom: '1.5rem', display: 'flex', gap: '0.75rem', alignItems: 'center', flexWrap: 'wrap' }}>
        <Filter size={16} style={{ color: '#64748b' }} />
        <select
          value={period}
          onChange={e => setPeriod(e.target.value)}
          style={{ padding: '0.5rem 0.75rem', borderRadius: '0.5rem', border: '1.5px solid #e2e8f0', fontSize: '0.8125rem', outline: 'none', background: 'white' }}
        >
          <option value="week">Última Semana</option>
          <option value="month">Último Mês</option>
        </select>
        <select
          value={driverFilter}
          onChange={e => setDriverFilter(e.target.value)}
          style={{ padding: '0.5rem 0.75rem', borderRadius: '0.5rem', border: '1.5px solid #e2e8f0', fontSize: '0.8125rem', outline: 'none', background: 'white' }}
        >
          <option value="">Todos os Entregadores</option>
          {drivers.map(d => (
            <option key={d.id} value={d.id}>{d.name}</option>
          ))}
        </select>
      </div>

      {/* Cards de Resumo */}
      {summary && (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '1rem', marginBottom: '1.5rem' }}>
          <SummaryCard
            icon={<Users size={22} />}
            iconBg="#dbeafe"
            iconColor="#2563eb"
            label="Entregadores Ativos"
            value={summary.total_drivers}
          />
          <SummaryCard
            icon={<Package size={22} />}
            iconBg="#f0fdfa"
            iconColor="#0d9488"
            label="Total de Entregas"
            value={summary.total_deliveries}
          />
          <SummaryCard
            icon={<DollarSign size={22} />}
            iconBg="#dcfce7"
            iconColor="#16a34a"
            label="Total Ganhos"
            value={utils.formatCurrency(summary.total_earning)}
          />
          <SummaryCard
            icon={<Clock size={22} />}
            iconBg="#fef3c7"
            iconColor="#f59e0b"
            label="Tempo Médio"
            value={`${summary.avg_delivery_time || 0} min`}
          />
        </div>
      )}

      {/* Cards de Entregadores */}
      {metrics.length === 0 ? (
        <div style={{ background: 'white', borderRadius: '0.75rem', padding: '3rem 2rem', textAlign: 'center', boxShadow: '0 1px 3px rgba(0,0,0,0.05)' }}>
          <div style={{ width: '4rem', height: '4rem', borderRadius: '50%', background: '#f0fdfa', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1rem' }}>
            <Users size={24} style={{ color: '#64748b' }} />
          </div>
          <p style={{ fontWeight: 600, color: '#1e293b', marginBottom: '0.25rem' }}>
            Nenhum entregador encontrado
          </p>
          <p style={{ fontSize: '0.875rem', color: '#64748b' }}>
            Cadastre entregadores próprios para ver as métricas
          </p>
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
          {metrics.map(m => (
            <DriverMetricCard
              key={m.driver.id}
              metric={m}
              getRatingColor={getRatingColor}
              getRatingLabel={getRatingLabel}
            />
          ))}
        </div>
      )}
    </div>
  );
};

// Card de resumo
const SummaryCard = ({ icon, iconBg, iconColor, label, value }) => (
  <div style={{
    background: 'white', borderRadius: '0.75rem', padding: '1.25rem',
    boxShadow: '0 1px 3px rgba(0,0,0,0.05)', transition: 'all 0.15s'
  }}
    onMouseEnter={e => { e.currentTarget.style.transform = 'translateY(-2px)'; e.currentTarget.style.boxShadow = '0 4px 12px rgba(0,0,0,0.08)'; }}
    onMouseLeave={e => { e.currentTarget.style.transform = 'translateY(0)'; e.currentTarget.style.boxShadow = '0 1px 3px rgba(0,0,0,0.05)'; }}
  >
    <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
      <div style={{ padding: '0.625rem', borderRadius: '0.5rem', background: iconBg, color: iconColor, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        {icon}
      </div>
      <div>
        <p style={{ fontSize: '0.6875rem', color: '#64748b', marginBottom: '0.125rem' }}>{label}</p>
        <p style={{ fontSize: '1.25rem', fontWeight: 700, color: '#1e293b' }}>{value}</p>
      </div>
    </div>
  </div>
);

// Card de métricas do entregador
const DriverMetricCard = ({ metric, getRatingColor, getRatingLabel }) => {
  const { driver, orders, delivery_time, financial, rating } = metric;
  const vehicleEmoji = driver.vehicle_type === 'MOTO' ? '🏍️' : driver.vehicle_type === 'BIKE' ? '🚲' : '🚗';

  return (
    <div style={{
      background: 'white', borderRadius: '0.75rem',
      boxShadow: '0 1px 3px rgba(0,0,0,0.05)',
      overflow: 'hidden', borderLeft: `4px solid ${getRatingColor(rating.average)}`
    }}>
      {/* Header */}
      <div style={{ padding: '1.25rem', borderBottom: '1px solid #f1f5f9', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
          <div style={{
            width: '3rem', height: '3rem', borderRadius: '50%',
            background: '#dbeafe', display: 'flex', alignItems: 'center', justifyContent: 'center',
            fontSize: '1.5rem'
          }}>
            {vehicleEmoji}
          </div>
          <div>
            <h3 style={{ fontSize: '1rem', fontWeight: 600, color: '#1e293b' }}>{driver.name}</h3>
            <p style={{ fontSize: '0.75rem', color: '#64748b' }}>
              {driver.vehicle_type} {driver.vehicle_plate ? `• ${driver.vehicle_plate}` : ''}
            </p>
          </div>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <div style={{
            padding: '0.375rem 0.75rem', borderRadius: '9999px',
            background: `${getRatingColor(rating.average)}15`,
            color: getRatingColor(rating.average),
            fontSize: '0.8125rem', fontWeight: 600,
            display: 'flex', alignItems: 'center', gap: '0.375rem'
          }}>
            <Star size={14} fill={getRatingColor(rating.average || 0)} />
            {(rating.average || 0).toFixed(1)}
          </div>
          <span style={{ fontSize: '0.6875rem', color: '#64748b' }}>
            ({rating.total_ratings} {rating.total_ratings === 1 ? 'avaliação' : 'avaliações'})
          </span>
        </div>
      </div>

      {/* Métricas */}
      <div style={{ padding: '1.25rem', display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(140px, 1fr))', gap: '1rem' }}>
        <MetricItem
          icon={<Package size={16} />}
          label="Entregas"
          value={orders.delivered}
          sub={`${orders.cancelled} canceladas`}
          color="#0d9488"
        />
        <MetricItem
          icon={<Clock size={16} />}
          label="Tempo Médio"
          value={`${delivery_time.avg_minutes} min`}
          sub={delivery_time.min_minutes > 0 ? `Mín: ${delivery_time.min_minutes} min` : ''}
          color="#f59e0b"
        />
        <MetricItem
          icon={<DollarSign size={16} />}
          label="Ganhos"
          value={utils.formatCurrency(financial.total_earning)}
          sub={`${utils.formatCurrency(financial.avg_per_delivery)}/entrega`}
          color="#16a34a"
        />
        <MetricItem
          icon={<Target size={16} />}
          label="Taxa Sucesso"
          value={`${orders.acceptance_rate}%`}
          sub={`${orders.total} pedidos`}
          color="#2563eb"
        />
      </div>

      {/* Barra de desempenho */}
      <div style={{ padding: '0 1.25rem 1.25rem' }}>
        <div style={{ background: '#f1f5f9', borderRadius: '9999px', height: '0.5rem', overflow: 'hidden' }}>
          <div style={{
            width: `${Math.min(100, orders.acceptance_rate)}%`,
            height: '100%',
            background: `linear-gradient(90deg, ${getRatingColor(rating.average)}, ${getRatingColor(rating.average)}88)`,
            borderRadius: '9999px',
            transition: 'width 0.5s'
          }} />
        </div>
        <p style={{ fontSize: '0.6875rem', color: '#64748b', marginTop: '0.375rem', textAlign: 'center' }}>
          {getRatingLabel(rating.average)} — {orders.acceptance_rate}% de entregas concluídas
        </p>
      </div>
    </div>
  );
};

// Item de métrica
const MetricItem = ({ icon, label, value, sub, color }) => (
  <div style={{ display: 'flex', flexDirection: 'column', gap: '0.25rem' }}>
    <div style={{ display: 'flex', alignItems: 'center', gap: '0.375rem' }}>
      <span style={{ color }}>{icon}</span>
      <span style={{ fontSize: '0.6875rem', color: '#64748b', fontWeight: 500 }}>{label}</span>
    </div>
    <span style={{ fontSize: '1.125rem', fontWeight: 700, color: '#1e293b' }}>{value}</span>
    {sub && <span style={{ fontSize: '0.625rem', color: '#64748b' }}>{sub}</span>}
  </div>
);

