import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Package, DollarSign, MapPin, Bike,
  CheckCircle, RefreshCw, Route, Bell, Navigation, Trophy, Star
} from 'lucide-react';
import api from '@/lib/api';
import { utils } from '@/lib/api';

const LEVEL_CONFIG = {
  diamante: { color: '#B9F2FF', bg: '#e0f7ff', label: 'Diamante', icon: '💎' },
  ouro: { color: '#FFD700', bg: '#fef9c3', label: 'Ouro', icon: '🥇' },
  prata: { color: '#C0C0C0', bg: '#f1f5f9', label: 'Prata', icon: '🥈' },
  bronze: { color: '#CD7F32', bg: '#fef3c7', label: 'Bronze', icon: '🥉' },
};

const STATUS_CONFIG = {
  OFFERED: { color: '#f59e0b', bg: '#fef3c7', text: 'Oferecido', icon: Bell },
  ACCEPTED: { color: '#2563eb', bg: '#dbeafe', text: 'Aceito', icon: CheckCircle },
  PREPARING: { color: '#8b5cf6', bg: '#f3e8ff', text: 'Preparando', icon: Package },
  READY: { color: '#06b6d4', bg: '#cffafe', text: 'Pronto', icon: CheckCircle },
  PICKED_UP: { color: '#3b82f6', bg: '#dbeafe', text: 'A Caminho', icon: Bike },
};

const PlatformDriverDashboardPage = () => {
  const navigate = useNavigate();
  const [routes, setRoutes] = useState([]);
  const [stats, setStats] = useState(null);
  const [muvScore, setMuvScore] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => { loadData(); }, []);

  const loadData = async (isRefresh = false) => {
    try {
      if (!isRefresh) setLoading(true);
      const token = localStorage.getItem('token');
      const headers = { Authorization: `Bearer ${token}` };

      const [routesRes, statsRes, scoreRes] = await Promise.all([
        api.get('/api/platform-routes/driver/active', { headers }),
        api.get('/api/driver/stats', { headers }),
        api.get('/api/muvscore/score', { headers }).catch(() => ({ data: null }))
      ]);

      setRoutes(routesRes.data.routes || []);
      setStats(statsRes.data.stats);
      setMuvScore(scoreRes.data?.score || null);
    } catch (err) {
      if (err.response?.status === 401) {
        navigate('/login');
      } else {
        setError('Erro ao carregar dados');
      }
    } finally {
      if (!isRefresh) setLoading(false);
    }
  };

  const acceptRoute = async (routeId) => {
    try {
      const token = localStorage.getItem('token');
      const headers = { Authorization: `Bearer ${token}` };
      await api.post(`/api/platform-routes/${routeId}/accept`, {}, { headers });
      loadData();
    } catch (err) {
      setError(err.response?.data?.error || 'Erro ao aceitar rota');
    }
  };

  const rejectRoute = async (routeId) => {
    if (!window.confirm('Rejeitar esta rota?')) return;
    try {
      const token = localStorage.getItem('token');
      const headers = { Authorization: `Bearer ${token}` };
      await api.post(`/api/platform-routes/${routeId}/reject`, {}, { headers });
      loadData();
    } catch (err) {
      setError(err.response?.data?.error || 'Erro ao rejeitar rota');
    }
  };

  const completeStop = async (routeId, stopId) => {
    try {
      const token = localStorage.getItem('token');
      const headers = { Authorization: `Bearer ${token}` };
      await api.post(`/api/platform-routes/${routeId}/complete-stop`, { stop_id: stopId }, { headers });
      loadData(true);
    } catch (err) {
      setError(err.response?.data?.error || 'Erro ao concluir parada');
    }
  };

  // Extrair pedidos ativos das rotas
  const activeOrders = [];
  routes.forEach(route => {
    if (route.stops) {
      route.stops.forEach(stop => {
        if (stop.status !== 'COMPLETED' && stop.order_id) {
          activeOrders.push({
            id: stop.order_id,
            order_number: stop.order_number || `Pedido #${stop.order_id}`,
            status: stop.order_status || (route.status === 'ACTIVE' ? 'ACCEPTED' : 'OFFERED'),
            stop_type: stop.stop_type,
            stop_id: stop.id,
            route_id: route.id,
            route_status: route.status,
            address: stop.address,
            customer_name: stop.customer_name
          });
        }
      });
    }
  });

  if (loading) {
    return (
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: '#f1f5f9' }}>
        <div style={{ width: '3rem', height: '3rem', border: '3px solid #e2e8f0', borderTopColor: '#2563eb', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
      </div>
    );
  }

  return (
    <div style={{ minHeight: '100vh', background: '#f1f5f9' }}>
      {/* Header */}
      <header style={{ background: 'linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%)', color: 'white', padding: '1rem' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div>
            <h1 style={{ fontSize: '1.25rem', fontWeight: 700 }}>Dashboard</h1>
            <p style={{ fontSize: '0.875rem', opacity: 0.9 }}>Entregador da Plataforma</p>
          </div>
          <button onClick={() => loadData(true)} style={{ background: 'rgba(255,255,255,0.2)', border: 'none', color: 'white', padding: '0.5rem', borderRadius: '0.5rem', cursor: 'pointer' }}>
            <RefreshCw size={20} />
          </button>
        </div>
      </header>

      <div style={{ padding: '1rem' }}>
        {/* MuvScore Card */}
        {muvScore && (
          <div style={{
            background: `linear-gradient(135deg, ${LEVEL_CONFIG[muvScore.level]?.color || '#CD7F32'}22, white)`,
            borderRadius: '0.75rem', padding: '1rem', marginBottom: '1rem',
            boxShadow: '0 1px 3px rgba(0,0,0,0.05)',
            border: `2px solid ${LEVEL_CONFIG[muvScore.level]?.color || '#CD7F32'}44`
          }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <div>
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '0.25rem' }}>
                  <Trophy size={18} style={{ color: LEVEL_CONFIG[muvScore.level]?.color || '#CD7F32' }} />
                  <span style={{ fontSize: '0.75rem', color: '#64748b', fontWeight: 600 }}>MUVSCORE</span>
                </div>
                <p style={{ fontSize: '2rem', fontWeight: 700, color: '#1e293b' }}>{muvScore.total_points || 0}</p>
                <p style={{ fontSize: '0.75rem', color: '#64748b' }}>pontos esta semana</p>
              </div>
              <div style={{ textAlign: 'center' }}>
                <div style={{
                  fontSize: '2.5rem', marginBottom: '0.25rem'
                }}>
                  {LEVEL_CONFIG[muvScore.level]?.icon || '🥉'}
                </div>
                <span style={{
                  padding: '0.25rem 0.75rem', borderRadius: '9999px', fontSize: '0.75rem', fontWeight: 600,
                  background: LEVEL_CONFIG[muvScore.level]?.bg || '#fef3c7',
                  color: LEVEL_CONFIG[muvScore.level]?.color || '#CD7F32'
                }}>
                  {LEVEL_CONFIG[muvScore.level]?.label || 'Bronze'}
                </span>
              </div>
            </div>
            {/* Barra de progresso */}
            <div style={{ marginTop: '0.75rem' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.6875rem', color: '#64748b', marginBottom: '0.25rem' }}>
                <span>{muvScore.total_points} pts</span>
                <span>
                  {muvScore.level === 'diamante' ? 'Nível máximo!' :
                   muvScore.level === 'ouro' ? `${1000 - muvScore.total_points} pts para Diamante` :
                   muvScore.level === 'prata' ? `${500 - muvScore.total_points} pts para Ouro` :
                   `${100 - muvScore.total_points} pts para Prata`}
                </span>
              </div>
              <div style={{ height: '6px', background: '#e2e8f0', borderRadius: '3px', overflow: 'hidden' }}>
                <div style={{
                  height: '100%', borderRadius: '3px',
                  width: `${Math.min(100, (muvScore.total_points / (muvScore.level === 'diamante' ? 1500 : muvScore.level === 'ouro' ? 1000 : muvScore.level === 'prata' ? 500 : 100)) * 100)}%`,
                  background: `linear-gradient(90deg, ${LEVEL_CONFIG[muvScore.level]?.color || '#CD7F32'}, ${LEVEL_CONFIG[muvScore.level]?.color || '#CD7F32'}88)`
                }} />
              </div>
            </div>
          </div>
        )}

        {/* Stats */}
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.75rem', marginBottom: '1rem' }}>
          <div style={{ background: 'white', borderRadius: '0.75rem', padding: '1rem', boxShadow: '0 1px 3px rgba(0,0,0,0.05)' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '0.5rem' }}>
              <Package size={20} style={{ color: '#2563eb' }} />
              <span style={{ fontSize: '0.75rem', color: '#64748b' }}>Entregas</span>
            </div>
            <p style={{ fontSize: '1.5rem', fontWeight: 700, color: '#1e293b' }}>{stats?.total_deliveries || 0}</p>
          </div>
          <div style={{ background: 'white', borderRadius: '0.75rem', padding: '1rem', boxShadow: '0 1px 3px rgba(0,0,0,0.05)' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '0.5rem' }}>
              <DollarSign size={20} style={{ color: '#16a34a' }} />
              <span style={{ fontSize: '0.75rem', color: '#64748b' }}>Ganhos</span>
            </div>
            <p style={{ fontSize: '1.5rem', fontWeight: 700, color: '#1e293b' }}>{utils.formatCurrency(stats?.total_earning || 0)}</p>
          </div>
        </div>

        {/* Rotas Pendentes (aceitar/rejeitar) */}
        {routes.filter(r => r.status === 'PENDING').length > 0 && (
          <div style={{ marginBottom: '1rem' }}>
            <h2 style={{ fontSize: '1rem', fontWeight: 600, color: '#1e293b', marginBottom: '0.75rem' }}>
              <Bell size={16} style={{ verticalAlign: 'middle', marginRight: '0.5rem', color: '#f59e0b' }} />
              Rotas Aguardando Aceite
            </h2>
            {routes.filter(r => r.status === 'PENDING').map(route => (
              <div key={route.id} style={{ background: 'white', borderRadius: '0.75rem', padding: '1rem', marginBottom: '0.75rem', boxShadow: '0 1px 3px rgba(0,0,0,0.05)', borderLeft: '4px solid #f59e0b' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.75rem' }}>
                  <div>
                    <p style={{ fontWeight: 600, color: '#1e293b' }}>Rota #{route.id}</p>
                    <p style={{ fontSize: '0.75rem', color: '#64748b' }}>{route.stops_count} paradas</p>
                  </div>
                  <span style={{ padding: '0.25rem 0.75rem', borderRadius: '9999px', fontSize: '0.75rem', fontWeight: 600, background: '#fef3c7', color: '#92400e' }}>
                    Aguardando
                  </span>
                </div>
                <div style={{ display: 'flex', gap: '0.5rem' }}>
                  <button
                    onClick={() => acceptRoute(route.id)}
                    style={{ flex: 1, padding: '0.625rem', borderRadius: '0.5rem', border: 'none', background: '#16a34a', color: 'white', fontWeight: 600, cursor: 'pointer' }}
                  >
                    Aceitar
                  </button>
                  <button
                    onClick={() => rejectRoute(route.id)}
                    style={{ flex: 1, padding: '0.625rem', borderRadius: '0.5rem', border: '1px solid #e2e8f0', background: 'white', color: '#64748b', fontWeight: 600, cursor: 'pointer' }}
                  >
                    Rejeitar
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Pedidos Ativos */}
        <div style={{ marginBottom: '1rem' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.75rem' }}>
            <h2 style={{ fontSize: '1rem', fontWeight: 600, color: '#1e293b' }}>
              Pedidos Ativos ({activeOrders.length})
            </h2>
          </div>

          {activeOrders.length === 0 ? (
            <div style={{ background: 'white', borderRadius: '0.75rem', padding: '2rem', textAlign: 'center', boxShadow: '0 1px 3px rgba(0,0,0,0.05)' }}>
              <Route size={40} style={{ color: '#64748b', marginBottom: '0.75rem' }} />
              <p style={{ fontWeight: 600, color: '#1e293b' }}>Nenhuma rota ativa</p>
              <p style={{ fontSize: '0.875rem', color: '#64748b' }}>Aguardando rotas...</p>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
              {activeOrders.map(order => {
                const config = STATUS_CONFIG[order.status] || STATUS_CONFIG.ACCEPTED;
                const StatusIcon = config.icon;
                return (
                  <div key={`${order.route_id}-${order.id}-${order.stop_type}`} style={{ background: 'white', borderRadius: '0.75rem', padding: '1rem', boxShadow: '0 1px 3px rgba(0,0,0,0.05)', borderLeft: `4px solid ${config.color}` }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.5rem' }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                        <span style={{ fontSize: '0.625rem', padding: '0.125rem 0.375rem', borderRadius: '9999px', background: order.stop_type === 'PICKUP' ? '#fef3c7' : '#dbeafe', color: order.stop_type === 'PICKUP' ? '#92400e' : '#1d4ed8' }}>
                          {order.stop_type === 'PICKUP' ? 'Coleta' : 'Entrega'}
                        </span>
                        <span style={{ fontWeight: 700, color: '#1e293b' }}>#{order.order_number}</span>
                      </div>
                      <span style={{ padding: '0.125rem 0.5rem', borderRadius: '9999px', fontSize: '0.6875rem', fontWeight: 600, background: config.bg, color: config.color, display: 'flex', alignItems: 'center', gap: '0.25rem' }}>
                        <StatusIcon size={10} /> {config.text}
                      </span>
                    </div>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.375rem', fontSize: '0.8125rem', color: '#64748b', marginBottom: '0.5rem' }}>
                      <MapPin size={14} />
                      <span>{order.address || 'Endereço não informado'}</span>
                    </div>
                    {order.customer_name && (
                      <p style={{ fontSize: '0.75rem', color: '#64748b', marginBottom: '0.5rem' }}>{order.customer_name}</p>
                    )}
                    {order.route_status === 'ACTIVE' && order.stop_type === 'DELIVERY' && (
                      <button
                        onClick={() => completeStop(order.route_id, order.stop_id)}
                        style={{ width: '100%', padding: '0.5rem', borderRadius: '0.5rem', border: 'none', background: '#16a34a', color: 'white', fontWeight: 600, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem' }}
                      >
                        <CheckCircle size={16} /> Marcar como Entregue
                      </button>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>

      <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
    </div>
  );
};

export default PlatformDriverDashboardPage;

import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Route, Package, MapPin, Clock, CheckCircle, Bike,
  AlertCircle, RefreshCw, Bell, ArrowLeft, Navigation, X
} from 'lucide-react';
import api from '@/lib/api';

const PlatformDriverRoutesPage = () => {
  const navigate = useNavigate();
  const [routes, setRoutes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [selectedRoute, setSelectedRoute] = useState(null);
  const prevPendingCount = useRef(0);
  const audioContextRef = useRef(null);
  const audioEnabledRef = useRef(false);

  // Habilitar áudio após primeira interação do usuário
  useEffect(() => {
    const enableAudio = () => {
      try {
        audioContextRef.current = new (window.AudioContext || window.webkitAudioContext)();
        audioEnabledRef.current = true;
      } catch (e) {}
      document.removeEventListener('click', enableAudio);
      document.removeEventListener('touchstart', enableAudio);
    };
    document.addEventListener('click', enableAudio, { once: true });
    document.addEventListener('touchstart', enableAudio, { once: true });
    
    return () => {
      document.removeEventListener('click', enableAudio);
      document.removeEventListener('touchstart', enableAudio);
    };
  }, []);

  // Auto-refresh a cada 15 segundos
  useEffect(() => {
    loadRoutes();
    const interval = setInterval(() => loadRoutes(true), 15000);
    return () => clearInterval(interval);
  }, []);

  // Tocar som quando novas rotas pendentes aparecem
  useEffect(() => {
    const newPending = routes.filter(r => r.status === 'PENDING').length;
    if (newPending > prevPendingCount.current && prevPendingCount.current > 0) {
      playNotification();
    }
    prevPendingCount.current = newPending;
  }, [routes]);

  const playNotification = () => {
    try {
      if (audioEnabledRef.current && audioContextRef.current) {
        const ctx = audioContextRef.current;
        const oscillator = ctx.createOscillator();
        const gainNode = ctx.createGain();
        
        oscillator.connect(gainNode);
        gainNode.connect(ctx.destination);
        
        oscillator.frequency.value = 800;
        oscillator.type = 'sine';
        
        gainNode.gain.setValueAtTime(0.5, ctx.currentTime);
        gainNode.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.3);
        
        oscillator.start(ctx.currentTime);
        oscillator.stop(ctx.currentTime + 0.3);
        
        setTimeout(() => {
          const osc2 = ctx.createOscillator();
          const gain2 = ctx.createGain();
          osc2.connect(gain2);
          gain2.connect(ctx.destination);
          osc2.frequency.value = 1000;
          osc2.type = 'sine';
          gain2.gain.setValueAtTime(0.5, ctx.currentTime);
          gain2.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.3);
          osc2.start(ctx.currentTime);
          osc2.stop(ctx.currentTime + 0.3);
        }, 200);
      }
    } catch (e) {}
  };

  const loadRoutes = async (isRefresh = false) => {
    try {
      if (!isRefresh) setLoading(true);
      const token = localStorage.getItem('token');
      const headers = { Authorization: `Bearer ${token}` };
      const res = await api.get('/api/platform-routes/driver/active', { headers });
      setRoutes(res.data.routes || []);
    } catch (err) {
      console.error('Erro ao carregar rotas:', err);
      if (!isRefresh) setError('Erro ao carregar rotas');
    } finally {
      if (!isRefresh) setLoading(false);
    }
  };

  const acceptRoute = async (routeId) => {
    try {
      const token = localStorage.getItem('token');
      const headers = { Authorization: `Bearer ${token}` };
      await api.post(`/api/platform-routes/${routeId}/accept`, {}, { headers });
      loadRoutes();
    } catch (err) {
      setError(err.response?.data?.error || 'Erro ao aceitar rota');
    }
  };

  const rejectRoute = async (routeId) => {
    if (!window.confirm('Tem certeza que deseja rejeitar esta rota?')) return;
    try {
      const token = localStorage.getItem('token');
      const headers = { Authorization: `Bearer ${token}` };
      await api.post(`/api/platform-routes/${routeId}/reject`, {}, { headers });
      loadRoutes();
    } catch (err) {
      setError(err.response?.data?.error || 'Erro ao rejeitar rota');
    }
  };

  const completeStop = async (routeId, stopId) => {
    try {
      const token = localStorage.getItem('token');
      const headers = { Authorization: `Bearer ${token}` };
      await api.post(`/api/platform-routes/${routeId}/complete-stop`, { stop_id: stopId }, { headers });
      loadRoutes(true);
    } catch (err) {
      setError(err.response?.data?.error || 'Erro ao concluir parada');
    }
  };

  const getStopIcon = (stop) => {
    if (stop.status === 'COMPLETED') return <CheckCircle size={16} style={{ color: '#16a34a' }} />;
    if (stop.stop_type === 'PICKUP') return <Package size={16} style={{ color: '#f59e0b' }} />;
    return <MapPin size={16} style={{ color: '#2563eb' }} />;
  };

  const getStopLabel = (stop) => {
    if (stop.stop_type === 'PICKUP') return 'Coleta';
    return 'Entrega';
  };

  const pendingRoutes = routes.filter(r => r.status === 'PENDING');
  const activeRoutes = routes.filter(r => r.status === 'ACTIVE');

  if (loading) {
    return (
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: '#f1f5f9' }}>
        <div style={{ width: '3rem', height: '3rem', border: '3px solid #e2e8f0', borderTopColor: '#2563eb', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
      </div>
    );
  }

  return (
    <div style={{ minHeight: '100vh', background: '#f1f5f9' }}>
      {/* Header */}
      <header style={{
        background: pendingRoutes.length > 0
          ? 'linear-gradient(135deg, #f59e0b 0%, #d97706 100%)'
          : 'linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%)',
        color: 'white', padding: '1rem', display: 'flex', alignItems: 'center', gap: '0.75rem',
        transition: 'background 0.3s'
      }}>
        <button onClick={() => navigate('/dashboard')} style={{ background: 'none', border: 'none', color: 'white', cursor: 'pointer' }}>
          <ArrowLeft size={24} />
        </button>
        <Route size={20} />
        <h1 style={{ fontSize: '1.125rem', fontWeight: 700 }}>Minhas Rotas</h1>
        {pendingRoutes.length > 0 && (
          <div style={{
            display: 'flex', alignItems: 'center', gap: '0.5rem',
            marginLeft: 'auto', padding: '0.375rem 0.75rem',
            borderRadius: '9999px', background: 'rgba(255,255,255,0.25)',
            animation: 'pulse 1.5s ease-in-out infinite'
          }}>
            <Bell size={16} />
            <span style={{ fontSize: '0.8125rem', fontWeight: 600 }}>
              {pendingRoutes.length} rota{pendingRoutes.length > 1 ? 's' : ''} aguardando
            </span>
          </div>
        )}
      </header>

      <div style={{ padding: '1rem' }}>
        {/* Erro */}
        {error && (
          <div style={{ background: '#fef2f2', border: '1px solid #fecaca', color: '#dc2626', padding: '0.75rem', borderRadius: '0.5rem', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.875rem' }}>
            <AlertCircle size={16} /> {error}
            <button onClick={() => setError('')} style={{ marginLeft: 'auto', background: 'none', border: 'none', cursor: 'pointer', color: '#dc2626' }}><X size={16} /></button>
          </div>
        )}

        {/* Rotas Pendentes */}
        {pendingRoutes.length > 0 && (
          <div style={{ marginBottom: '1.5rem' }}>
            <h2 style={{ fontSize: '1rem', fontWeight: 600, color: '#1e293b', marginBottom: '0.75rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
              <Bell size={16} style={{ color: '#f59e0b' }} /> Aguardando Aceite
            </h2>
            {pendingRoutes.map(route => (
              <div key={route.id} style={{ background: 'white', borderRadius: '0.75rem', overflow: 'hidden', marginBottom: '0.75rem', boxShadow: '0 1px 3px rgba(0,0,0,0.05)', borderLeft: '4px solid #f59e0b' }}>
                <div style={{ padding: '1rem' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.75rem' }}>
                    <div>
                      <p style={{ fontWeight: 700, color: '#1e293b', fontSize: '1rem' }}>Rota #{route.id}</p>
                      <p style={{ fontSize: '0.75rem', color: '#64748b' }}>{route.stops_count} paradas</p>
                    </div>
                    <span style={{ padding: '0.25rem 0.75rem', borderRadius: '9999px', fontSize: '0.75rem', fontWeight: 600, background: '#fef3c7', color: '#92400e' }}>
                      Aguardando
                    </span>
                  </div>

                  {/* Preview das paradas */}
                  <div style={{ marginBottom: '0.75rem' }}>
                    {route.stops?.slice(0, 3).map((stop, idx) => (
                      <div key={stop.id} style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', padding: '0.25rem 0', fontSize: '0.8125rem', color: '#64748b' }}>
                        {getStopIcon(stop)}
                        <span style={{ fontSize: '0.625rem', padding: '0.125rem 0.25rem', borderRadius: '4px', background: stop.stop_type === 'PICKUP' ? '#fef3c7' : '#dbeafe', color: stop.stop_type === 'PICKUP' ? '#92400e' : '#1d4ed8' }}>
                          {getStopLabel(stop)}
                        </span>
                        <span style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{stop.address}</span>
                      </div>
                    ))}
                    {route.stops?.length > 3 && (
                      <p style={{ fontSize: '0.75rem', color: '#94a3b8', padding: '0.25rem 0' }}>+{route.stops.length - 3} mais paradas</p>
                    )}
                  </div>

                  <div style={{ display: 'flex', gap: '0.5rem' }}>
                    <button
                      onClick={() => acceptRoute(route.id)}
                      style={{ flex: 1, padding: '0.75rem', borderRadius: '0.5rem', border: 'none', background: '#16a34a', color: 'white', fontWeight: 600, cursor: 'pointer', fontSize: '0.875rem' }}
                    >
                      Aceitar Rota
                    </button>
                    <button
                      onClick={() => rejectRoute(route.id)}
                      style={{ padding: '0.75rem 1rem', borderRadius: '0.5rem', border: '1px solid #e2e8f0', background: 'white', color: '#64748b', fontWeight: 600, cursor: 'pointer', fontSize: '0.875rem' }}
                    >
                      Rejeitar
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Rotas Ativas */}
        {activeRoutes.length > 0 && (
          <div>
            <h2 style={{ fontSize: '1rem', fontWeight: 600, color: '#1e293b', marginBottom: '0.75rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
              <Bike size={16} style={{ color: '#2563eb' }} /> Em Andamento
            </h2>
            {activeRoutes.map(route => (
              <div key={route.id} style={{ background: 'white', borderRadius: '0.75rem', overflow: 'hidden', marginBottom: '0.75rem', boxShadow: '0 1px 3px rgba(0,0,0,0.05)', borderLeft: '4px solid #2563eb' }}>
                <div style={{ padding: '1rem', borderBottom: '1px solid #f1f5f9' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <div>
                      <p style={{ fontWeight: 700, color: '#1e293b', fontSize: '1rem' }}>Rota #{route.id}</p>
                      <p style={{ fontSize: '0.75rem', color: '#64748b' }}>
                        {route.stops?.filter(s => s.status === 'COMPLETED').length || 0} de {route.stops_count} concluídas
                      </p>
                    </div>
                    <span style={{ padding: '0.25rem 0.75rem', borderRadius: '9999px', fontSize: '0.75rem', fontWeight: 600, background: '#dbeafe', color: '#1d4ed8' }}>
                      Em Rota
                    </span>
                  </div>
                </div>

                {/* Paradas */}
                <div style={{ padding: '0.75rem 1rem' }}>
                  {route.stops?.map((stop, idx) => (
                    <div key={stop.id} style={{
                      display: 'flex', alignItems: 'center', gap: '0.75rem',
                      padding: '0.75rem', marginBottom: idx < route.stops.length - 1 ? '0.5rem' : 0,
                      background: stop.status === 'COMPLETED' ? '#f0fdf4' : '#f8fafc',
                      borderRadius: '0.5rem',
                      opacity: stop.status === 'COMPLETED' ? 0.7 : 1
                    }}>
                      <span style={{
                        width: '1.75rem', height: '1.75rem', borderRadius: '50%',
                        background: stop.status === 'COMPLETED' ? '#22c55e' : stop.stop_type === 'PICKUP' ? '#f59e0b' : '#2563eb',
                        color: 'white', display: 'flex', alignItems: 'center', justifyContent: 'center',
                        fontSize: '0.625rem', fontWeight: 600, flexShrink: 0
                      }}>
                        {stop.stop_order}
                      </span>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: '0.375rem', marginBottom: '0.125rem' }}>
                          <span style={{ fontSize: '0.5625rem', padding: '0.0625rem 0.25rem', borderRadius: '4px', background: stop.stop_type === 'PICKUP' ? '#fef3c7' : '#dbeafe', color: stop.stop_type === 'PICKUP' ? '#92400e' : '#1d4ed8' }}>
                            {getStopLabel(stop)}
                          </span>
                          <p style={{ fontSize: '0.8125rem', color: '#1e293b', fontWeight: 500, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                            {stop.address}
                          </p>
                        </div>
                        <p style={{ fontSize: '0.6875rem', color: '#64748b' }}>
                          {stop.customer_name} • Pedido #{stop.order_number}
                        </p>
                      </div>
                      {stop.status === 'COMPLETED' ? (
                        <CheckCircle size={18} style={{ color: '#22c55e', flexShrink: 0 }} />
                      ) : stop.stop_type === 'DELIVERY' ? (
                        <button
                          onClick={() => completeStop(route.id, stop.id)}
                          style={{
                            padding: '0.375rem 0.75rem', borderRadius: '0.375rem',
                            border: 'none', background: '#16a34a', color: 'white',
                            fontSize: '0.6875rem', fontWeight: 600, cursor: 'pointer',
                            flexShrink: 0
                          }}
                        >
                          Entregue
                        </button>
                      ) : (
                        <button
                          onClick={() => completeStop(route.id, stop.id)}
                          style={{
                            padding: '0.375rem 0.75rem', borderRadius: '0.375rem',
                            border: 'none', background: '#f59e0b', color: 'white',
                            fontSize: '0.6875rem', fontWeight: 600, cursor: 'pointer',
                            flexShrink: 0
                          }}
                        >
                          Coletado
                        </button>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Sem rotas */}
        {routes.length === 0 && (
          <div style={{ background: 'white', borderRadius: '0.75rem', padding: '2rem', textAlign: 'center', boxShadow: '0 1px 3px rgba(0,0,0,0.05)' }}>
            <Route size={48} style={{ color: '#64748b', marginBottom: '0.75rem' }} />
            <p style={{ fontWeight: 600, color: '#1e293b', fontSize: '1.125rem' }}>Nenhuma rota</p>
            <p style={{ color: '#64748b', marginTop: '0.5rem' }}>Você não tem rotas no momento</p>
          </div>
        )}
      </div>

      <style>{`
        @keyframes spin { to { transform: rotate(360deg); } }
        @keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.7; } }
      `}</style>
    </div>
  );
};

