          } catch (e) {}
          if (!instructions) return null;
          return (
            <div style={{ background: '#fffbeb', borderLeft: '3px solid #f59e0b', padding: '0.75rem 1rem', borderRadius: '0 0.375rem 0.375rem 0', marginBottom: '1rem', fontSize: '0.8125rem', color: '#92400e' }}>
              📝 {instructions}
