import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, AlertCircle, CheckCircle } from 'lucide-react';
import api from '@/lib/api';
import { utils } from '@/lib/api';
import DeliverySteps from './own-driver-delivery/DeliverySteps';
import DeliveryOrderInfo from './own-driver-delivery/DeliveryOrderInfo';
import DeliveryProof from './own-driver-delivery/DeliveryProof';
import CodeModal from './own-driver-delivery/CodeModal';

const STATUS_FLOW = [
  { key: 'ACCEPTED', label: 'Aceito', next: 'PICKED_UP', nextLabel: 'Coletar Pedido' },
  { key: 'PICKED_UP', label: 'A Caminho', next: 'DELIVERED', nextLabel: 'Confirmar Entrega' },
];

const OwnDriverDeliveryPage = () => {
  const { orderId } = useParams();
  const navigate = useNavigate();
  const [order, setOrder] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [updating, setUpdating] = useState(false);
  const [codeInput, setCodeInput] = useState('');
  const [showCodeModal, setShowCodeModal] = useState(false);
  const [nextStatus, setNextStatus] = useState('');
  const [proofPhoto, setProofPhoto] = useState(null);

  useEffect(() => {
    loadOrder();
  }, [orderId]);

  const loadOrder = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('own_driver_token');
      const headers = { Authorization: `Bearer ${token}` };
      const res = await api.get(`/api/own-driver/orders?status=all`, { headers });
      const found = res.data.orders.find(o => o.id === parseInt(orderId));
      if (found) {
        setOrder(found);
      } else {
        setError('Pedido não encontrado');
      }
    } catch (err) {
      setError('Erro ao carregar pedido');
    } finally {
      setLoading(false);
    }
  };

  const handleStatusUpdate = (status) => {
    setNextStatus(status);
    if (status === 'PICKED_UP' && order.pickup_code) {
      setShowCodeModal(true);
    } else if (status === 'DELIVERED' && order.delivery_code) {
      setShowCodeModal(true);
    } else {
      confirmStatusUpdate(status);
    }
  };

  const confirmStatusUpdate = async (status, code) => {
    try {
      setUpdating(true);
      setError('');
      const token = localStorage.getItem('own_driver_token');
      const headers = { Authorization: `Bearer ${token}` };

      let locationData = {};
      try {
        const pos = await new Promise((resolve, reject) => {
          navigator.geolocation.getCurrentPosition(resolve, reject, { timeout: 10000 });
        });
        locationData = {
          latitude: pos.coords.latitude,
          longitude: pos.coords.longitude
        };
      } catch (e) {
        // Sem localização
      }

      const payload = { status, ...locationData };
      if (code) {
        if (status === 'PICKED_UP') payload.pickup_code = code;
        if (status === 'DELIVERED') payload.delivery_code = code;
      }
      if (status === 'DELIVERED' && proofPhoto) {
        payload.proof_of_delivery = proofPhoto;
      }

      const res = await api.put(`/api/own-driver/orders/${orderId}/status`, payload, { headers });
      setOrder(res.data.order);
      setShowCodeModal(false);
      setCodeInput('');

      if (status === 'DELIVERED') {
        setTimeout(() => navigate('/own-driver'), 2000);
      }
    } catch (err) {
      setError(err.response?.data?.error || 'Erro ao atualizar status');
    } finally {
      setUpdating(false);
    }
  };

  const handleTakePhoto = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.capture = 'environment';
    input.onchange = (e) => {
      const file = e.target.files[0];
      if (file) {
        const reader = new FileReader();
        reader.onload = (ev) => {
          setProofPhoto(ev.target.result);
        };
        reader.readAsDataURL(file);
      }
    };
    input.click();
  };

  const openNavigation = () => {
    const addr = order.delivery_address;
    if (addr?.latitude && addr?.longitude) {
      const isMobile = /Android|iPhone|iPad|iPod/i.test(navigator.userAgent);
      if (isMobile) {
        const useWaze = window.confirm('Abrir no Waze?\n\nCancelar = Google Maps');
        if (useWaze) {
          window.open(`https://www.waze.com/ul?ll=${addr.latitude},${addr.longitude}&navigate=yes`, '_blank');
        } else {
          window.open(`https://www.google.com/maps/dir/?api=1&destination=${addr.latitude},${addr.longitude}`, '_blank');
        }
      } else {
        window.open(`https://www.google.com/maps/dir/?api=1&destination=${addr.latitude},${addr.longitude}`, '_blank');
      }
    } else if (addr?.street) {
      const query = encodeURIComponent(`${addr.street}, ${addr.neighborhood || ''}, ${addr.city || ''}`);
      window.open(`https://www.google.com/maps/dir/?api=1&destination=${query}`, '_blank');
    }
  };

  if (loading) {
    return (
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: '#f1f5f9' }}>
        <div style={{ width: '3rem', height: '3rem', border: '3px solid #e2e8f0', borderTopColor: '#0d9488', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
        <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
      </div>
    );
  }

  if (!order) {
    return (
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: '#f1f5f9' }}>
        <p style={{ color: '#64748b' }}>Pedido não encontrado</p>
      </div>
    );
  }

  const isDelivered = order.status === 'DELIVERED';
  const currentStep = STATUS_FLOW.find(s => s.key === order.status);
  const canAdvance = currentStep && !isDelivered;

  return (
    <div style={{ minHeight: '100vh', background: '#f1f5f9' }}>
      {/* Header */}
      <header style={{
        background: 'linear-gradient(135deg, #0d9488 0%, #0f766e 100%)',
        color: 'white', padding: '1rem', display: 'flex', alignItems: 'center', gap: '0.75rem'
      }}>
        <button onClick={() => navigate('/own-driver')} style={{ background: 'none', border: 'none', color: 'white', cursor: 'pointer' }}>
          <ArrowLeft size={24} />
        </button>
        <div>
          <h1 style={{ fontSize: '1.125rem', fontWeight: 700 }}>Pedido #{order.order_number}</h1>
          <p style={{ fontSize: '0.75rem', opacity: 0.8 }}>{utils.formatDateTime(order.created_at)}</p>
        </div>
      </header>

      <div style={{ padding: '1rem', maxWidth: '600px', margin: '0 auto' }}>
        {/* Erro */}
        {error && (
          <div style={{
            background: '#fef2f2', border: '1px solid #fecaca', color: '#dc2626',
            padding: '0.75rem 1rem', borderRadius: '0.5rem', marginBottom: '1rem',
            display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.875rem'
          }}>
            <AlertCircle size={16} /> {error}
          </div>
        )}

        <DeliverySteps status={order.status} />

        <DeliveryOrderInfo
          order={order}
          isDelivered={isDelivered}
          onOpenNavigation={openNavigation}
        />

        {order.status === 'PICKED_UP' && (
          <DeliveryProof
            proofPhoto={proofPhoto}
            onTakePhoto={handleTakePhoto}
            onRemovePhoto={() => setProofPhoto(null)}
          />
        )}

        {/* Botão de Ação Principal */}
        {canAdvance && (
          <button
            onClick={() => handleStatusUpdate(currentStep.next)}
            disabled={updating}
            style={{
              width: '100%', padding: '1rem', borderRadius: '0.75rem',
              border: 'none', background: '#0d9488', color: 'white',
              fontSize: '1.125rem', fontWeight: 700, cursor: updating ? 'not-allowed' : 'pointer',
              opacity: updating ? 0.7 : 1, boxShadow: '0 4px 14px rgba(13, 148, 136, 0.3)',
              display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem'
            }}
          >
            {updating ? 'Atualizando...' : currentStep.nextLabel}
          </button>
        )}

        {isDelivered && (
          <div style={{
            background: '#dcfce7', borderRadius: '0.75rem', padding: '1.5rem',
            textAlign: 'center', boxShadow: '0 1px 3px rgba(0,0,0,0.05)'
          }}>
            <CheckCircle size={40} style={{ color: '#22c55e', marginBottom: '0.5rem' }} />
            <p style={{ fontSize: '1.125rem', fontWeight: 700, color: '#166534' }}>Entrega Concluída!</p>
            <p style={{ fontSize: '0.875rem', color: '#15803d', marginTop: '0.25rem' }}>
              {order.delivery_time ? utils.formatDateTime(order.delivery_time) : 'Agora'}
            </p>
          </div>
        )}
      </div>

      {showCodeModal && (
        <CodeModal
          nextStatus={nextStatus}
          codeInput={codeInput}
          onCodeChange={setCodeInput}
          onConfirm={() => confirmStatusUpdate(nextStatus, codeInput)}
          onClose={() => { setShowCodeModal(false); setCodeInput(''); }}
          updating={updating}
        />
      )}
    </div>
  );
};

export default OwnDriverDeliveryPage;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  DollarSign, ArrowLeft, Clock, CheckCircle, Package, Filter, AlertCircle,
  Wallet, CreditCard, Settings
} from 'lucide-react';
import api from '@/lib/api';
import { utils } from '@/lib/api';

const OwnDriverEarningsPage = () => {
  const navigate = useNavigate();
  const [earnings, setEarnings] = useState([]);
  const [summary, setSummary] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [period, setPeriod] = useState('month');
  const [showPixModal, setShowPixModal] = useState(false);
  const [pixKey, setPixKey] = useState('');
  const [withdrawing, setWithdrawing] = useState(false);

  useEffect(() => { loadEarnings(); }, [period]);

  const loadEarnings = async () => {
    try {
      setLoading(true);
      setError('');
      const token = localStorage.getItem('own_driver_token');
      const headers = { Authorization: `Bearer ${token}` };
      const res = await api.get(`/api/own-driver/earnings?period=${period}`, { headers });
      setEarnings(res.data.earnings || []);
      setSummary(res.data.summary || {});
    } catch (err) {
      console.error('Erro ao carregar ganhos:', err);
      if (err.response?.status === 401) {
        localStorage.removeItem('own_driver_token');
        navigate('/own-driver/login');
        return;
      }
      setError('Erro ao carregar ganhos. Tente novamente.');
    } finally {
      setLoading(false);
    }
  };

  const handleWithdraw = async () => {
    if (!window.confirm('Solicitar saque de todos os ganhos pendentes?')) return;
    
    try {
      setWithdrawing(true);
      setError('');
      const token = localStorage.getItem('own_driver_token');
      const headers = { Authorization: `Bearer ${token}` };
      const res = await api.post('/api/own-driver/withdraw', {}, { headers });
      setSuccess(res.data.message);
      setTimeout(() => setSuccess(''), 5000);
      loadEarnings();
    } catch (err) {
      setError(err.response?.data?.error || 'Erro ao solicitar saque');
    } finally {
      setWithdrawing(false);
    }
  };

  const handleUpdatePix = async () => {
    if (!pixKey.trim()) {
      setError('Informe uma chave PIX');
      return;
    }
    try {
      setError('');
      const token = localStorage.getItem('own_driver_token');
      const headers = { Authorization: `Bearer ${token}` };
      await api.put('/api/own-driver/pix-key', { pix_key: pixKey }, { headers });
      setSuccess('Chave PIX atualizada!');
      setShowPixModal(false);
      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      setError(err.response?.data?.error || 'Erro ao atualizar PIX');
    }
  };

  return (
    <div style={{ minHeight: '100vh', background: '#f1f5f9' }}>
      {/* Header */}
      <header style={{
        background: 'linear-gradient(135deg, #0d9488 0%, #0f766e 100%)',
        color: 'white', padding: '1rem', display: 'flex', alignItems: 'center', gap: '0.75rem'
      }}>
        <button onClick={() => navigate('/own-driver')} style={{ background: 'none', border: 'none', color: 'white', cursor: 'pointer' }}>
          <ArrowLeft size={24} />
        </button>
        <h1 style={{ fontSize: '1.125rem', fontWeight: 700 }}>Meus Ganhos</h1>
      </header>

      <div style={{ padding: '1rem', maxWidth: '600px', margin: '0 auto' }}>
        {/* Erro */}
        {error && (
          <div style={{
            background: '#fef2f2', border: '1px solid #fecaca', color: '#dc2626',
            padding: '0.75rem 1rem', borderRadius: '0.5rem', marginBottom: '1rem',
            display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.875rem'
          }}>
            <AlertCircle size={16} /> {error}
          </div>
        )}
        
        {/* Sucesso */}
        {success && (
          <div style={{
            background: '#f0fdf4', border: '1px solid #bbf7d0', color: '#166534',
            padding: '0.75rem 1rem', borderRadius: '0.5rem', marginBottom: '1rem',
            display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.875rem'
          }}>
            <CheckCircle size={16} /> {success}
          </div>
        )}

        {/* Cards de Resumo */}
        {summary && (
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.75rem', marginBottom: '1rem' }}>
            <div style={{
              background: 'linear-gradient(135deg, #0d9488 0%, #0f766e 100%)',
              borderRadius: '0.75rem', padding: '1.25rem', color: 'white'
            }}>
              <p style={{ fontSize: '0.75rem', opacity: 0.8, marginBottom: '0.25rem' }}>Total Ganhos</p>
              <p style={{ fontSize: '1.5rem', fontWeight: 700 }}>{utils.formatCurrency(summary.total || 0)}</p>
            </div>
            <div style={{
              background: 'white', borderRadius: '0.75rem', padding: '1.25rem',
              boxShadow: '0 1px 3px rgba(0,0,0,0.05)'
            }}>
              <p style={{ fontSize: '0.75rem', color: '#64748b', marginBottom: '0.25rem' }}>Pendente</p>
              <p style={{ fontSize: '1.5rem', fontWeight: 700, color: '#f59e0b' }}>
                {utils.formatCurrency(summary.pending || 0)}
              </p>
            </div>
          </div>
        )}

        {/* Botões de Ação */}
        <div style={{ display: 'flex', gap: '0.75rem', marginBottom: '1rem' }}>
          <button
            onClick={handleWithdraw}
            disabled={withdrawing || !summary?.pending || summary.pending <= 0}
            style={{
              flex: 1, padding: '0.75rem', borderRadius: '0.5rem', border: 'none',
              background: summary?.pending > 0 ? '#059669' : '#94a3b8',
              color: 'white', fontWeight: 600, fontSize: '0.875rem',
              cursor: summary?.pending > 0 ? 'pointer' : 'not-allowed',
              display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem'
            }}
          >
            <Wallet size={18} />
            {withdrawing ? 'Processando...' : 'Solicitar Saque'}
          </button>
          <button
            onClick={() => setShowPixModal(true)}
            style={{
              padding: '0.75rem 1rem', borderRadius: '0.5rem',
              border: '1.5px solid #e2e8f0', background: 'white',
              color: '#374151', fontWeight: 500, fontSize: '0.875rem',
              cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '0.5rem'
            }}
          >
            <Settings size={18} /> PIX
          </button>
        </div>

        {/* Filtro de Período */}
        <div style={{
          display: 'flex', gap: '0.5rem', marginBottom: '1rem'
        }}>
          {[
            { key: 'day', label: 'Hoje' },
            { key: 'week', label: 'Semana' },
            { key: 'month', label: 'Mês' }
          ].map(f => (
            <button
              key={f.key}
              onClick={() => setPeriod(f.key)}
              style={{
                padding: '0.5rem 1rem', borderRadius: '9999px', border: 'none',
                background: period === f.key ? '#0d9488' : 'white',
                color: period === f.key ? 'white' : '#64748b',
                fontSize: '0.8125rem', fontWeight: 500, cursor: 'pointer',
                boxShadow: '0 1px 2px rgba(0,0,0,0.05)'
              }}
            >
              {f.label}
            </button>
          ))}
        </div>

        {/* Lista de Ganhos */}
        {loading ? (
          <div style={{ display: 'flex', justifyContent: 'center', padding: '3rem' }}>
            <div style={{ width: '2rem', height: '2rem', border: '3px solid #e2e8f0', borderTopColor: '#0d9488', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
            <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
          </div>
        ) : earnings.length === 0 ? (
          <div style={{
            background: 'white', borderRadius: '0.75rem', padding: '2rem',
            textAlign: 'center', boxShadow: '0 1px 3px rgba(0,0,0,0.05)'
          }}>
            <DollarSign size={40} style={{ color: '#64748b', marginBottom: '0.75rem' }} />
            <p style={{ fontWeight: 600, color: '#1e293b' }}>Nenhum ganho neste período</p>
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
            {earnings.map(earning => (
              <div
                key={earning.id}
                style={{
                  background: 'white', borderRadius: '0.75rem', padding: '1rem',
                  boxShadow: '0 1px 3px rgba(0,0,0,0.05)'
                }}
              >
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.5rem' }}>
                  <span style={{ fontWeight: 600, color: '#1e293b', fontSize: '0.9375rem' }}>
                    #{earning.order_number}
                  </span>
                  <span style={{
                    padding: '0.125rem 0.5rem', borderRadius: '9999px',
                    fontSize: '0.6875rem', fontWeight: 600,
                    background: earning.is_paid ? '#dcfce7' : '#fef3c7',
                    color: earning.is_paid ? '#16a34a' : '#92400e'
                  }}>
                    {earning.is_paid ? 'Pago' : 'Pendente'}
                  </span>
                </div>

                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <div style={{ fontSize: '0.8125rem', color: '#64748b' }}>
                    <span>Frete: {utils.formatCurrency(earning.delivery_fee)}</span>
                    {earning.distance_km > 0 && (
                      <span style={{ marginLeft: '0.5rem' }}>• {earning.distance_km} km</span>
                    )}
                  </div>
                  <span style={{ fontSize: '1.125rem', fontWeight: 700, color: '#16a34a' }}>
                    +{utils.formatCurrency(earning.driver_earning)}
                  </span>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Modal PIX */}
      {showPixModal && (
        <div style={{ position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
          <div style={{ background: 'white', borderRadius: '0.75rem', padding: '1.5rem', width: '100%', maxWidth: '400px', margin: '1rem' }}>
            <h3 style={{ fontSize: '1.125rem', fontWeight: 700, color: '#1e293b', marginBottom: '1rem' }}>
              Configurar Chave PIX
            </h3>
            <p style={{ fontSize: '0.875rem', color: '#64748b', marginBottom: '1rem' }}>
              Cadastre sua chave PIX para receber os saques.
            </p>
            <input
              type="text"
              value={pixKey}
              onChange={e => setPixKey(e.target.value)}
              placeholder="CPF, CNPJ, email, telefone ou chave aleatória"
              style={{
                width: '100%', padding: '0.75rem', borderRadius: '0.5rem',
                border: '1.5px solid #e2e8f0', fontSize: '0.875rem', marginBottom: '1rem',
                boxSizing: 'border-box'
              }}
            />
            <div style={{ display: 'flex', gap: '0.75rem', justifyContent: 'flex-end' }}>
              <button
                onClick={() => setShowPixModal(false)}
                style={{ padding: '0.625rem 1.25rem', borderRadius: '0.5rem', border: '1.5px solid #e2e8f0', background: 'white', color: '#374151', fontSize: '0.875rem', cursor: 'pointer' }}
              >
                Cancelar
              </button>
              <button
                onClick={handleUpdatePix}
                style={{ padding: '0.625rem 1.25rem', borderRadius: '0.5rem', border: 'none', background: '#0d9488', color: 'white', fontSize: '0.875rem', fontWeight: 600, cursor: 'pointer' }}
              >
                Salvar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

