import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Package, ArrowLeft, MapPin, Clock, CheckCircle, Bike, DollarSign, AlertCircle
} from 'lucide-react';
import api from '@/lib/api';
